window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_015"]={"n":"释函是","dyn":"明","poems":[{"t":"春佃六首 其一","f":"五言古诗","c":["幽谷逢春至，蔼然鬯予情。","江流日以长，山鸟时一鸣。","重云蔽群木，冥蒙遂所生。","斯人独不然，耳目馀聪明。","万物纷其前，安得返无名。","役役百年中，毁誉争虚声。","何不乘青阳，优游同耦耕。","旷观古与今，贤智多无成。","惜此荷锄人，来往空生平。"]},{"t":"春佃六首 其二","f":"五言古诗","c":["久雨不敢厌，有事在西畴。","戴笠随人行，望望荒山丘。","春风吹我衣，飘然忘去留。","爱彼绿遍野，远近驰双眸。","试问往来者，知我心中否。","与尔情均同，所异能不忧。","饱煖百念灰，饥寒岂无求。"]},{"t":"春佃六首 其三","f":"五言古诗","c":["一身寄天地，生事随人间。","山泽吾自为，勤苦有馀闲。","乐道当如是，名誉匪所干。","招隐愧郑谷，矜贫薄袁安。","饥渴苟可支，泉石足忘年。","春林生意满，心逐禽鱼欢。","种蔬不待暖，布谷畏犹寒。","去年瓜豆迟，野羹良辛酸。","万事须及时，岂但耕锄然。"]},{"t":"春佃六首 其四","f":"五言古诗","c":["新晴喜见日，微风荡青林。","弱柳未成条，雏莺试好音。","和气彻上下，奇怀发良晨。","挈象观初苗，终岁赖不贫。","所欲亦易足，俯仰无馀心。","倦归茅檐下，读书思古人。","黄虞讵关世，安知不如今。","出户望空远，高山临星辰。"]},{"t":"春佃六首 其五","f":"五言古诗","c":["谷风寒不栗，山日多所欣。","泉声远近别，深浅绿畦分。","燕归寻先巢，去雁不成群。","大小农事忙，谁与观斯晨。","好事悦予怀，闲情惭昔人。","自知景物同，老兴聊云云。","莫言世如幻，幻中良有真。","澄江摇古木，怪石羂春云。"]},{"t":"春佃六首 其六","f":"五言古诗","c":["甲子行当健，今春逾往年。","日食几一升，颂诗尝百篇。","措心无他营，所慕维耕田。","贫贱固其分，畎亩诚多贤。","燕逸岂不娱，揣己难为安。","迩因老且病，众务惭身先。","徒以口舌劳，兀傲谁与怜。","君子贵自处，吾亦非苟然。"]},{"t":"过泐山","f":"五言古诗","c":["寒山有佳色，理策临清漪。","倚棹过绿玉，将以观冬犁。","舍舟登古岸，髣髴玉渊时。","所异谷与川，动静各有宜。","停步稍顾盼，抚景心相随。","遥遥望石门，双峰一径微。","梯穷万山出，忽然就长堤。","土屋三两间，依岩缚茅茨。","爨烟穿石窦，云影随高低。","下有丹溜潭，水落松风吹。","泠泠潭上人，分明见须眉。","乐此毕生平，耕锄复何辞。","古者食其力，辛苦当为谁。","日暮且归去，明春予再来。"]},{"t":"沈秀才融谷入山","f":"五言古诗","c":["何人江上来，面目清如水。","遥遥向石门，寻我万山里。","岩前青林舒，衣上白云起。","读书破万卷，相对难为似。","岂不释世纷，渊明曾一仕。","但存霜雪心，迟尔十年耳。","张灯酌流泉，寒燄入杯泚。","杯影与壁光，毕竟何者是。","言穷神自会，他时须记此。"]},{"t":"次韵答杨伊水","f":"五言律诗","c":["竹院逢君处，相看古道存。","从来无剩法，惭愧独称尊。","新月窥人影，寒鸦代我言。","更寻晴雪夜，移榻破云痕。"]},{"t":"晚登风幡阁","f":"五言律诗","c":["望处江山旧，凭高独怆然。","曾随章贡水，直抵秣陵天。","六月溪楼上，三年樵舍前。","风光今夕异，抚景倍流连。"]},{"t":"出诃林闻罗季作讣","f":"五言律诗","c":["别子方三月，倏然成古人。","谁知昔日诺，空结再生因。","侠骨终难副，诗情孤绝邻。","穷交看欲尽，横泗独沾巾。"]},{"t":"王园长侍郎入山","f":"五言律诗","c":["破寺寻僧至，呼名尚俨然。","座中今日意，石上旧时缘。","榾柮烧寒雨，髼松坐暝烟。","干戈犹满目，珍重惜馀年。"]},{"t":"归过石涧","f":"五言律诗","c":["别有一天地，巉岩路不穷。","白云扶怪石，碧涧浸寒空。","杖屦虚无际，林峦杳霭中。","归途情更慊，习习起东风。"]},{"t":"九日登三老峰","f":"五言律诗","c":["叶落万山紫，披云信短筇。","恰逢重九日，独上最高峰。","海色连秋汉，风声杂晚钟。","黄花今又醉，犹是去年侬。"]},{"t":"转禅病出诃林","f":"五言律诗","c":["久病伤为客，寒虫候月艰。","三冬诃子舍，八载荔枝山。","始觉浮生促，深知平日閒。","近思芦服味，念汝海云间。"]},{"t":"示阿字","f":"五言律诗","c":["大道无人识，微言为尔开。","白云将眼去，明月照心来。","坐落西风夜，行冥古径苔。","嗒然天地外，相见一悠哉。"]},{"t":"闻秋风寄即觉","f":"五言律诗","c":["六月秋风起，行人知不知。","何须梧叶尽，方觉雁声悲。","北地稻粱早，南湖菰米迟。","归山霜未降，更勿滞佳期。"]},{"t":"悼袁特丘中丞四首 其一","f":"五言律诗","c":["凶信疑难定，书来始觉真。","十年师弟意，一旦古今人。","老死非所讳，因缘不可陈。","精魂何处觅，未易忆前身。"]},{"t":"悼袁特丘中丞四首 其二","f":"五言律诗","c":["易别成辜负，多时恨未收。","匡山从昔峙，楚水至今流。","我隐何曾隐，君休竟不休。","此生堪几误，惭望武昌楼。"]},{"t":"悼袁特丘中丞四首 其三","f":"五言律诗","c":["长生不可学，但愿莫长离。","解语人难再，多情我易悲。","遣怀怜旧好，悼往惜今时。","相续他生事，论因亦自知。"]},{"t":"悼袁特丘中丞四首 其四","f":"五言律诗","c":["而媳师吾妹，能参出世禅。","及门多割爱，岐路叹前缘。","任运元无住，千生总偶然。","忧伤唯我佛，底事未堪诠。"]},{"t":"与角子夜话怀姜山江宁二首 其一","f":"五言律诗","c":["相对复何语，灯摇此夕情。","无心居野寺，有梦到江城。","恩在身名重，缘抛道谊轻。","谁当信畴昔，期尔尽生平。"]},{"t":"与角子夜话怀姜山江宁二首 其二","f":"五言律诗","c":["未尽今宵意，难为千里心。","残莺啼短烛，细雨滴离襟。","旧话怜当日，新愁起夕吟。","白门何处院，笠影动城阴。"]},{"t":"悼旋庵湛都寺六首 其一","f":"五言律诗","c":["不敢为人累，心孤意自阑。","谊衰知道丧，时迈觉情寒。","社燕辞霜白，秋鸿叫树丹。","每因朝露委，都作暮龄看。"]},{"t":"悼旋庵湛都寺六首 其二","f":"五言律诗","c":["华陀不可学，把药泣涟洏。","尽意起遥夜，论心限此时。","达生嫌世薄，问卜爱人痴。","门外西风急，披襟信步迟。"]},{"t":"悼旋庵湛都寺六首 其三","f":"五言律诗","c":["人情今古尽，夕月与朝烟。","好客常终日，挥金信一拳。","岂堪分水乳，容易论因缘。","已矣真风邈，予当远石泉。"]},{"t":"悼旋庵湛都寺六首 其四","f":"五言律诗","c":["万里秋山好，凋零逼岁除。","晴空填翠黛，碧汉挂蟾蜍。","草树无常色，光辉亦暂舒。","悠悠尘世里，谁独爱吾庐。"]},{"t":"辛酉元夜吟","f":"五言律诗","c":["世上真如梦，兴来閒一吟。","明灯过午夜，独坐拥寒襟。","大泽龙蛇蛰，高峰霜雪深。","峄阳有孤树，爨下亦成音。"]},{"t":"尹恒复中秘见过","f":"七言律诗","c":["频年转战知交尽，相对真疑梦里人。","心淡自应廉吏后，时危曾现宰官身。","趋庭有子能娱老，避世寻僧得正因。","开士渐推莲社长，罗浮今亦有遗民。"]},{"t":"丹霞诗十二首 其三 望长老峰","f":"七言律诗","c":["万丈孤危在目前，亭亭不与众山缘。","但看八面无行地，想见中峰直到天。","远近云峦供怪石，浅深沙碛绕晴川。","宝华王座当空倚，路滑还他长老禅。"]},{"t":"忆过姑苏","f":"七言律诗","c":["西风散发阖闾城，回首姑苏泪暗生。","孤客不知他日恨，旅怀空怆昔人情。","秋高叶落吴门冷，夜半潮生海月明。","三十年来吟望处，江湖缭绕暮云平。"]},{"t":"寄熊内阁齐云山中","f":"七言绝句","c":["富贵功名梦里人，谁知苦乐正相邻。","回头大有甘心处，须信身贫道未贫。"]},{"t":"入齐云","f":"七言绝句","c":["深山高卧白云屯，閒听林莺尽日喧。","不为痴呆宁有此，肝肠空向石头论。"]},{"t":"白云谣","f":"五言古诗","c":["昆崙在人间，盼望疑青霄。","盈盈瑶池觞，良遘忽崇朝。","旦暮不可再，白云空迢迢。","王者岂真乐，仙人徒见招。","悠远非山川，举足抟扶摇。","叹息古今事，犹传天子谣。"]},{"t":"周穆王答歌","f":"五言古诗","c":["玉台距东土，一瞬分天人。","予归岂勿顾，诸夏多人民。","含餔帝力忘，百姓谁疏亲。","觌面看踌躇，万年犹若今。","袅袅瑶流响，亭亭玄圃云。","相见不相知，迢遥空梦魂。","抗手谢青鸟，毋劳翘昆崙。"]},{"t":"紫芝歌","f":"五言古诗","c":["高山高可极，深谷深可至。","中有四皓者，采芝避秦始。","作歌以忘年，蒲轮安足致。","富贵良多忧，贫贱乃肆志。","天下而既定，汉高徵不出。","亡匿曾几时，竟为孝惠侍。","古今竞相传，皆仰留侯智。","青松与白云，商山今尚在。"]},{"t":"可以终隐二章章十句","f":"古风","c":["可以终隐，哀我后人。","可以终默，谁迪先民。","毋尚孤洁，任其爱瞋。","四众之式，不淄不磷。","深心坚忍，尽未来身。","内无系念，外无长物。","一瓶一钵，一杖一笠。","要行便行，要住便住。","无愧古人，无欺后嗣。","慎乃典型，永垂来祀。"]},{"t":"圣人一章章十句","f":"古风","c":["圣人无己，谁当宝几。","万象体玄，圆鉴自尔。","缘感普周，而恒处此。","慎汝后昆，勿立规矩。"]},{"t":"题观音大士像三首 其一","f":"古风","c":["智绝真空，体应群物。","物岂他物，有感斯通。","空非顽空，无远弗届。","来无所从，去无所至。","苦乐如梦，觉迷一致。","秖此深慈，弗休弗憩。","是故稽首，观音大士。"]},{"t":"题观音大士像三首 其二","f":"古风","c":["大士如镜，照一切心。","大士如月，清光普临。","万象历历，随感而寂。","慈能摄慢，悲以化执。","机器靡定，同归静正。","但办肯心，何疑于圣。","我昔早年，将悟未悟。","稽首皈诚，曾获冥护。","梦里投机，如箭锋拄。","宾主出入，有语无语。","越三十年，宛尔昨日。","凡一念至，铁与磁石。","愿汝小子，但坚信此。"]},{"t":"题观音大士像三首 其三","f":"古风","c":["大士灵通，多在忍土。","以无缘慈，哀五浊苦。","感应道交，如子得母。","水中月影，非去非到。","空谷响声，前后之步。","我以心眼，观大士处。","几丧目前，而哑然住。","能非所观，所非能觑。","绝待而歔，有语无语。","以示禅者，如箭锋拄。","俯仰折旋，无容顾伫。","信口而呼，纵目所注。","神光俨然，不可思虑。","大悲观音，为物作矩。","共此未来，皈命顶礼。"]},{"t":"观音大士赞","f":"楚辞体","c":["仰吾师之深慈兮，置十二类生于怀中。","随所求而各给兮，知根欲之无穷。","天与人之不可顿易兮，聊止啼以黄叶。","妄无体而必终兮，尔乃需之情竭。","望东方之既白兮，犹濛濛其复晦。","同乎迷若相濡兮，谁独当机感之会。","入大冶而不自知兮，感天泽之一勺。","时忽构而顿醒兮，悔从前之昧略。","顾吾身之独遭兮，几旦暮而失之。","觉而后知其将告兮，叹虚白之靡移。","匪覃恩之浪浪兮，孰执手而同归。","底乾慧而极果兮，誓始终而相师。","释及门之洗心兮，礼顶踵而陈词。"]},{"t":"题本师空和尚真","f":"楚辞体","c":["明镜当台兮，曜神光乎夜堂。","西飙栗冽兮，蘸秋水之杲阳。","望俨慈氏兮，近之而不可狎。","荡荡乎博峤之遗风兮，当其机而知石头路滑。","悲晚近之羊质兮，尚虎皮之灿灿。","侈炎日之峻步兮，宁深云之泛泛。","念石住之微言兮，余小子犹虔虔坐以待旦。"]},{"t":"题拄杖二首 其一","f":"楚辞体","c":["年既迈而弗衰兮，壮力由伊。","予亦因高下以相谐兮，岂旦暮之能离。","著地兮荆披，撑空兮云随。","直趋兮不顾，运足兮自知。","追前烈兮，启后武兮，将舍是焉其谁。"]},{"t":"题拄杖二首 其二","f":"楚辞体","c":["我凭汝力，汝得我立。","汝我兮同心，不可转兮匪石。","绝夷险以进止兮，遵先贤之遗轶。","行终古而勿替兮，挈斯人以跻乎峻极。"]},{"t":"箜篌引","f":"五言古诗","c":["北风何凄凄，吹我百衲衣。","膏雨何霏霏，泽我西山薇。","披衣可禦寒，采薇聊充饥。","顾影成独立，无俦终怨谁。","登高眺远空，心与空俱驰。","空里有江山，江山多是非。","是非靡所穷，我心归无期。","忽然返蓬庐，还我未登时。","读书晤古人，将以娱心脾。","叔夜不偶俗，东市良堪悲。","夜闻鼓琴声，形神离不离。","鲍公谓尸解，此语至今疑。","子房已辞汉，竟为帝王师。","文若似子房，事曹欲何为。","严辞折董昭，饮药甘如饴。","各自用其天，身世犹云霓。","生死不足畏，人心焉能知。"]},{"t":"江南","f":"五言古诗","c":["江南有羁客，朝夕望不返。","柳衰寒花黄，狂风吠山犬。","潜颖欣青阳，眼见红复浅。","浮云弥太虚，河水日沔沔。","车盖填道路，相识非我善。","臭味自有真，岂以夙昔舛。","夕霞流停曜，圆景媚新畚。","仰观众鸟喧，使我中情远。","不畏新知乐，秖忧相见晚。"]},{"t":"薤露","f":"五言古诗","c":["薤叶难停露，露停乾复乾。","人一去不来，何不蚤盘桓。","富贵期延龄，贫贱忧饥寒。","饥寒未即死，延龄先摧残。","金石常误人，神物不可攒。","形容终逮化，有无吾自观。","纷寂竟何待，愚智空目前。","勿以春花落，哀哀盈陌阡。"]},{"t":"蒿里","f":"五言古诗","c":["送送别蒿里，游魂向何方。","荣名耀当世，宝玉悬中堂。","宾从临高坟，子孙哭两傍。","黄泉无贵客，不如贫贱良。","贱士营身薄，观化同雪霜。","蚤将近死心，万感皆荒唐。","近死心不死，年年冬夜长。","劝君莫忧贫，但看死贵人。"]},{"t":"平陵东","f":"五言古诗","c":["平陵东道傍，松柏不可久。","狗自入中庭，断齧群雁首。","群雁亦孔伤，狗向门外走。","祸福岂足问，空名其何有。","火照未央宫，十万伊谁负。","人或哀其心，安知皆夙取。","歔嗟卖黄犊，不为薄为厚。"]},{"t":"长歌行二首 其一","f":"五言古诗","c":["寒日照旸谷，渐中光乃舒。","光舒寒色敛，万物承欢娱。","日入松景促，猋风集吾庐。","气序有变化，此理无同殊。","鄙夫鲜克终，贤士慎厥初。","心节不可渝，宠眷从戚疏。","所矢定夙昔，生死安须臾。","周公感风雷，岂在蔡叔诛。","孺子终不悟，金縢胡为乎。","忠佞为自知，讵更问荣枯。","荣枯自天泽，消息还江湖。","明昧任宵旦，寒煦观乘除。","身名付天下，吾心安可诬。"]},{"t":"长歌行二首 其二","f":"五言古诗","c":["虑远百年短，情捐一夕长。","忧时问牛喘，遗身调象狂。","彼此不相知，论绪若参商。","但观三春泽，转盼成秋霜。","时雨不终宵，驱云乘朝阳。","天既不可测，人亦何能量。","先主称仁后，顾托誓不忘。","恢土限益州，竟以危刘璋。","宁我负天下，孟德真豺狼。","忍心杀文举，厚遇关云长。","慈暴出入机，善恶岂有常。","利欲从中来，一滴溃川坊。","事理谁合离，寤寐各弛张。","形神互主宾，断续趋彭殇。","茫茫世上人，买药诬韩康。"]},{"t":"相逢行","f":"五言古诗","c":["仗剑走平原，结客少年场。","冲突烟尘里，横戈枕长杨。","金盔换美酒，击筑官路傍。","忽驰大将檄，扶醉骋鞭缰。","慷慨誓捐躯，神武威八方。","饮马长城窟，悲歌动杞梁。","功成万骨枯，谁复念玄黄。","凯旋宴太平，王侯册朝堂。","万骑绕辕门，云旗摇日光。","叹息游侠儿，一朝名播扬。","走卒无白衣，夹路皆笙簧。","夜饮彻晨鸡，银烛照垂珰。","梦里见单骑，插羽驰君王。","方悔飞鸟尽，良弓不善藏。","慑慑荡神魂，觉后犹徬徨。","此岂平日心，自古多奇殃。","富贵人侧目，不如归故乡。","故乡有宗族，长幼携相望。","卖剑买黄犊，畎亩追羲皇。","农隙课子孙，诗书出贤良。","贤良知外物，身世能两忘。","荣华鲜克终，宁澹性乃常。"]},{"t":"陇西行","f":"五言古诗","c":["世岂无贤才，识寡昧所从。","遂令当路子，低昂槃涧中。","自昔重华氏，畎亩行将终。","吕望钓渭川，八十守固穷。","苟无唐与周，高栖竟乔松。","许由藉神尧，千载景遐风。","隐显恒因人，名实无异同。","贤圣不逢时，形迹如飘蓬。","揽辔遍中野，所见多樵农。"]},{"t":"东门行","f":"五言古诗","c":["相送出东门，生死各不知。","人生匪金石，保有重会期。","酌酒尽今夕，中心多所悲。","新好讵勿谐，猥未经岁时。","倾盖难如故，百然犹一疑。","风雨复晴霁，白日成阴霾。","眷言怀夙昔，始终思旧知。","往见管鲍交，旷久情易移。","岂况千万里，寒暑更相违。","此语安可道，默默空自惟。"]},{"t":"淮南王篇","f":"五言古诗","c":["淮南有小山，伤悼淮南死。","追忆未死时，求仙礼方士。","白鹿安可骑，黄鹤呼不已。","宾客数千人，所见皆徐市。","巨万填神山，连弩射海水。","今视犹昔然，岂但一秦始。","愚哉淮南王，误信少年子。","白刃临春风，八公竟何在。","姱修安馀龄，奚必睎久视。"]},{"t":"蝶蝶行","f":"五言古诗","c":["蝶蝶畏乳燕，乳燕良可畏。","不知天壤间，所遭皆燕类。","人亦尽蝶蝶，东西竟何拟。","明月照江山，幽谷终弗弃。","万物知所从，莫以形骸累。","劲翮随翱翔，高低各有位。","延促安天年，与夺岂人事。","委运吾自适，卒尔勿惊异。","持此为遨游，平生鲜违意。"]},{"t":"蒲生行","f":"五言古诗","c":["兔丝缘茑萝，玄鸟巢深屋。","所托岂不厚，常恐年运速。","松枯根叶萎，栋折春泥覆。","羽翼良可因，青云匪我欲。","不见兰与蕙，萍藻欣一绿。","荣瘁人不知，顾盼傥非俗。","春露谁为滋，秋霜鲜见毒。","白日从冥冥，红尘空逐逐。","凄风悲中宵，骤雨沉广陆。","蘼芜青复黄，兰蕙香断续。","盛衰各有时，何山无幽谷。"]},{"t":"野田黄雀行","f":"五言古诗","c":["野田多黄雀，罗网无停机。","少年有利剑，不肯放雀飞。","若肯放雀飞，四海谁疮痍。","汤仁开一面，孔不射宿枝。","隐显自有道，布泽随盛衰。","人各怀其心，猛鸷安足施。","富贵苟弗念，日月逝如斯。","零落归山丘，始悔当路时。","更闻侠烈人，身意为是非。","慷慨任目前，要令天下知。","意气寡所效，虞卿终奚为。"]},{"t":"远游二首 其一","f":"五言古诗","c":["少年事远游，不识远游难。","望望向河北，北风吹我颜。","飘飖鸿雁群，衔芦度秦关。","翱翔南浦云，潜鳞沉巨川。","贪饵喷馀沫，复见随竹竿。","敛迹逝嵚厓，虎豹号林寒。","往来无人踪，狐兔多伤残。","黄谷奋羽翼，常忧金丸弹。","作客三十年，年年摧肺肝。","备知远游苦，徒嗟头鬓斑。","世无羡门子，不如蚤回还。"]},{"t":"远游二首 其二","f":"五言古诗","c":["远游迷卢外，不离迷卢中。","偶逢海大鱼，忽化为神龙。","神龙无定形，随意成纤洪。","或现南鳖鼻，或时群蛟从。","合马产龙驹，■悷难络笼。","我有豢龙术，乘之驰西东。","鞭耳倏不见，隐显潜吾躬。","遥望在山头，只是住山翁。","往来平无奇，安知吾跨龙。"]},{"t":"挽歌","f":"五言古诗","c":["重泉不可到，到者几人来。","昔年高会处，歌钟依旧催。","骅骝黄金勒，葡萄白玉杯。","昔人今尚在，千秋铜雀台。","台上昔人行，井干生青苔。","拂苔行今人，意气扬烟尘。","容仪光凝停，引手弹鸣琴。","游龙从风翔，轻云落素阴。","今日美少年，他年蝼蚁心。","秦王与汉武，高陵何乔林。"]},{"t":"惟汉行","f":"五言古诗","c":["自昔鸿门会，智士咸危疑。","当时已默定，事后方始知。","沛公必不死，泰山终难移。","项伯以身蔽，意气良为谁。","临难心乃见，一诺安可欺。","壮心樊参乘，死且不足辞。","帝王匪偶然，龙起云相随。","观世以知人，忠邪各自为。","范曾数目羽，于羽焉足非。","卖主曹无伤，身戮有馀灾。","兴废古今常，天授多明扬。"]},{"t":"大道曲","f":"五言古诗","c":["谁著紫罗襦，据床弹琵琶。","意在市中人，声声到日斜。","系马垂杨下，停车傍酒家。","曲调岂关手，闻音多叹嗟。","将军笑不言，彼此争奈何。","年年春日媚，日日门前花。","相识不相识，满目空尘沙。","悠悠大道间，古树临长河。"]},{"t":"宛转歌","f":"五言古诗","c":["春中花盛开，暄风集崇台。","爽气朗襟袖，白昼净尘埃。","如此良辰何，看看欲徘徊。","徘徊还自问，人生当几回。","荆棘生高坟，雨雪空皑皑。","今我不惜阴，后人徒见哀。","后人复如我，展转成劫灰。","劝君濯渊鉴，静言观从来。","春花与秋实，荣落时见摧。","观彼荣落时，我心当何持。","莫以琴瑟娱，逐乐忘归期。","斗酒虽云欢，万岁谁相知。","何不趁芳华，百情聊以移。"]},{"t":"乐辞","f":"五言古诗","c":["世人重颜色，颜色如秋兰。","兰气随风散，兰花开后残。","眼见花开尽，香散秋风寒。","独坐观荣瘁，流泉空潺潺。","此意难为言，人外君自看。","枯骸旧颜色，旧人今不识。","新人即旧人，恩怨岂当忆。"]},{"t":"梅花落","f":"五言古诗","c":["梅花良可持，翻惜花落时。","花在霜中好，花在霜中老。","开落趁春寒，不识春外草。","青青松柏枝，常为斧斤恼。","延促终归尽，寻香苦不蚤。","莫忧落时无，但看开时皎。","物理岂长荣，春光人见少。","百卉望不及，寂寞寒山道。"]},{"t":"渌水曲","f":"五言古诗","c":["乘流汎春渚，荡荡木兰桡。","日射水头红，微风翼柔条。","轻衣入芳树，重阴覆河桥。","缓步胜安车，遵畬盼新苗。","真乐岂景物，百龄如一朝。","山酌薄醇醪，清辞当歌谣。","心与诸境泠，寓目皆逍遥。","烟光澹将夕，黄鸟鸣咬咬。","倚杖望櫩际，去来谁为招。","含情迟回涂，此道何寥寥。"]},{"t":"古诗十九首 其一","f":"五言古诗","c":["我昔在中冓，与君生别离。","不识别离苦，宁畏死相思。","乃至相思死，始知生别好。","秋风入罗帏，萧索哀边草。","迢迢天一涯，颜貌在怀抱。","奄忽随化迁，痛绝安可道。","生亦不相见，情教别到老。","魂魄终何之，举头寒月皎。","掩户徒沉吟，人生岂长保。"]},{"t":"古诗十九首 其二","f":"五言古诗","c":["西猋捲黄云，白昼扬氛埃。","天地一为变，登高望边陲。","羌独无良人，胡为久徘徊。","念彼邻家妇，掩涕向予哀。","红粉怜青春，征衣手自裁。","裁就寄沙场，常忧游冶猜。","猜则从他猜，中情谁与回。","不学白头媪，年年守空帏。"]},{"t":"古诗十九首 其三","f":"五言古诗","c":["天高安可极，海深不足注。","斗酒聊为欢，含情伤日暮。","人生如旅泊，倾盖皆亲故。","晨起东西驰，行行不相顾。","人言五陵贵，驱车向官渡。","巍巍望高门，衣冠盈道路。","李赵列前楹，珠履盛金赂。","朝登廉颇堂，夕曳相如阼。","所见尽攀龙，转盼浥朝露。","第宅何曾易，主宾非昔遇。","白云仍在天，波宕洪溟固。","俛思胡为来，万里怆回步。"]},{"t":"古诗十九首 其四","f":"五言古诗","c":["穷贱人所厌，岂不慕要津。","辞褐事簪绂，得意扬风尘。","吹笙连北里，歌钟接南邻。","壮心亦云遂，往来多懿亲。","讵知松柏侧，垒垒列高坟。","生前皆荣贵，死后同贱贫。","营营一百年，电火追良辰。","何不湛高识，虚舟随吾身。","贵贱当有时，俯视如浮云。"]},{"t":"古诗十九首 其五","f":"五言古诗","c":["高阁敞云衢，斥鴳飞不到。","奋翅及檐楹，徘徊忽长啸。","空梁亦有巢，飓风终夜号。","岂不恋主人，中怀限堂奥。","翱翔返蓬蒿，大鹏安足告。","扶摇九万程，望绝空长悼。","鹪鹩惭一枝，饮啄从吾好。","御风与乘云，引领非所造。","飞飞时复鸣，优游卒此道。"]},{"t":"古诗十九首 其六","f":"五言古诗","c":["万里忽怀归，对景心相违。","不耐春花艳，那堪秋草凄。","梦里喜还乡，到乡犹此时。","花草何曾异，形影终不移。","乡关本无情，吾心自欣悲。","寸心苟勿忆，古今谁合离。","玄鬓伤白头，安车惭奔驰。","邈邈江山外，游人空是非。"]},{"t":"古诗十九首 其七","f":"五言古诗","c":["朔猋动幕寒，谷风入户清。","秋鹰化春鸠，逐雨求将晴。","物候恒因时，人心多不平。","富贵无贫交，穷居矢友生。","兹道岂从今，慷慨犹虚名。","世上赖有此，贤哲终以明。","息机勿复言，天下皆陈人。","梦觉安足知，夷然乐吾真。"]},{"t":"古诗十九首 其八","f":"五言古诗","c":["乔木不可息，汉女不可思。","灼灼桃花夭，家室交相宜。","忡忡谓之何，岂不惮愆期。","鸿雁鸣雍雍，冰泮良有时。","江汜且终悔，白茅慎毋移。","芣苢何足采，兔罝吾所知。","愿言勖君子，素丝其纰之。"]},{"t":"古诗十九首 其九","f":"五言古诗","c":["幽兰比良朋，临风怀馨香。","诗书还昔人，所思在高阳。","折花聊以遗，颠倒醉君傍。","君醉我独醒，我醉君荒唐。","携手上河桥，新条排两行。","醉里犹惺惺，髣髴旧残杨。","行行莫回顾，踯躅登君堂。","千里长相思，畏言恐心伤。"]},{"t":"古诗十九首 其十","f":"五言古诗","c":["尽云天鉴迩，昭昭奚所亲。","尽云天听卑，号号如无闻。","江汉何滔滔，草木何芸芸。","人外有青山，青山多白云。","茅茨共麋鹿，宫阙齐秋旻。","秋旻不可逼，麋鹿常为群。","岂不乐麋鹿，麋鹿犹畏人。","万古只如此，始尽介然心。"]},{"t":"古诗十九首 其十一","f":"五言古诗","c":["人生必有死，衰迈寻病老。","少壮矢四方，驾言向燕赵。","笙竽连夜动，娱情不觉晓。","有客倾盖交，劝我立身好。","中路遽回车，黾勉先贤蚤。","荣名勒朝堂，宾从行尘扰。","本所获生平，须鬓忽已皓。","韩众安可亲，三万亦难保。","念此当何为，自托岂无道。"]},{"t":"古诗十九首 其十二","f":"五言古诗","c":["衰草曾几何，盼盼春已绿。","百草向人欣，黄莺啭深谷。","会当秾李期，士女争相逐。","晨朝行泥中，日夕贮金屋。","恩遇亦靡常，君情多反覆。","絺绤不可风，古人其何赎。","音响非不谐，悽惋托丝竹。","弦断伫遥夜，沉吟空踯躅。","秋水照颜鬓，忧多损冰玉。","回忆春燕归，感化成衰辱。","不如未嫁时，素裳聊以服。"]},{"t":"古诗十九首 其十三","f":"五言古诗","c":["极寿鲜至百，城隍故复新。","知见留世间，国土迁人民。","浩浩阴风吹，凛凛松柏身。","已死勿复道，未死谁与陈。","未死笑已死，今人犹昔人。","智者向我言，人生如浮云。","豪杰与圣贤，终焉成灰尘。","丹液多所误，浮丘空有名。","有酒但须乐，安问毁且成。","此语不知道，大道忘身形。","彭殇岂足计，玄妙匪其珍。","荣枯还大化，所赖吾有心。","汎汎难为谋，抚弦鸣素琴。"]},{"t":"古诗十九首 其十四","f":"五言古诗","c":["更有游宕子，感化思乡邻。","岂知乡中土，亦有松下人。","久客伤新死，还家悲旧亲。","远道羡村井，故里怜他津。","人情相去住，欣戚同一真。","知且不可移，格格谁与平。","安得庖丁刃，为君易其心。"]},{"t":"古诗十九首 其十五","f":"五言古诗","c":["人有百岁忧，所忽在旦暮。","今夕不知明，茫茫竟何去。","为乐贵及时，景短心难御。","神仙如可求，执鞭亦欣慕。","缑氏山头鹤，到今过几度。","寸阴良足惜，莫以昔人误。","宣尼叹逝水，岂为遨游故。","崇德在尔躬，绝续起深惧。"]},{"t":"古诗十九首 其十六","f":"五言古诗","c":["凉猋起何处，浥露掩朝晞。","草色白未已，王孙寒不归。","本与我同襟，忽然捐重帏。","帏薄梦难同，秖要良人知。","自古多行役，亦有回车时。","岂不念昔者，新昏情孔痴。","情痴焉可久，昔心宁终违。","婉转盼今夕，寒月空相随。","今夕移他夕，谁知寒月辉。"]},{"t":"古诗十九首 其十七","f":"五言古诗","c":["别久音问旷，不疑窗外声。","蟢子焉足凭，檐鹊长欺人。","月圆忽已缺，暑去寒相因。","书来不敢看，恐是遗东邻。","尝闻有归期，寒风暗自惊。","午梦迎中途，生憎黄莺鸣。","修阻谁能料，新心知重轻。","万事弗信缘，沉吟空复情。"]},{"t":"古诗十九首 其十八","f":"五言古诗","c":["前路岂无知，青云多合离。","或当成螮蝀，率尔长阴霾。","飘飘万里馀，安得如旧时。","昔心犹在怀，意气谁能持。","旦夕聊相许，乘风难奋飞。","体素所当重，叹息琼树枝。","寤寐予勿忘，尔亦应予思。","冥冥天宇阔，相见终何期。"]},{"t":"古诗十九首 其十九","f":"五言古诗","c":["老妇守罗帏，羞见旧衣裳。","谁家游冶儿，不念嫁时妆。","红粉倚高楼，因人还自伤。","明月为谁皎，清风为谁长。","举目皆索怀，不如归中堂。","我亦曾少年，忆欢时断肠。","幸然决绝蚤，不到悲空床。","此心何日止，橘绿柳条黄。"]},{"t":"翠鸟","f":"五言古诗","c":["有鸟缥青色，近集櫩前树。","树下渊洄澜，旭日照毛羽。","水中与日里，徘徊不能去。","双双飞复鸣，饮啄频相顾。","岂不念高栖，锦襟君子慕。","因人亦自怜，安知造物妒。","一旦虞机张，始悔投林暮。","毋为怨主人，托身非其处。"]},{"t":"百一诗","f":"楚辞体","c":["生平喜住山，而匪乐登陟。","犹忆居匡庐，频年乃一出。","讵肯离人群，枘凿初难入。","尝为鲁国士，志不受绳墨。","岂有王子乔，丹溜不可食。","离离若参辰，俯仰恒滋惑。","桀纣奚无性，舜禹安知习。","心知随见闻，渐渍非一日。","阪泉无恶名，南巢有惭德。","曹魏亦受禅，人指为篡立。","侯门出仁义，俘虏尽残贼。","当时重成败，后世覈名实。","名实持圣贤，成败犹甲乙。","甲乙古又今，圣贤何得失。","事穷乃崇因，邈邈终难必。","盗蹠丰且延，颜闵贫而疾。","吁嗟乎天兮，三世费穷诘。","浩劫一念兴，休咎成消息。","易言积有馀，庆殃通家国。","薰莸竞目前，不知其所集。","我观始与终，以此百情毕。","玄璧难为功，燕石吾自袭。","富贵岂不欲，黄雀悲双翼。","长年岂不慕，蓬莱日易昃。","世纷久已辞，接舆匪其匹。","有身随饥寒，无心任欣怵。","衰荣造化均，忘怀岂静力。","一死复一生，一劳复一逸。","蜉蝣自朝暮，鹤曲龟潜匿。","修短竟由谁，可以破世执。","我亦无奇怀，秖有安心术。","行行见远山，或时坐长默。","或时登高台，一目浮云逼。","云散空中真，夕照起寒色。","茂林环苍岑，晨风归广隰。","此趣谁当无，殷勤赋百一。","试问张留侯，黄石蚤曾识。","功成鬓垂垂，欲悔嗟何及。"]},{"t":"形影神诗三首 其一 形赠影","f":"五言古诗","c":["天地岂不仁，万物为刍狗。","斯人岂不仁，大患随其后。","我本奉周旋，尔复劳相守。","父母未生时，太虚谁为偶。","忽然成百骸，我有尔亦有。","动静虽不离，泯灭岂当久。","曾念世间人，名利空狂走。","纵使长逸媮，毕竟将安取。","羡尔能无心，我亦恒抖擞。","归尽宁异今，且共乐南亩。"]},{"t":"形影神诗三首 其二 影答形","f":"五言古诗","c":["至理无亲疏，近情分苦乐。","身心我不知，一味随倒卓。","始终同劳劳，趣避省营度。","汝亦待神明，悲欢要先觉。","苦乐虽梦幻，忘形焉可学。","日夕相体悉，一解一切缚。","此理须稔知，且勿候凋落。","我固候化迁，悠悠欣所托。"]},{"t":"形影神诗三首 其三 神释","f":"五言古诗","c":["由我成汝形，形立影恒随。","朕兆匪无因，合离信有时。","三一理同然，各各不相期。","汝无遗景意，我岂逐汝摧。","进止终当无，胡为更徘徊。","汝常为我役，亦复生我悲。","稔知不长存，彭殇空尔为。","善恶吾自悉，讵为一身贻。","生死谁去来，大冶将同归。","面目安有穷，万化犹若斯。","只今鉴顾閒，任性齐灵皮。","卷舒从所欲，作起毋暂违。"]},{"t":"示旋庵","f":"五言古诗","c":["众生久流转，迷于自心量。","失所精了性，无觉觉所觉。","分别见有我，我立生有人。","众生及寿命，一时同具足。","展转生死中，缚脱总迷闷。","愚人随业缘，住于不觉地。","智者觉不觉，舍生而取灭。","空华阳燄里，颠倒徒掜目。","晴空迥无有，观者莫劳累。","汝与诸佛同，一切贪嗔痴。","即是戒定慧，直下无有二。","亦无无二想，居然登祖位。","慎勿下劣心，流转不知止。","一念自觉非，善哉旋庵子。"]},{"t":"谢毓和母七十初度求题小影","f":"五言古诗","c":["谢母雅好道，七十志逾坚。","不以福胜慧，火中生红莲。","又有子若孙，在俗而行禅。","锡类摄同事，所交皆圣贤。","颂祝匪无物，重以法供先。","殷勤乞我赞，以当仁者言。","天地不称寿，大寿语默边。","非数量所拘，得之实有缘。","努力须及时，释迦岂自然。","至哉真实相，普现群生前。"]},{"t":"书龚德瞻扇头","f":"五言古诗","c":["君知造化者，而不行造化。","呼牛应以牛，呼马应以马。","真亦随他真，假则灼是假。","眼孔空一世，踪迹半天下。","与君世外交，相看口常哑。","同在五行中，各自有陶冶。","君示有室家，我固乐山野。","死生与险夷，嘻笑而怒骂。","但以虚舟触，胸次恒洒洒。","交尽世间人，亦何妨和寡。","君索我赠言，咄咄聊且且。","愿君终解脱，共休乎般若。"]},{"t":"禅人制衣示之以诗","f":"五言古诗","c":["此衣如传舍，一日三易主。","须知我与子，亦无决定义。","但以此蒙头，谁论是不是。"]},{"t":"戊戌小除示澹书记","f":"五言古诗","c":["我年五十一，适汝四十五。","面目各老大，法身无遮护。","七年小除夕，喜共今年度。","缘聚且有时，况复无上道。","道在忧弥深，空忧愧无补。","爱尔性忱挚，惧尔性疏稿。","我归自栖贤，晤别犹草草。","臷庵一月谈，投机恨不蚤。","屈曲有深言，直捷无行路。","暗明绝暗明，回互不回互。","十地岂其俦，万法从兹扫。","一喝双耳聋，一蹋全身倒。","释子非百丈，山僧非马祖。","荷担莫迟回，须记四十五。"]},{"t":"示雪盛禅人","f":"五言古诗","c":["雪盛供我研，即日乞书扇。","我书既不佳，报称亦颇贱。","嘉尔解人意，忘我笔墨俚。","忻然惠一言，似诗而实偈。","汝性如美石，良工待雕琢。","因缘信有时，逡巡惧瓠落。","汝事余有年，忽务徒周旋。","何如一片石，抱璞蹲吾前。","我闻古之学，慕道如饥渴。"]},{"t":"题观世音菩萨像","f":"五言古诗","c":["道以无心得，相以有心现。","无心割截平，有心庄严展。","无心无罪福，福罪有心见。","割截与庄严，有无心转变。","一人成两心，两人圆一念。","积精遂密藏，至诚忻佛面。","大士无缘慈，照临仝时遍。","各以佛子根，真实通方便。"]},{"t":"乞药","f":"五言古诗","c":["雪山有药草，可以愈痼疾。","具足大地人，信手便拈得。","拈药施良医，醍醐还自食。","秖贵大地知，先须破悭惑。","施受总由渠，成佛无他术。"]},{"t":"初春闻顿修至丹霞","f":"五言古诗","c":["抗别忽四龄，沈哀先后仆。","高树失慈乌，终恨不成哭。","悬钵毁空中，悲辛怆幽独。","岂无桃李蹊，行行念穷谷。","绻彼谷中人，茕茕夷骨肉。","宁尔独无父，巽坎抗宵夙。","安乐矢同归，穷愁厌相逐。","嗟今世上情，而我怀惭恧。","前路轻冬夏，离忧数往复。","遥遥待归人，弹指未云促。","谁驻丹石昂，谷风摇春木。"]},{"t":"初春怀石鉴栖贤","f":"五言古诗","c":["石人峰下云，长覆石梁水。","石梁潭水淙，分明来梦里。","五老白雪零，五羊红桃美。","红白本同时，山川成遐迩。","引念情复殷，悠悠几千里。","坐起徒为劳，无酒安可恃。","憬然觉何从，形迹百年耳。","多宝塔中人，古今前后履。","蟭螟眉睫间，冥合不自此。","优游溪上林，岂俟观无始。","厌闻世外俦，合离仍贩市。","意气感当时，睽违亦已矣。","死且不可忘，终山有田子。","安得至今日，展像谁当似。","我有夙世习，抱衾中夜起。","忘情卑太上，所钟非所儗。","亭亭百尺楼，极目万山紫。","山外汇重溟，溟深不见底。","揆我怀人心，心孤焉足比。"]},{"t":"喜枯吟还山","f":"五言古诗","c":["不是怨离别，前途非所知。","所忧在吾道，世路安足悲。","冬徂春复暖，杳然无来期。","桃柳覆曲栏，鸟雀鸣繁枝。","对景每独坐，虚堂席毳帏。","童子报归人，未语先解颐。","相见空复情，掩泪恨去时。","丈夫贵肝膈，匪石终难移。","岂无众卉芳，乔松古壑宜。","千尺映危楼，迢迢与世违。","夙志非懒瓒，今昔伤淳漓。","口舌畏异同，长贫托海湄。","怪石丛高林，益励霜雪姿。"]},{"t":"樊长文生日","f":"五言古诗","c":["谷风吹南陌，高树鸣春禽。","晴川迥长薄，户牖临苍岑。","往来者何子，优游松柏阴。","行谊照古道，而无晚近心。","壮年曾一荐，异代守素襟。","每有袁安困，刘龚徒知音。","物情观累卵，白社依东林。","遁世惜微言，恒为斯人任。","今年六十一，设帐远海浔。","道俗庆悬弧，予亦寄微吟。","莫厌山泽癯，年年春木森。"]},{"t":"樊大愿生日","f":"五言古诗","c":["三界如逆旅，千年犹终朝。","一枯复一荣，旷劫空迢遥。","众庶乐奔竞，太上恒寂寥。","奔竞竟何成，寂寥长冥冥。","我爱樊道人，皆醉而独醒。","壹志在西方，而未尝离欲。","莲花生淤泥，随缘兴百福。","今年五十一，俛仰畅幽独。","高斋来南薰，梵音响村屋。","田园乐有馀，岂更羡山谷。","顾我非仁者，何能以言祝。","但愿终遐龄，遮莫远麋鹿。"]},{"t":"栖贤舍利塔","f":"五言古诗","c":["佛性甚光明，能破一切暗。","佛性甚坚利，能断一切物。","流被千百骸，结成五色珠。","表此坚光体，法化无有二。","念我遗教者，睹珠如佛在。","一粒细如菽，供养福无异。","况聚千万珠，瞻仰发夙慧。","极果摄微因，感应通心臂。","佛是已成佛，我是未成佛。","果即在因中，当念无终始。","我以此一心，供养诸如来。","获睹佛真身，朝暮常顶礼。","金轮触神光，三十年于此。","今复闻栖贤，古塔示瑰异。","将建窣堵坡，作诗寄千里。","佛身不可赞，我赞非言句。","愿佛鉴我心，与佛身无极。","遂我今日愿，心光泽营卫。","有理必有事，本举末自至。","广及诸未来，学佛到佛地。"]},{"t":"海幢舍利塔","f":"五言古诗","c":["佛在众生中，如日处霾翳。","霾翳非可入，日光彻空际。","佛身如虚空，佛心如光霁。","光极与空入，空光交相蔽。","结成幻摩尼，五色非坚脆。","我识如来心，随顺示真谛。","假名为舍利，金石不能甈。","现在与当来，百福之所逮。","群动匪无心，遇境生幽滞。","寂感总随缘，形神不相俪。","佛以主摄宾，金刚见精慧。","我汝但回光，弹指消阴曀。","如日之在天，百物无疵疠。","此以论性功，岂为形骸励。","我昔在金轮，蒙光涤夙瞖。","栖贤发神异，今复流法系。","慧日照岭南，丹霞若先契。","次第及海幢，贻尔大厥裔。","隆隆薄青霄，百道金光丽。","万世福人天，皇风永勿替。"]},{"t":"丹霞舍利塔","f":"五言古诗","c":["心光彻内外，如珠入五色。","珠与色无性，非离亦非即。","非即超形骸，非离浃营卫。","月在千波中，波波摇青霁。","凡圣唯一心，湛昏成二谛。","示生死涅槃，而实无坚脆。","脆以别生死，坚光表性义。","本从心生色，迷色乃有二。","蚌含明月珠，体合百骸粹。","领纳镜中像，想即妙观智。","流注皆真常，分别非明记。","如是五蕴身，与法身何异。","秖因一念迷，情生分秽净。","净秽悟由心，当念绝邪正。","佛以此智證，法化无同别。","示现别中同，同中别自晰。","光耀百千年，福被我遗教。","神光触金轮，仰瞻如梦觉。","栖贤发瑰异，感激当其运。","移光照岭南，慈曜无远近。","佛子学聚沙，燔土紫金斓。","崔巍海螺巅，晶晶逼霄汉。","举目道与会，布发形俱泮。","见闻起遐情，究此未来际。","念念尽圆明，身与心毋戾。"]},{"t":"门人崔今婴居家事佛而先得观音大士像以其意乞赞焉为释之曰子初事佛而进退作辍未克自信是不可不乞庇于大士事大士正所以深事佛也遂赞以诗","f":"五言古诗","c":["如来一大事，而出现于世。","大士辅如来，方便为广励。","众生深于迷，须以慈相示。","大士如众母，善恶皆可恃。","有不可对佛，不忍欺大士。","靠之若泰山，罔极终难比。","愿与敬礼者，如大士而止。"]},{"t":"忆昔二首 其一","f":"五言古诗","c":["忆昔年十八，矢志学浮图。","荏冉尘网中，坐令真人徂。","读书恨不见，犹及宗其徒。","博峤曾有言，吾道恶岐涂。","杨朱泣何从，哀彼南北殊。","始吾过吴越，亲遘良不诬。","倏忽三十载，法运当谁扶。","当时谓羊角，今日之所无。","汨汨若逝川，俛仰空长吁。"]},{"t":"忆昔二首 其二","f":"五言古诗","c":["忆昔鸾溪头，门掩寒山雪。","侧闻飞瀑下，法雷振岩穴。","冠盖列松杉，杖笠相颃颉。","主人貌婴儿，真似谁优劣。","犹争法秋毫，不与稗贩埒。","今见尽虎皮，云深山路绝。","撺迹远海隅，攒眸长捲舌。"]},{"t":"写怀","f":"五言古诗","c":["孤怀与谁论，经冬复徂夏。","迟迟云中人，白龙不可迓。","燕石久什袭，藏之乃愈固。","千里想神驹，买骨期旦暮。","伯乐匪无衣，喷鸣应有数。","凤凰患朝饥，高飞且回顾。","爰念修竹花，结实岂终误。","我爱鹿门山，园林多蔓绿。","护彼霜雪侵，淹滞同流俗。","流俗安足依，蔓绿长芳菲。","山鸟去仍来，悠悠盼春归。"]},{"t":"题卫其自小像","f":"五言古诗","c":["百岁终当尽，岂为斯人悲。","毕生述孔业，一半遭乱离。","我有大泽僻，远引疑先几。","朝游石镜峰，暮归洗马池。","浮沉三十年，见闻无旧知。","因人理南策，相见海之湄。","不敢论往事，欣然为后期。","雷宗依东林，心迹毋相遗。","乘兴每倏然，系舟雷峰陲。","乐事不可待，寒暑嗟密移。","一旦成朝露，厥嗣哀淋漓。","挥涕想音容，抱像乞一辞。","展轴犹俨然，相对如昔时。","生死俱不言，后世谁当疑。"]},{"t":"青松篇","f":"五言古诗","c":["我年已六十，黄花开未残。","落木风初劲，澄江月正寒。","所与共千峰，青松当露漙。","霜重百卉枯，葱郁犹可观。","桃李竞芳晨，敛容若盘桓。","而非黜繁华，意在三春前。","而非乐枯槁，庭葩无久鲜。","拳曲荫崇台，廓落宇宙宽。","挥杯就清影，颇觉形骸安。","远近呼良朋，坐久生夕烟。","此乐不可说，说乐岂其天。","岁月忽自知，俯仰良欣然。","我乐与他乐，不离松树边。","各各起奇情，安得不忘年。"]},{"t":"岁晏","f":"五言古诗","c":["抚景岁云暮，山寒人境幽。","乱霞空布满，深松藏径修。","高低距百丈，回曲将三休。","登台观云变，倚树闻石流。","忽睹归鸟忘，岂为卒岁谋。","归鸟无所知，人心自绸缪。","人心不似鸟，似鸟何优游。","鸟若似人心，万物多欣忧。","石壁分鸠月，空林限鹿丘。","虽有桃花源，顾盼终夷犹。","所赖天地宽，川陵容老叟。","上有千仞梯，长啸高峰头。","下有九曲渊，汗漫乘轻舟。","相携三五辈，日出课西畴。","以此乐长年，人生当何求。"]},{"t":"买花辞","f":"五言古诗","c":["买花莫买叶，买叶草离离。","花种从根来，枝叶相扶持。","叶堕花影稀，影稀风易吹。","风吹花不落，花落自有时。","落时非无花，花落子垂垂。","春来花复发，枝叶宁亏危。","枝叶信所天，非关花盛衰。"]},{"t":"杂诗七首 其一","f":"五言古诗","c":["南国有佳人，赋性慕芬芳。","一笑惑阳城，袅袅情不荒。","席帏竟长年，寸步规中堂。","引镜照斜领，容貌空自将。","曾许五陵少，十五宜归郎。","父母劝女行，为理嫁衣裳。","敛衽跪陈辞，愿终守雪霜。","讵不怀三星，绸缪焉足长。","毳褐亦可缝，稗秕亦可浆。","百岁将安之，予美耿中肠。","日月既云迈，苞稂乃见伤。","未逮衾与裯，揆谊终难忘。","吁嗟乎冽泉，掩涕归空房。"]},{"t":"杂诗七首 其二","f":"五言古诗","c":["噭噭云中雁，迢迢向南飞。","万里从沙漠，怆恻兴予悲。","所悲曷云谁，乃谓予中姨。","中姨同予生，亦复同操持。","许嫁不肯嫁，形与心相随。","忽闻良人殂，潸然泪横洟。","虽无琴瑟好，父母曾相期。","礼义发天性，此岂世俗知。","载鬼且张弧，今昔多然疑。","道路既阻修，魂魄竟长辞。","我非念骨肉，岂更为情痴。","落叶随风飘，故株终不移。","黄河亦易竭，水流难向西。","寒日沉东溟，濯魄乃逾辉。","桑榆盼初景，聊为一登台。"]},{"t":"杂诗七首 其三","f":"五言古诗","c":["阿姨行第三，嫁郎好驰驱。","驰驱事中原，结客皆市屠。","所许多侯嬴，夷门几捐躯。","易水去悠悠，空惭剑术疏。","茕茕未亡人，截耳守志孤。","张罗岂不密，其如南山乌。","自古臣致君，节妇死故夫。","柏舟汎共姜，危楼坠绿珠。","委身各有道，生死良不诬。","我悲犹同生，志异行俱殊。","百年曾几时，精识当何如。","天地会终极，四气相乘除。","白骨弃黄泥，寸心观有无。","不见川上波，逍遥雁与凫。"]},{"t":"杂诗七首 其四","f":"五言古诗","c":["夕竟出东门，蟾兔起遥岑。","初照不至地，空水白粼粼。","郁勃昏经涂，先后声相凭。","崇楼耸睥睨，已过越王城。","人影怯松风，腐草流青萤。","湍流渐寒响，石梁月微横。","搴芳藉颓轨，慷慨论生平。","敛皓繁霜满，屯云蔽前林。","厓巘隐漭沆，明没见秋灯。","蹑足端所向，入树宿鸟惊。","茅屋沉雾中，扣门如无人。","长老烹旅葵，晨餐才五更。","饱粟坐磐石，灌木摇高岑。","虑澹匪忽物，俗简情易亲。","虎狼不在山，遨游随浅深。","回顾今何时，空忆吕稽名。","山阳无旧居，何以赋予情。"]},{"t":"杂诗七首 其五","f":"五言古诗","c":["少年慕勋名，挟策向京都。","朝辞莱子衣，日暮登公车。","万里谒君门，所志在攘除。","朱户尽金张，许史无空庐。","鼓鼙遍原野，北郭皆丘墟。","文臣死疆场，游说多穰苴。","九重日焦劳，闾左夜笙竽。","贡公不可学，胡为滞通衢。","寸阴讵勿惜，缮性吾有馀。","徘徊去长安，浮游归蓬居。","岂不怀匡济，天运当何如。","汉兴擢良何，隋衰生世虞。","何山无良材，拳曲顾盼纡。","此理良固然，志士徒欷歔。","贫贱安足骄，将以返生初。","偃息川岳间，真乐非禽鱼。"]},{"t":"杂诗七首 其六","f":"五言古诗","c":["日中影自仄，岂待薄虞渊。","流曜渐西夕，烛炬讵足然。","举目昧荧荧，哲士惭几先。","人天虽合并，难以希时贤。","一死不可生，及生犹迁延。","既已绝世用，吾当纯用天。","周望勋安在，邓禹名空传。","渭滨与邺下，至今河潺湲。","冢上呼黄鹤，子安何时仙。","功泽在一世，形骸无千年。","声象非永久，探索维幽玄。","抚时知代谢，观身悟脆坚。","悬鉴穷将来，乃居万物前。","沉寐忽一觉，枕间闻夜泉。","响寂竟何从，悄然复成眠。"]},{"t":"杂诗七首 其七","f":"古风","c":["青青头上天，汨汨江中船。","亭亭北山松，噭噭南浦鸿。","岂得不杂处，万物群相攻。","人为万物灵，蠢尔当何从。","肆顾足徬徨，无宁犹梦中。","梦里登太华，交游皆赤松。","明月生紫烟，流光停碧空。","浮丘驾云?，洪厓乘轻风。","相视如旧知，长啸抚焦桐。","一弹嫦娥集，再奏吟商龙。","所食白石脂，所居琼瑶宫。","语笑非人间，颜貌疑初童。","岁月岂有厓，惝然闻朝钟。","群籁渐俱入，展目东方红。","犹忆颛顼时，东南倾共工。","伯禹腹于鲧，九载弗成功。","秦穆殉三良，贤士运何穷。","愚智竞芳秽，哀乐心相同。","情随物化迁，一雌复一雄。","蜾蠃负蛢蛉，生死将安终。"]},{"t":"咏史十二首 其一","f":"五言古诗","c":["嬴秦溯颛顼，实肇诸大费。","治水锡皂游，贻尔大厥嗣。","勤周肆封爵，赐之岐西地。","陈宝得其雄，将无为秦始。","食马三百人，岂直当世利。","种德被子孙，威加殄尔类。","隆功德所乘，德薄功难再。","并一古帝无，六王不足毙。","咸阳兵可销，阿房复渡渭。","杀旁绝人知，坑儒塞巷议。","诗书竟何仇，揭竿岂文字。","皇帝传万年，山鬼知一岁。","陈胜奋臂呼，万国诸侯至。","功成不务德，天命安可系。"]},{"t":"咏史十二首 其二","f":"五言古诗","c":["天下自归仁，乘敝易见泽。","长者人共推，况有西楚霸。","雄兵号百万，瞋叱皆辟易。","背关杀义主，遂为帝王藉。","神龙排九霄，风云生羽翮。","一败彭城东，折木扬沙石。","再出荥阳西，黄屋回剑戟。","残暴人天厌，子惠一当百。","吕公识微贱，老妪安足覈。","君子慎幽邈，小人怀显谪。","迩可远在兹，上帝日临赫。","英雄各自为，委身矜一掷。","若无良与平，东西决晨夕。","鸿沟限天堑，龙蛇异窟宅。","五年起布衣，成败争毫发。","所信维穹苍，穹苍不可绎。","抚时崇明德，天心在咫尺。"]},{"t":"咏史十二首 其三","f":"五言古诗","c":["天子起稼穑，卖谷布兵弩。","谨厚亦复为，子弟乃安堵。","美髯刘将军，大敌猛如虎。","三千乘锐奔，百万成尘土。","雷雨溢滍川，溺死安足数。","功成失伯兄，引过不敢语。","三辅喜东迎，汉官今复睹。","晨夜趣南辕，几为传吏虏。","兼行犯雪霜，惶惑不知所。","冰合滹沱河，乃有白衣父。","邯郸拔其城，焚谤安行伍。","萧王推赤心，铜马获真主。","短兵接高厈，突骑胡相距。","南郭千秋亭，正位顺群伫。","大宝归仁人，万灵赖依怙。","抚我谁当仇，元吉自天祐。"]},{"t":"咏史十二首 其四","f":"五言古诗","c":["天命邈难谌，仁暴恒相持。","汉室至桓灵，国祚亦孔衰。","既生刘豫州，又生操与丕。","挟主令天下，荀郭多从之。","维我与使君，英鉴谁当欺。","不可与争锋，卧龙犹守雌。","运会倘默定，鞅掌欲何为。","仁人之用心，尽瘁以死期。","连营七百里，尝为此辈嗤。","孝直即不死，骨肉终难移。","丞相真天威，南人无所施。","魏延不可用，岂故从坦夷。","竟出五丈原，仲达安足窥。","有道未必昌，古今长叹咨。","奸雄亦有成，圣哲能无疑。","曷求所从来，毋为昧当时。"]},{"t":"咏史十二首 其五","f":"五言古诗","c":["治世耻言功，拨乱难为德。","周公安足类，国史从来直。","考古至隋终，掩卷长太息。","江都不可留，群盗势孔亟。","神速趣关中，柴师会渭北。","贤谋揖军日，一见如旧识。","骁雄摄英主，不疑怀敬德。","大业率由谁，而乃论嫡立。","功薄图自固，嫌忌反成侧。","人事上应天，秦分太白出。","骑虎竟何从，六月之四日。","诸子尚复有，哽咽终无及。","泽被在天下，万世悲其质。","贫贱无伤心，崇高多险仄。","勿生帝王家，此语堪涕泣。"]},{"t":"咏史十二首 其六","f":"五言古诗","c":["捡点作天子，天命不可违。","黄袍竟加身，人心奚所私。","惭负若之何，清夜终难欺。","试以询仁后，处此宜胡为。","干戈将揖让，遂古良有之。","百姓讵勿恤，残虐当歼夷。","事类乖中情，君子之所非。","幼主岂独夫，恩遇匪丛疑。","姬公苟莫恃，孺子谁与归。","申菽其不芳，粪壤以充帷。","沧溟胡宁枯，昆崙胡为移。","荃蕙化为茅，久旷安足知。","赵氏一块肉，三百以为期。"]},{"t":"咏史十二首 其七","f":"五言古诗","c":["微子竟何去，朝鲜闻鹁鸠。","箕子托佯狂，为人画九畴。","比干谏而死，形骸以为仇。","孔圣称三仁，芳躅传千秋。","迂哉鲁仲连，一身奚所求。","彊秦并六国，不知曾闻否。","刻石遍川岳，寻仙穷瀛洲。","古今多帝王，东海空悠悠。","更有田北平，除芜锄荒丘。","管宁终不仕，读书到白头。"]},{"t":"咏史十二首 其八","f":"五言古诗","c":["君都而臣俞，千古瞻清夷。","天性不可易，相得宁无时。","昏庸弃忠良，芳洁蒙谗讥。","不可终如何，若命殆安之。","嗟尔楚屈平，忧心亦孔哀。","宠眷鲜克终，练要捐尘埃。","武关不还辕，余马独徘徊。","亲知复弗谐，日暮谁为媒。","皇天安足问，云旗空委蛇。","终焉从彭咸，江中悲不悲。","愤惋匪骨肉，中情恒相随。","形骸既勿恤，修名欲何为。","灵枢返宵夙，九曜争光辉。","章黻晔且煌，旧乡亦有犁。","寸心苟不忘，率土皆潢池。","日月有明晦，桀挚奚是非。"]},{"t":"咏史十二首 其九","f":"五言古诗","c":["古称鸱夷子，三徙有荣名。","仕越谏伐吴，会稽几危倾。","反国共忧辱，二岁乃行成。","计然策十五，报吴卒以平。","横行江淮东，诸侯谁与争。","功成受上将，遗书投海滨。","致产数千万，齐主闻其名。","相齐曾几时，归印辞乡邻。","閒行止于陶，贸易兼躬耕。","累赀复巨万，中男行杀人。","千金不死市，褐器致庄生。","长男重弃财，竟以殒其身。","贵既不可久，富亦何足陈。","人生若朝露，不如贱与贫。","去彼复取此，终惭头上巾。"]},{"t":"咏史十二首 其十","f":"五言古诗","c":["天下马上得，不可马上治。","陆贾称诗书，尝为汉主詈。","新语十二篇，美言令人爱。","利弊中当时，亦复令人畏。","贤哲贵周身，忧国先防忌。","好畤可以家，多买腴田地。","家有五男子，橐中装尚在。","从侍常十人，十日更相替。","极欲数击鲜，千金足一醉。","来往公卿间，益增饮食费。","声名藉汉廷，不知其所为。","禄产既伏诛，孝文新嗣位。","大勋归将相，乃谓用其计。","世间恕醉人，或当有此事。"]},{"t":"咏史十二首 其十一","f":"五言古诗","c":["龙门曾诣阙，献策弗能用。","教授河汾间，弟子从之众。","累徵更不起，名藉一时哄。","风雨足以庇，薄田良堪种。","著书可自乐，谈道与人共。","假使献策时，大为隋文重。","伊吕岂终隐，杨元相伯仲。","虽有蛊上心，考槃不可颂。","奚似宁北海，山谷长读诵。","语不及世间，邴王交磨砻。","秖畏彦方知，刑戮安足痛。","道路惭拾遗，遐迩返群讼。","所负吾不知，行藏有微中。"]},{"t":"咏史十二首 其十二","f":"五言古诗","c":["吾爱臧子源，慕义行哭秦。","时乖事弗谐，挥戈绝陈琳。","瞋目声琅琅，投命毕君亲。","陈容起坐侧，激烈气冲巾。","宁与臧生死，不同将军生。","一日杀二士，坐客泪涔涔。","吾爱孔文举，正气淩星辰。","鸿名喿海内，兰艾难为林。","抚尸诣京兆，哀恻愿相徇。","吾爱唐魏徵，努力为良臣。","耻君非尧舜，切谏终其身。","吾爱狄梁公，北斗南一人。","不欲知谮名，俛仰涤素襟。","乱政弗逆指，志在归庐陵。","脯醢暂适口，供疾维术参。","从容将忠款，卒以返唐庭。","吾爱武攸绪，弃官隐嵩岑。","盛夏居石室，冬巢茅菽深。","释服买良田，混俗同耦耕。","中宗召问道，再拜还崚嶒。","丈夫遇不齐，所贵在寸心。","宠辱酬当时，明昧亘中情。","屋漏讼秋毫，岂以谋身名。"]},{"t":"老子","f":"五言古诗","c":["精一而既邈，三代朴以漓。","尚闻周柱史，眷言守中规。","无欲妙常净，有欲覈所依。","浮游浴玄虚，神物无相违。","久久返自然，颛致之循持。","古者垂衣裳，百姓冥是非。","运替文质殊，一揆成两岐。","仲尼叹犹龙，理穷拙言辞。","今日为长年，长年其糠秕。","大圣不可作，斯道犹近之。"]},{"t":"关尹子","f":"五言古诗","c":["吾爱关尹子，澹然绝群虑。","世有大圣人，旦暮欣一遇。","情冥如处暗，暗中明可数。","夜梦成于思，天地职此故。","圣不去天地，无识无所住。","虎变而鳖行，丝纷以棋布。","徇迹同众人，至神独离寓。","斯道久不传，谁复超所趣。","安得如是人，相将穷鸟路。"]},{"t":"孔子","f":"五言古诗","c":["尧舜禹汤文，直接尼山丘。","原道本乎中，未发当何求。","喜怒哀乐时，一簇破青眸。","尚论古之人，机括能不谋。","万祀有真诠，焉敢同悠悠。","人伦百世师，我亦曾侧修。","穷达各有道，体用宁相仇。","愿言有国家，上下其率由。"]},{"t":"颜回","f":"五言古诗","c":["之子不远复，复其见天心。","三月能不违，力尽知疏亲。","一间竟勿逮，洙泗乃无人。","箪瓢士之常，风雨岁时深。","所矢贵自信，岂直为安贫。","道在物我忘，迢迢空古今。","世间爱其名，山林多隐沦。","圣贤行何从，贵贱吾知音。"]},{"t":"庄子","f":"五言古诗","c":["庄周梦蝴蝶，蝴蝶为庄周。","是中无作者，万物将安休。","指与非指喻，相去何短修。","死岂遂知归，滑疑终悠悠。","明照非天均，因是焉足由。","譬之千万派，到海声俱收。","声消不是海，是海行倾湫。","一切悉意言，过此谁与俦。","吾思道在迩，作止空相尤。","要以解粗识，聊当圣贤谋。"]},{"t":"不饮酒二十首 其一","f":"五言古诗","c":["康狄肇作醪，大禹戒亡国。","牛饮竟丧朝，虎酣乃败德。","中山过一斗，玄石葬千日。","摄生且勿计，岁月良堪恤。","人生一百年，谁道更媮逸。","一醉忘百忧，醒后岂不忆。","不知未醉时，身世齐得失。","避影而处阴，重为君子惑。"]},{"t":"不饮酒二十首 其二","f":"五言古诗","c":["醉乡在何处，试问东皋子。","窅然丧天下，皇帝曾游否。","阮陶之所至，恐当是块垒。","不顾世閒名，沉湎竟奚以。","旦昏无移时，双眸湛如泚。","回以视世间，兴灭嗟逝水。","贤智处其中，如电与泡耳。","醉又当何为，不醉亦如此。","晨鸟东西驰，日落归山梓。","山高圆景微，朔风连夜起。","揽衣坐茅堂，此心不可似。"]},{"t":"不饮酒二十首 其三","f":"五言古诗","c":["梅花寒更韵，霜气晓来清。","山高常背日，暴药当午晴。","中食饱粗粝，隐几困以瞑。","悄然入胜地，高阳徒有名。","倦起呼酪奴，习习清风生。","抠衣下石门，远近观冬耕。","收种候春泽，千亩皆植粳。","斜日沉西江，返照摇云根。","石壁挂松影，已见蟾蜍升。","缓步谣归途，寒灯悬茅庭。","小僧接笠杖，大僧擎紫英。","此中有真意，醉人安足聆。","流光过石火，真成抛青春。"]},{"t":"不饮酒二十首 其四","f":"五言古诗","c":["竹林阮步兵，纵酒落世事。","母卒犹弹棋，二斗不足醉。","一号血数升，放达将安在。","所以贵有我，此心终难昧。","哀乐循固然，岂以一醉窴。","孔圣云汝安，乃以折狂蔽。","天性焉可诬，守此达礼义。","出处吾自将，不醉亦何累。"]},{"t":"不饮酒二十首 其五","f":"五言古诗","c":["世人笑我拙，有酒不肯斟。","我笑世人狂，醒醉各失真。","醉时醒时言，醒时醉时心。","醒言不可道，醉心安足任。","兀兀徒自为，言行互商参。","往昔多醒者，被酒同醉人。","醉心尚可易，醒亦非其伦。","因醉乃有醒，尝为醉人瞋。","瞋中多杂乱，益伤人醉深。"]},{"t":"不饮酒二十首 其六","f":"五言古诗","c":["季鹰仕晋惠，虑祸归乡闾。","尝因秋风起，忽忽思莼鲈。","顾荣乃酣饮，废职徙中书。","人臣尽明哲，王室谁为图。","鹿车乘伯伦，荷锸随一壶。","未死而计埋，设心何能无。","当时以为贤，逐名多近愚。","此身苟可遗，穷达恒晏如。","才势两俱窘，方寸吾有庐。","生死亦偶然，毋为豫名模。"]},{"t":"不饮酒二十首 其七","f":"五言古诗","c":["居山三十年，蔬食不过午。","腾腾无所为，于世复何补。","一食已足多，岂敢更奢取。","年迈愧躬耕，赖有同道侣。","兀坐尝思过，勉此安心处。","惺惺尚不堪，悠然见前古。"]},{"t":"不饮酒二十首 其八","f":"五言古诗","c":["省虑道之媒，省事道之贼。","世无无事人，欲省省不得。","细氓营一家，君子匡王国。","优游泉石士，所计维衣食。","计食岂不耕，计衣岂不织。","一衣足三年，再食日始昃。","耒耜良苦辛，将以解微识。","饱煖无馀情，千峰影自息。","即使长饥寒，我心终不惑。","此语寄世间，各各当努力。"]},{"t":"不饮酒二十首 其九","f":"五言古诗","c":["中士重名教，上士慎幽独。","幽独吾自知，寤寐徒往复。","心一境乃空，观化成相续。","绝物岂不劳，讵更徇所欲。","醉者之堕车，不死焉足赎。","苦雾积寒林，微香汎石屋。","破衲深蒙头，不真亦不俗。","此士过华胥，风味似天竺。"]},{"t":"不饮酒二十首 其十","f":"五言古诗","c":["结宇崇厓下，冬景多寒云。","飞雁迷云中，空有声遥闻。","日出已近西，群峦列馀曛。","千仞临江湄，暮帆微见人。","远睇在天上，下视水无粼。","我乃不知处，思共谁为邻。","坐对晚甘侯，头无漉酒巾。","清歌每竟夕，翛然忘极贫。"]},{"t":"不饮酒二十首 其十一","f":"五言古诗","c":["我有一枝藤，尝拄海蠃巅。","东南抗巨灵，北与楚云连。","目不接千里，江山常现前。","青嶂皆崒嵂，排叠成蜿蜒。","桐椅昼森森，灵鷟翔翩翩。","幽谷产奇葩，临厓喷飞泉。","中有凌霄台，登高望神仙。","驾鸿乘空来，上下生紫烟。","此岂梦中事，亦非意云然。","太白醉一斗，酒中无百篇。","我无太白才，宁当醉时诠。","愿听予一曲，长谣叹无缘。"]},{"t":"不饮酒二十首 其十二","f":"五言古诗","c":["生亦我所欲，一死不可逃。","东吴有张悌，可以励士操。","牛渚至今在，江水空滔滔。","今日我死日，仲思安足邀。","曾受丞相知，常恐负贤豪。","贤者讵不重，知己诚难遭。","此心苟可已，角巾归蓬蒿。","人生贵适意，痛饮读离骚。","何自苦乃尔，九原无醇醪。"]},{"t":"不饮酒二十首 其十三","f":"五言古诗","c":["一冬风不劲，豫料春寒凓。","气序有盈亏，但以往岁则。","新谷止初夏，旧絮尚一袭。","人事可先谋，尽力一百日。","过此何必知，且勿计得失。","世人解穷愁，多赖杯中物。","我意不如此，百情当自抑。","假使卒然至，有酒饮不及。","试问华亭鹤，何不蚤种秫。"]},{"t":"不饮酒二十首 其十四","f":"五言古诗","c":["人情如溃川，一决辄瀰瀰。","川溃赖堤防，情流曷以止。","欲止不可止，但观情所起。","万物皆由情，万情皆由己。","情本由己起，亦复由己止。","借物以移情，一止又一起。","一起不再起，一止不更止。","起止如浮云，碧落长如此。","堪笑陶渊明，乃以止利己。","请观未止时，己已终何似。","胡为逐清颜，顿忘千万祀。"]},{"t":"不饮酒二十首 其十五","f":"五言古诗","c":["古今有高士，借酒以自适。","不知醉翁意，相效竟成滑。","才滑适清狂，贫滑适放越。","滑世抱牢骚，滑化仇形魄。","为乐乃得苦，百情徒役役。","巽坎安其常，哑然见畴昔。","持此狎田畯，悲欢共晨夕。","慎勿与人异，异处终变易。","远睇碧空尽，万载无广厏。"]},{"t":"不饮酒二十首 其十六","f":"五言古诗","c":["人生皆劳劳，尔独放山泽。","瓮头无春醅，何以百骸释。","我亦不自知，少小耽泉石。","地远世情疏，心閒形不役。","山深闻午鸡，清谈少游客。","不欠酒家钱，安眠竟至夕。","开户常阒然，空对石岩白。","将以乐馀年，讵辨阡与陌。","修短总由天，九十或一百。"]},{"t":"不饮酒二十首 其十七","f":"五言古诗","c":["莫道黄虞邈，至今有遗民。","茅房因树缚，倚石临高深。","佳禽时复鸣，可以悦素襟。","丰暇移短榻，远近藉层阴。","长幼能玄谈，相与晰古今。","此乐非世间，负苓或其邻。","往往一告语，反以为醉人。","人醉不知足，我醉不知贫。","寒风入蔽庐，衣薄多酸辛。"]},{"t":"不饮酒二十首 其十八","f":"五言古诗","c":["吾生亦云足，尘网曾一羁。","父母解此意，山林相与归。","肥遁岂当易，至今有馀思。","少壮事场圃，耆迈少提携。","晨兴欣绿畴，日入散长堤。","返照上墟烟，村井行人稀。","暮鸟度河阳，倒影随舟移。","好景多在晚，正当人醉时。","寿极至一百，一半无所知。","不如远嗜好，使心常希夷。","大道难为言，聊以豁沉迷。"]},{"t":"不饮酒二十首 其十九","f":"五言古诗","c":["尝因今夕欢，攒念昔人迂。","鉴彼天禄阁，回车就溺沮。","相与挈壶觞，愿言忘居诸。","居诸良易忘，荣瘁行须臾。","灵爽托营卫，岂遂同虚无。","此生苟可达，后视今何殊。","缮性弗及时，空令年运徂。","见闻从物化，安得复其初。","泽涸多异同，叹息园中蔬。"]},{"t":"不饮酒二十首 其二十","f":"五言古诗","c":["天道不可知，可知惟寸心。","荣落归自然，不动如昆崙。","委化成丧志，灾沴乃见侵。","忠信自有道，生死自有伦。","抱柱不是愚，汨罗无知音。","守一谁与明，情极难为任。","骨肉匪所爱，报称宁一身。","九原如有知，哀怆何异今。","沧海变桑田，古今多陆沉。","弦筈不停晷，念念空相寻。","悟此复何为，渊然返吾真。","朗鉴犹昔时，何必为醉人。"]},{"t":"不厌酒","f":"五言古诗","c":["我得酒中趣，醉卧山之阴。","清醑不入口，沆瀣消形神。","怡然百虑息，万缘如游尘。","对境无寂諠，对人无疏亲。","顺之不禁喜，逆之依然瞋。","对水白茫茫，对山青嶙峋。","寒煖别冬夏，上下空古今。","此醉无醒时，不如世间人。","世人多感激，所恨吾有身。","愁中浮大白，将与无何邻。","累月亦有閒，千日防醒心。","一醒安能醉，忧患仍相寻。","俯仰大槐宫，闲杀洞庭春。","何时到江南，雪压渔船深。"]},{"t":"严霜篇","f":"五言古诗","c":["严霜下原隰，秋草日以衰。","游宕思乡井，飞禽重徘徊。","庭柯畏金丸，参天怒冯夷。","寒猋忽朝夕，高木先折摧。","岂无劲羽翮，不离故山枝。","故山不可离，寒猋无已时。","巢卵讵复惜，托足良多岐。","南翔盼北岫，东集念西驰。","饮河惊浅浪，野田农人欺。","仰见云间雁，悔蚤不追随。","晚尚未易决，奋翅何忧迟。"]},{"t":"黄鸟歌","f":"五言古诗","c":["黄鸟翔高岑，徘徊若为匹。","渴饮西江湄，饥餐山木实。","一旦饵稻粱，乃坠虞人术。","金羁勒良驹，谁怜千里质。","翘首东南飞，怆然怀昔日。","岂不奋天路，瞻恋成胶漆。","晴空阔且长，迢遥盼崒嵂。","往者何能追，时乎安可失。","浮沉复浮沉，老死终无述。"]},{"t":"摘茶八首 其一","f":"五言古诗","c":["南方有嘉木，穿地一二尺。","其树如瓜芦，孤根终不易。","尝产丹丘山，服之生羽翮。","海蠃烂石中，春至颇堪摘。","虽非穆陀种，可以愈瘕癖。","一饮营卫舒，再饮寤终夕。","三饮通神明，清风起两腋。","采采勿伤株，伤株枝叶竭。"]},{"t":"摘茶八首 其二","f":"五言古诗","c":["先春秖有一，托根乃见异。","荒瘠本从天，沃土非所寄。","生长千峰上，饱饮烟霞气。","石花首剑南，紫笋湖州次。","不关物性纷，禀受亦足累。","天宇固自真，见闻岂容易。","甘露既在手，安得子尚味。","双林傅大士，结庵颛所事。"]},{"t":"摘茶八首 其三","f":"五言古诗","c":["三春日云暮，言采东山薇。","薇熟兼粝香，日永食易饥。","正午彊加餐，既饱神昏疲。","一觉至西逝，倒照疑朝晞。","谁当过鹙子，饮我霜华杯。","双眸忽如电，群峦依旧时。","微猋散林薄，夕景上楼台。","行旅望村烟，蠃角四山催。","落落孤云外，远见耕锄归。"]},{"t":"摘茶八首 其四","f":"五言古诗","c":["日暖气初敛，抽芽畏春霖。","蒸焙贵当时，活火候晴岑。","睡足与禅足，一杯松风吟。","傥家安足识，相对维白云。","宁可作苍头，不慕王侯珍。","绝色当谁辨，素涛兼玉尘。","予意岂在兹，七盌无馀心。","一日两三回，振枯散遐襟。","此味播九区，陆羽非知音。"]},{"t":"摘茶八首 其五","f":"五言古诗","c":["昨日采新笋，上上蠃峰巅。","报道蝉翼肥，今年胜往年。","当暑庶有赖，不学黄山仙。","住山先种茶，次乃言耕田。","耕田百日功，种茶期三年。","饥渴不切身，身泰心悠然。","客至粟一盂，烹葵当割鲜。","继以惊雷荚，带露和春烟。","岂秖六不羡，还待日高眠。"]},{"t":"摘茶八首 其六","f":"五言古诗","c":["瑞草产高山，乃不受灌溉。","鲜妍漭沆间，何曾别天地。","遇浊混不齐，清中煞有味。","自洁涤人烦，于物匪无利。","寘之邦国上，难与邾莒比。","时或逢高人，大瓢聊以试。","白云浮太虚，骤雨松声细。","岂必登蓬莱，只在玉泉寺。","我也沾馀沥，释然薄兰芷。"]},{"t":"摘茶八首 其七","f":"五言古诗","c":["茗能祛肉毒，又能解宿酲。","肉毒中身浅，中心当奚平。","举世皆醉人，谁为沃寒清。","我无此二疾，携瓶趁早春。","出山云作沫，拂水暖猋轻。","岂直扶颜色，将以濯馀生。","武夷栽自昔，至今空知名。","不可献天子，萱带徒自荣。","当时苏学士，极口羡甘馨。"]},{"t":"摘茶八首 其八","f":"五言古诗","c":["酌水贵知源，须是石头城。","缥色入磁盌，水蔎难为名。","善饮不得味，谁闻月涧声。","冷煖何关舌，云外获其真。","能仁当自别，祇有蔡先生。"]},{"t":"采兰","f":"五言古诗","c":["幽兰产深谷，不与众卉争。","杂之蓬蒿间，桃李非其伦。","岂不羡红紫，梁园多俗情。","芬郁世所慕，几人披荆榛。","春风吹春草，习习带馀芳。","独茂谁为伍，援琴聊自鸣。","闻香思王者，龙虎兆嘉名。","采采纫作佩，终焉怀生平。"]},{"t":"种菊二首 其一","f":"五言古诗","c":["万卉各有奇，潜颖候春泽。","茂林郁佳气，苍茫竞红白。","霖泽殊未终，春开复春落。","芳菲不到秋，讵关覆载薄。","梧桐一叶飞，草木皆萧索。","独立何煌煌，黄金曜霜萼。","岂不畏寒猋，抱一从旅泊。","将以贻幽人，遐襟恣磅礴。","晚登君子志，硕德须早植。"]},{"t":"种菊二首 其二","f":"五言古诗","c":["南阳山上水，饮之臻遐龄。","武林曹太虚，种菊盈户庭。","红子如樱桃，大黄当心生。","邻女良宿缘，摘食乘风轻。","又有楚屈平，冉冉餐落英。","长生匪予志，牢骚匪予情。","所爱甘且芳，当秋能独荣。","山林鲜秀实，聊以同其人。","晨兴荷锄畚，殷勤趁残春。"]},{"t":"种竹二首 其一","f":"五言古诗","c":["丹霞多异木，筼筜别一山。","常恐绿阴短，分植诸岩端。","天帚不可偏，横扫碧空烟。","碧烟无尽时，此帚天门悬。","阳屿有平石，名之为仙坛。","方广十丈馀，四围青琅玕。","风来动遐音，宫商自成弹。","相传羽化人，石上去不还。","洁净无尘箨，至今空盘桓。","我非爱方士，爱此清风寒。","敢效李卫公，日报竹平安。"]},{"t":"种竹二首 其二","f":"五言古诗","c":["昔有文与可，閒居维独笑。","笑笑终无言，写竹发其妙。","当时少人知，秖有东坡好。","何如武林山，两两相比肖。","幻者尝似真，似真真不较。","寒玉一溪烟，渭川千亩道。","抱节葛龙迁，作花丹凤到。","树之为庭实，君子多所效。"]},{"t":"种蔓菁","f":"五言古诗","c":["东畴秋已获，西岭锄荒芜。","将以植蔓菁，来春调苦蔬。","有粟不畏饥，肥羹胜薄酤。","可以乐晨夕，岂更求有馀。","运促虑欲远，景迁情易徂。","万事毕目前，毋为事踟蹰。","堪笑东陵瓜，后世名其庐。"]},{"t":"负薪","f":"五言古诗","c":["冬月不积薪，春来雨淋漓。","新木烟熢熢，犹胜无薪炊。","三旬闭岩谷，日出仍稀微。","人力向青林，候化宜先时。","荷笠行云中，脚下从水泥。","错过讵复忆，迄今且奚为。","斧落木自折，缚株不去枝。","四顾志欲满，横千随人归。","一回忙里得，寒暑宁再违。"]},{"t":"劝耕二首 其一","f":"五言古诗","c":["古者重力田，自信无所疑。","阳城犹畏人，奚比历山时。","南阳终勿出，岂维帝者师。","外瞻内且啬，名实恒相亏。","况我巢居子，只有食与衣。","无衣终岁寒，不食一日饥。","饥寒频叩门，不如苦耕犁。","人生贵微尚，手足匪所私。","吾道无所为，百虑捐耒耛。","此意惭农夫，农夫当胡为。"]},{"t":"劝耕二首 其二","f":"五言古诗","c":["人言一岁苦，所志在秋穫。","营营商贾心，不知苦中乐。","一镬更无馀，今日忙如昨。","晨征入云烟，微昕见飞鹤。","午食藉畦蔬，藜羹任斟酌。","腹果力气粗，一斫一株落。","远近归牛羊，万山沉日脚。","暮鸟随人声，呜呜绕松彴。","青萤高复低，蟾影摇屋角。"]},{"t":"听泉","f":"五言古诗","c":["晨起启山户，长天空一色。","俯瞰江山遥，高深靡所极。","山上松风喧，猿啸禽虫唧。","飞湍走千溪，人语交相集。","众响成奔雷，师旷焉足给。","仰见烟云流，平观群木立。","心随耳目迁，欲返返不得。","于焉西阳沉，忽尔万象入。","风静树不摇，鸟宿众兽匿。","解衣就床眠，远听流泉急。","不将双耳迎，涓涓到胸臆。","吾臆安可逃，泉声岂当默。","上下自乾坤，勿以音象惑。"]},{"t":"喜雨","f":"五言古诗","c":["九旬淋雨少，一夜足三秋。","凿石引千尺，迢遥下林丘。","接竹竟至炊，聊以息担头。","汤茗既以丰，亦复滋田畴。","山客愿易足，稻蔬无多求。","翛然天地内，一饱忘百忧。","山色可饫目，耳醉泉风飕。","信手随乌藤，濯足沧江流。","百骸各自娱，岂更羡王侯。","王侯学我易，难逢林下休。","举眼渔樵人，将无为我俦。"]},{"t":"寒食","f":"五言古诗","c":["一月断烟爨，相传为介推。","割腕心何切，抱木情何哀。","黍饭与醴酪，终不入泉台。","忠谊反见疏，古今多疑猜。","岂果有斯事，闻歌皆徘徊。","雕卵染蓝茜，千秋后殿开。","无限今人乐，安知昔人悲。","柳风起新火，又到清明时。"]},{"t":"上巳","f":"五言古诗","c":["屋倚千尺厓，门临九曲渊。","欣逢上巳日，芳春犹及妍。","山客忘新故，褉韨仍世传。","护生非千金，石泉如天泉。","渌水宕丹峰，回流濯繁鲜。","野服薄连绮，藉草誇琼筵。","胜事追古人，周秦肇何年。","华林岂维昔，西池今犹然。","乐极悲相随，此理无深玄。","代不乏哲后，亦复多豪贤。","宴赏正当时，叹息忽在前。","落花不上枝，归禽逐后先。","对此惜良晨，景过生人怜。"]},{"t":"久雨弗止","f":"五言古诗","c":["天泽岂厌多，春泥行深耕。","九州沾易满，一暴新苗焚。","阳石不可鞭，草木倚玄冥。","宁使白日烈，不愿天无云。","烈日枝可濯，土乾根难萌。","犹忧榆筴后，田上无焦明。","二月园蔬足，三四稻粱生。","稻粱终岁望，蔬蓏四时更。","讵直予中心，普天翳同情。","盼盼祥风起，濛濛垤鹳鸣。","不以柴门掩，眷焉怀暂晴。"]},{"t":"登海蠃岩顶定舍利塔址","f":"五言古诗","c":["三春风日丽，抠衣登重基。","千仞插青霄，八方蟠龙骊。","呵护自何年，乃以藏吾师。","妙高高不见，别峰长委蛇。","化城极西北，宝所良在兹。","渊源大东南，银河天上来。","顿超十九地，鬼神安在哉。","再涌金轮巅，负铁予宁辞。","稽首大觉尊，长跪遥致辞。","清净本如然，法化终无岐。","此山曾有无，天龙焉足知。","灵光曜今日，云烟犹昔时。","星日绕檐楹，幢铃摇须弥。","多子谁后先，万古将不疑。","稽首大觉尊，天宇空恢恢。"]},{"t":"秋日山居","f":"五言古诗","c":["掩室白云巅，瞑坐声光灭。","灭处不能知，渐返觉通彻。","目入纸窗明，耳透泉声咽。","开户风飕飕，秋山天气冽。","携筇过竹坡，径转秋虫切。","所遇山中人，但笑而无说。","我观笑中怀，千偈难分别。","以此尽世间，一切言应绝。","说天天无名，说地地无辙。","山色与泉声，谁道广长舌。","未说是非无，说已是非绝。","正说是非时，如闻隔垣垤。","瞋与喜何从，相对言辞拙。","日日瞑坐中，长笑当不辍。"]},{"t":"中秋无月","f":"五言古诗","c":["中秋五夕前，寻凉登紫玉。","皓魄悬高岑，影散千林浴。","万里无片云，横眸九霄瞩。","耸身淩星辰，转觉澄汉局。","语笑停空中，信步天路促。","晨起理盘餐，片鳞追隔宿。","微云瞹太虚，桂影羂罗縠。","及望晷愈乖，夕赏且继烛。","班荆坐檐下，情殷景自淑。","底事维目前，慎莫期后复。","气序不可知，人事亦反覆。","澹若忘固然，美景焉可续。","委运乐无穷，天真吾自赎。"]},{"t":"九日","f":"五言古诗","c":["观水水初涸，登山山渐寒。","水涸尚可汲，山寒磨衲单。","衣单当彻骨，汲井领斜看。","谁把茱萸酒，凭谁为整冠。","菊花开灿烂，涧水急潺潺。","何处不相似，狂歌到日残。"]},{"t":"孤雁","f":"五言古诗","c":["数年闻雁声，感慨多所系。","今年声愈悽，一雁落天际。","念彼百千雁，存没何能计。","哀此一雁孤，一去不知岁。","羽毛亦自美，江山岂不丽。","死生物之常，何地不足瘗。","所伤共一群，先后终难逮。","薄影沉西江，秋风吹浪细。","江月夜夜寒，不敢翘清霁。"]},{"t":"访菊","f":"五言古诗","c":["秋色澹欲入，携筇访山菊。","林幽山径迂，香气散松竹。","坐石良欣然，毋劳更仆仆。","世人爱见花，见花徒悦目。","悦目曾几时，鲜美限宵夙。","荣枯何苦知，春温而秋肃。","我亦随化迁，馀龄信幽独。","物理返自然，神智空攒簇。","飕飕朔风起，万景沉山谷。","举头寒月西，晶晶照茅屋。"]},{"t":"望归鸟","f":"五言古诗","c":["霜气横秋雯，暮鸟归何迟。","犬疾墓草枯，风劲冥鸿坠。","苍茫云树中，目极百忧萃。","人各有其怀，浅深随所寄。","景物感凋衰，抚心时一慨。","阮藉穷途哭，荆轲易水泪。","首阳伯叔歌，东篱彭泽醉。","孤英与节烈，情愫当无二。","茫茫靡所归，安得不丧志。","我昔二十馀，怀古多寤寐。","缅想百年终，身没名何为。","愧彼巢居人，万感消食睡。","茅茨三两间，言笑有真意。"]},{"t":"望归人二首 其一","f":"五言律诗","c":["岁暮怀归人，苍茫云木外。","登高不可见，入室闻寒籁。","髣髴檐下声，捲幔日已昧。","日昧犹平时，对此偏无奈。"]},{"t":"望归人二首 其二","f":"五言古诗","c":["山泽谁不乐，衣食岂自然。","叩门良有时，淹滞将穷年。","一诺未云易，宁更嫌迁延。","世间重财宝，慷慨安得兼。","客心久已降，节序无后先。","市井归人忙，对之如夜禅。","俛仰匪我畏，所畏在脆坚。","中愿苟或谐，可以遂林泉。","归期知随人，吾心徒拳拳。"]},{"t":"伫立","f":"五言古诗","c":["伫立松根久，秋风吹敝衣。","回望万山合，山高身愈微。","茕茕百岁人，寒暑恒相违。","嗒然忘形骸，万里如初归。","廓落匪宇宙，目前徒清机。","视听还寻常，色响仍昔时。","沙静归鸿晚，溪深落叶迟。","白云终何来，明月寒更辉。","一滴鼓洪溟，古是今谁非。"]},{"t":"长啸","f":"五言古诗","c":["长啸千峰顶，下方闻不闻。","倚杖落红叶，开畬烧白云。","云端邈天际，不见其中人。","树下一敛目，隔山来斧斤。","丁丁彻遐迩，寂感乃愈纷。","声象体自玄，圣哲无所云。","坐起翘青冥，高低阳雁群。"]},{"t":"梦","f":"五言古诗","c":["世间维有梦，可以识吾心。","见闻铄觉知，动止久非真。","譬如镜里像，万状无疏亲。","中宵悬崇台，形影安所陈。","忽当炬与日，始悟光生尘。","梦中境何从，只是床上人。","觉知不及谋，一息成古今。","寸心岂出入，翕辟谁为因。","登高揽八方，邈然散遐襟。","所见皆人外，海岳摇参辰。","驰目不能返，焉知吾有身。"]},{"t":"萤火","f":"五言古诗","c":["腐草生岂易，飘零信此身。","谁怜玄夜苦，微光远趁人。","白日不可见，难为平旦心。","冥冥泱漭中，随风忘高深。","迢迢自星汉，所照非长林。","烈炬限华堂，耿耿遗中情。","夕露安足畏，晨晞吾独矜。","聊以托荒秽，薄翅且从今。"]},{"t":"疾风","f":"五言古诗","c":["疾风欻然至，无人窗自开。","折木震岩谷，黑云变楼台。","耳目不为易，知非大块颓。","死故从所生，宠辱恒相推。","物理本自然，而乃重徘徊。","此疑尽一世，终古无能裁。","绝虑求真诠，冥然失从来。","一觉山雾晴，万壑馀清哀。"]},{"t":"酬客","f":"五言古诗","c":["客问我何意，萧然住此山。","我答客何愚，何不观我颜。","我颜又不戚，我心何曾顽。","我非武陵人，亦非南阳贤。","又非无为谓，终日长窅然。","一衲三十载，夏热冬犹寒。","客至无美酒，烹葵酌流泉。","相对无游辞，所举楞伽篇。","日入群动息，连床同夜禅。","终宵松风声，至晓不得眠。","我有懒瓒计，放足且随缘。","觉来日已高，此诀不可传。"]},{"t":"莫厌贫十二首 其一","f":"五言古诗","c":["人生莫厌贫，厌贫多所许。","食贫许粱肉，始觉薇藿苦。","衣贫许章黻，皮褐畏予侮。","粱肉岂不甘，所恶呼尔与。","章黻匪不华，君子贵自处。","凤凰巢椅桐，游鱼乐繁渚。","上下忘其天，各自矜鳞羽。","离离田上苗，丁丁远山斧。","田窦虽足歆，宵旦移寒暑。","萌隶终岁赡，毋宁询季主。"]},{"t":"莫厌贫十二首 其二","f":"五言古诗","c":["水木彻上下，飞潜尘外迥。","静言冥初终，风物各自永。","閒者得其真，此岂富贵谂。","所遘良足多，空庐抱寒影。","玙璠但有名，明月惭独醒。","噭噭嗟陆沉，安所贵颜闵。","海鸽不是雀，入淮雉作蜃。","贞脆忽不觉，久暂成松菌。","东谷悲凄风，去雁遗玄景。","弦望互相催，晚节当谁秉。"]},{"t":"莫厌贫十二首 其三","f":"五言古诗","c":["贫贱无长虑，富贵有深嗜。","多嗜常多忧，薄虑鲜所蔽。","人情类皆然，是亦焉足概。","往昔古帝王，自视若胥隶。","持此贫贱心，行吾所无事。","衡门栖迟者，所贵非寡累。","一身不足营，万物我皆备。","逍遥托巢许，黾勉夔龙志。","即使长独处，耦耕岂不愧。","植杖竟何人，岂以隐显异。"]},{"t":"莫厌贫十二首 其四","f":"五言古诗","c":["人生贵寸心，所感易汨没。","顺风扬灰尘，寄托终不择。","自古得意事，贤士多困折。","浮荣果霜实，不如守岩穴。","寤寐恒勿忘，动止信前辙。","美人自迟暮，何辞愆岁月。","肃此励芳晨，慎修匪明哲。","三闾不可学，渔父羞灭裂。","悠悠时运迁，毋徒伤井渫。"]},{"t":"莫厌贫十二首 其五","f":"五言古诗","c":["崇基临荒泽，松柏生其间。","讵以霜露零，孤根移岁寒。","晚穫收良田，幽香迟秋兰。","时物良有然，吾将乐考槃。","汉祚久已易，此世无彭韩。","隆替还乘除，运去身名閒。","原始要厥终，吾生岂漫漫。","见闻如逝波，心知不可还。","昏觉当为谁，悠悠须自观。"]},{"t":"莫厌贫十二首 其六","f":"五言古诗","c":["海岳无真幻，古今多修短。","云里怪石巉，波中古木浣。","晨风鸣高林，烟雾宕空满。","相对尽竟日，过目徒窾窾。","朝贵勋名驰，野贱约心款。","心境两相外，嚣寂成乖沴。","乃有感慨士，兴怀寄繁衍。","凌云登崇台，悲歌恣凄泫。","又有逃虚者，绝物以自善。","豕鹿游无人，俛仰情俱缅。","山色连溪光，红绿春深浅。","万汇体恒玄，至今不可辨。","告汝岩谷居，莫当欣厌遣。"]},{"t":"莫厌贫十二首 其七","f":"五言古诗","c":["颜氏乐圣道，陋巷匪所矜。","孔门七十二，一士称安贫。","蔬水曷云易，饥寒托生平。","生死尚殊涂，未可言忘形。","夷齐饿首阳，季路犹结缨。","节烈轻一时，古今皆有名。","名与实俱捐，吾以观其心。","椮椮东岭松，悠悠西山云。","渺渺金乌坠，亭亭玉兔升。","子期不复作，千古谁知音。"]},{"t":"莫厌贫十二首 其八","f":"五言古诗","c":["昆崙不可窜，戾天有飞翰。","岩穴不可藏，高冈犹追随。","巨渊不可入，浮沉将何之。","不如共一处，动静相因依。","父母岂我欲，天地岂我私。","柴门设不关，蒿床聊自支。","慎勿为楚相，楚相安足为。","尽忠以至死，其子无立锥。"]},{"t":"莫厌贫十二首 其九","f":"五言古诗","c":["原宪并日食，端木出连驷。","两贤恒相从，只有叹已耳。","道胜无怨尤，夜耕可卒岁。","世岂乏刘龚，人生贵立志。","荣叟年九十，带索乐弗匮。","所造吾安知，豁达庸何易。","几死之散人，优游同直寄。","自古笑亡羊，殉名如殉利。","待激西江流，索我枯鱼肆。"]},{"t":"莫厌贫十二首 其十","f":"五言古诗","c":["山泽罕人事，与世颇无干。","启户朝云攒，及午始见山。","暄风爽林际，景落絺衣寒。","田圃各西东，荷锄当暮还。","树里课勤惰，杂言忘辛酸。","岂守固穷节，吾分应如然。","四海无亲疏，去住各有缘。","草木春夏繁，天气秋冬妍。","日夕省营虑，丰约随目前。"]},{"t":"莫厌贫十二首 其十一","f":"五言古诗","c":["弱冠不知道，抱志志四方。","读书慕先贤，设心追上皇。","蒿日切时艰，夙夜矢济匡。","寒云起西北，中原临苍茫。","千羽投西江，感物情惨伤。","天运不可回，猖狂归山阳。","岂惜饥与渴，念彼兰桂香。","兰桂生幽谷，不畏秋露霜。","秖忧荒秽杂，逵路无津梁。","眷言怀斯人，揽衣起徬徨。"]},{"t":"莫厌贫十二首 其十二","f":"五言古诗","c":["徬徨守先训，焉敢欺后昆。","此世无是非，同异徒相因。","吾道流为名，久已丧厥真。","性澹时愈乖，安得不长贫。","孤踪岂足尚，黔娄乃无邻。","矫俗非夙志，维当尊所闻。","偃鼠腹易满，促弦无缓音。","去去勿复道，终焉从予心。"]},{"t":"铜雀台","f":"五言古诗","c":["谁道昔人痴，穗帏犹昔时。","昔时人皆慕，今日人皆悲。","亭亭西陵台，歌吹声迟迟。","不关歌吹异，人心有盛衰。","飞甍一百二，连接烟云垂。","玉盌盛脯粻，琼浆上金卮。","此乐极生平，死亦安能离。","当令泉下人，长闻铜雀辞。"]},{"t":"南阳李鉴湖寄桃杏核各数百颗","f":"五言古诗","c":["武陵不可入，岂复访蓬瀛。","中州有奇士，携家来海滨。","选胜丹之丘，侨居最上层。","琴书藏石室，鸡犬云中鸣。","皇天何辽辽，激烈星辰横。","伯氏不吹埙，悽恻泪沾巾。","家人怀桑土，扶榇向舂陵。","云烟还长空，丘壑付隐沦。","墨池后芳泉，紫玉绍金轮。","昔居不种桃，始以见厥心。","今寄维缃核，千里托中情。","释此毋片言，当歌歌不成。","重台朱千仞，回渊绿一泓。","还将旧时月，相待故山人。","松桂寒无恙，莫当桃杏阴。"]},{"t":"陆太守孝山入山","f":"五言古诗","c":["世荣讵不慕，所贵维物外。","但识电火机，何辞金印大。","古者不贱目，偶与水云会。","今贤有奇情，往返丹山旆。","丹山指二千，居食恒依赖。","感激发微言，欲解东坡带。","万汇自乾坤，焉有函无盖。","起唤陆大夫，庭株落寒濑。","摇摇空影中，相对岂梦事。","纵使百千劫，春光今夕在。"]},{"t":"读仞千雁影诗","f":"五言古诗","c":["金风起肃杀，凋落先梧楸。","知时贵哲人，不如鸿雁俦。","噭噭鸣青天，徬徨向南州。","气序乃相逼，匪为稻粱谋。","伟哉求寂士，睹影发清讴。","寒暑识代谢，物化冥显幽。","悟理捐形骸，色空生双眸。","玄景靡所遗，江山亦不留。","俯仰彻上下，所见皆浮沤。","万物同一雁，羽翼空绸缪。","象类常寂然，圣人行多忧。","憬然知无从，岂羡乘云游。"]},{"t":"寄旋庵都寺","f":"五言古诗","c":["人生贵自处，劳劳欲何为。","岂不怀丰功，动静宜知时。","尔年五十四，百岁半过之。","年年徇土木，日日计度支。","山菊与溪梅，梦中相对谁。","我年日以迈，尔少只数期。","纵使更百龄，所忧常别离。","何如松桂侧，竟夕论心期。","山芋可继粟，荒年恒不饥。","语笑皆羲轩，而无衰世疑。","灵龟未易舍，观我徒朵颐。","随身登古台，下视西江湄。","飞帆去如鹜，安得暂相随。","念尔如飞帆，汨汨寒风吹。","欲倾万斛怀，千里重踌蹰。"]},{"t":"寄黄山还生二首 其一","f":"五言古诗","c":["闻君隐黄山，仍戴竹皮冠。","去秋飞一札，看看度岁寒。","约我当春来，又是桃花残。","运化一何易，相见一何难。","山深多白云，玄鸟今复还。","欲倚千尺松，为君筑净坛。","老眼望已穿，踟蹰空长叹。"]},{"t":"寄黄山还生二首 其二","f":"五言古诗","c":["此日为何日，鹪鹩巢深林。","一枝岂不择，满腹何沉吟。","丹山亦有河，饮啄随天真。","为君假羽翼，翱翔垂秋云。","怀袖宁三年，字字感予心。"]},{"t":"悼离言","f":"五言古诗","c":["寒猋自西北，薄曙凄中林。","揽衣起徘徊，慷慨怀昔人。","寿不及颜子，而有乐道心。","担笈三千里，六七年于今。","风雨守穷檐，抱志暂安贫。","念此冰雪姿，意气干星辰。","精锐造物妒，乖沴中肺金。","适予移茅屋，扁舟发榕阴。","依依向长薄，帆没海烟深。","到山始一月，遽然闻讣音。","盼望绝云涛，中宵情莫任。","为学苦不蚤，清标负高岑。","自夏复徂冬，驱隙忽骎骎。","犹忆别离时，美言竟斯晨。","九仞亏一成，石上空微因。"]},{"t":"读大唐西域记十三首 其一","f":"五言古诗","c":["世无转轮王，赡部有四主。","人主南面尊，上下中规矩。","象主清心累，声教流东土。","刑名所勿逮，可以翼周鲁。","贞淫通三世，功高于伯禹。","生当仁义邦，复饮五天乳。","一苇从西航，儿孙安足数。","努力同斯人，毋宁负前古。"]},{"t":"读大唐西域记十三首 其二","f":"五言古诗","c":["屈支有明王，崇道事黄发。","游览历遐方，爰用访奇迹。","监国属懿弟，谊重将安适。","割势封金函，丐俟驾旋发。","厥后成搆祸，因兹竟获白。","亲爱日以隆，出入排庭阙。","路逢五百牛，刑腐在旦夕。","自念形体亏，宿业不可谪。","竭赀解牛厄，愿藉慈善格。","形体乃复具，始以辞宫掖。","王闻叹奇哉，厚宠旌其阀。","仁智良不诬，设心当在昔。"]},{"t":"读大唐西域记十三首 其三","f":"五言古诗","c":["将夕云霞变，玄景忽已灭。","中宵霁光风，薄曙春寒冽。","境迁情屡易，识纷智乃汨。","文句竞华质，高明神理滑。","见闻遗所知，焉得心路绝。","展转名义兴，玄解肆分别。","谁作声明论，今日何曾劣。","童稚匪他人，秖昧当年说。","五百阿罗汉，豁然成超越。","迦匿弥罗时，髣髴枯树穴。","莫倚渊镜微，皓首不能决。"]},{"t":"读大唐西域记十三首 其四","f":"五言古诗","c":["睹史多上人，大庵没罗心。","未断铦刀舌，善来莲花身。","三年不相报，六月下阶庭。","相好不可言，妙音谁与闻。","一人乃多形，一心乃多因。","多形人岂幻，多因心自真。","先后俱不到，春风吹蚤林。","万木一时茂，天上亦成阴。"]},{"t":"读大唐西域记十三首 其五","f":"五言古诗","c":["作善乘权贵，权贵岂能长。","展布不及时，徘徊徒心伤。","一赡部洲主，半阿摩洛王。","积宝非己有，力弱心乃彊。","此是最后施，施心安可忘。","铁轮威已尽，鸡园羹独香。","巍巍窣堵坡，日月摇恩光。"]},{"t":"读大唐西域记十三首 其六","f":"五言古诗","c":["印度毕钵罗，空劫来迢迢。","茎叶青且翠，冬夏恒不凋。","中有千圣座，下极金刚牢。","大地悉震动，此处无倾摇。","伐树不留根，枝柯就焚烧。","烟燄尚未静，火中仍参霄。","人天安足护，灵株终条条。","欣厌各自为，培覆空徒劳。"]},{"t":"读大唐西域记十三首 其七","f":"五言古诗","c":["尼连林外池，香象侍母处。","采藕汲清泉，于世复何与。","林外有人声，徬徨悲失路。","象导人以归，人指象往捕。","岂待两臂落，方知鬼神怒。","幽厄本自甘，盲母谁为哺。","仁王自有心，上帝日临汝。","名利终当尽，此心安可负。"]},{"t":"读大唐西域记十三首 其八","f":"五言古诗","c":["屈屈吒播陀，三峰挺绝崿。","尊者迦叶波，受嘱于中托。","捧持金缕衣，敬候慈氏作。","三会法已周，憍慢当谁药。","登高一弹指，山开见无学。","授衣仍致辞，先后无二觉。","乔木映丹厓，白云迷归鹤。","灵鹫尚俨然，岁岁花荣落。"]},{"t":"读大唐西域记十三首 其九","f":"五言古诗","c":["帝释窟之东，渐教昧随机。","三净安得常，仰见群雁飞。","诒言众食乏，应声投身遗。","悲感动见闻，执情终以移。","人岂不如鸟，圣化良有时。","至今窣堵坡，照耀同吾师。"]},{"t":"读大唐西域记十三首 其十","f":"五言古诗","c":["网罟不可设，匪但戕群生。","禽鱼多异迹，隐显难以明。","大鸽济罗者，乃是金仙身。","深慈聊尔尔，所矢终何心。","仁暴性靡常，迁延宁至今。"]},{"t":"读大唐西域记十三首 其十一","f":"五言古诗","c":["孤山竟何在，郁郁青树林。","名花间清流，被壑注层岑。","炜煌金阙迥，坐列多精灵。","中间擎莲台，琅琅海潮音。","机感当所求，像外如有神。","予言尽大地，一境无二人。","昏蔽落尘网，万象随心形。","不见僧伽王，目前成异因。","晨起揽清镜，忽然空其身。","遍睹皆多罗，草木四山春。","上有天华冠，赫赫威光迎。","图访至摩竭，镜里曾亲临。","此岂夙所构，因事聊以明。"]},{"t":"读大唐西域记十三首 其十二","f":"五言古诗","c":["维人与兽交，乃以产凶逆。","不信凶逆徒，亦从人类获。","怪哉狮子父，慈心终勿革。","威宁踞长林，万骑尽辟易。","一子当其前，哮吼忽已歇。","剚刃入怀中，忍痛竟至殁。","世人谓之痴，我谓慈无别。","天下皆吾子，覆载及穷发。"]},{"t":"读大唐西域记十三首 其十三","f":"五言古诗","c":["宝洲多美色，可以倾人国。","维有僧伽罗，庶几祛此惑。","大海何茫茫，谁执天马鬣。","骧腾云路中，回顾即淹没。","妖媚岂不工，降心吾有诀。","哀哉五百人，湎淟终难脱。","延祸及宫庭，贵贱同湮没。","悠悠古自今，内外须明哲。"]},{"t":"悼大牛","f":"五言古诗","c":["之子解尘网，相将十五年。","五年予在匡，十年归佛山。","适值分卫时，相见江流间。","为众忘疲劳，精神泽癯颜。","转盼曾几何，须鬓蚤已斑。","客春中深寒，半月不得眠。","愿言病既瘳，长揖陌与阡。","欲返尔形神，侍我巾瓶前。","彊饭始两旬，辄闻随人缘。","菩提萨埵心，岂肯图自安。","忆我入丹山，再睹阳雁翩。","偶逢旧山人，方知竟淹然。","生死安可逃，形魄伤云烟。","觉海空茫茫，静观徒往旋。","谁当谙水脉，安流汎晴川。"]},{"t":"秋夜谣","f":"五言古诗","c":["万里无片云，青霄非所择。","今古一同然，当秋显精色。","归鸟空中真，流星界天石。","湖水入孤帆，水中天更碧。","遥光射群峦，万木生寒栗。","俯仰失从来，敛襟恣吾适。"]},{"t":"双镜楼","f":"五言古诗","c":["一镜从空出，清光透檐隙。","白白入双眸，并作琉璃国。","中有五色云，隐显镜中错。","四窗常豁然，阳燄生虚室。","古称百尺楼，高广非其匹。","高出九霄上，俯视犹蜗角。","横亘踰八荒，转足失广漠。","远睇彭蠡滨，秋水连天白。","近枕紫霄高，松竹罗其侧。","山晴天气朗，时花爱丽日。","百鸟翔且鸣，高低竟晨夕。","星月绕榱楹，寒空彻几席。","风雨至无时，轰雷震山岳。","瞬息复晴霁，万木光通泽。","时运无古今，观听有荣落。","流览一镜中，双眸自开合。"]},{"t":"耕田二首 其一","f":"五言古诗","c":["举世竞干谒，俯仰丧其真。","性岂与人殊，难忘贱且贫。","遇境辄自信，行浊而志清。","此语非圣贤，大言以徇情。","性习本同源，明昧互相倾。","理必不胜欲，观浅乃无成。","凡夫贪着事，吾师之所箴。","有初鲜克终，岂不负生平。","长揖谢世间，决志归山林。","饘粥亦可食，努力事躬耕。","少者效勤劬，晨宵予在心。","但得无馀想，山水有知音。"]},{"t":"耕田二首 其二","f":"五言古诗","c":["淹留四十年，宵旦为人谋。","此道不可传，明珠徒暗投。","悟理贵力行，空闻岂真修。","市井多佳士，所识非王侯。","追呼马队中，君子之所羞。","营营竟何为，不肯归山丘。","所食不过饱，粗衣省多求。","日出荷锄去，日入濯清流。","百虑不干怀，自春乃徂秋。","精识与奇情，终古行当休。","峄阳产孤桐，爨下获其俦。","宿雾隐高林，百里闻虎吼。","孰是圣人徒，而为吾道忧。"]},{"t":"秋夜与诸衲坐月","f":"五言古诗","c":["管弦邀月醉，醉后月还山。","何似千峰顶，年年共月閒。","微云元不碍，澄江影自澜。","光摇万木动，静极鸟声寒。","目前多所陈，意短境乃悭。","人爱秋月佳，智者独不言。","物理非有无，事会成寂喧。","夜落群动息，心閒林壑宽。","因月得其真，无月亦恒然。","万古犹若斯，人间徒厌忻。","空明山岳峙，敛目归虚玄。","亦岂在象外，吾徒当冥观。"]},{"t":"送真诠化米","f":"五言古诗","c":["庐山有山叟，弗与王侯友。","晚年居庐山，一路植榆柳。","两年柳叶长，相将荫南亩。","荫多稻苗稀，年荒岂柳咎。","风雨非不时，苗虫酷天狗。","去年工食繁，麦粥苦已久。","今岁秋无收，遑以恤其后。","有衲辞出山，所欲给众口。","众口诚待哺，志操非可苟。","元亮频叩门，礼义看授受。","饥饱信当时，平生安足负。"]},{"t":"培牡丹","f":"五言古诗","c":["名花逊牡丹，色香皆第一。","珍重花开时，灌溉先秋日。","沃土培根株，尘坌非所择。","香臭本殊途，忻厌互施设。","用厌以为忻，即臭成香洁。","物理无美恶，人心有同别。","君子道岂常，仁智分畛域。","万类同一花，芳秽待时节。","忘秽得花情，爱花因人热。","随世呼马牛，倒想何能及。","但看春明林，我心终匪石。"]},{"t":"闰中秋玩月","f":"五言古诗","c":["闰亦中秋月，胡为此较妍。","云尽当空媚，桂影无正偏。","因闰识从来，翳中体恒然。","休更怀宿昔，尔乃矜目前。","万古清光偏，明暗分后先。","暗先难为明，明后谁独怜。","且尽今夜欢，夜夜青霄寒。","顾影成阴霾，遮莫疑当时。"]},{"t":"买坟","f":"五言古诗","c":["莫买他人坟，坟地不可耕。","人骨在地下，掘地伤人心。","人心讵残忍，天性难为贫。","饥寒在目前，安知祖父亲。","孝弟随所知，名实互主宾。","所知有时昧，不如不知真。","买坟与卖坟，相安世上情。","我自不掘地，岂共仁义邻。"]},{"t":"三良","f":"五言古诗","c":["一死安足难，斯人应自观。","勋名盖宇宙，恩遇洽肺肝。","时异人云迁，慷慨多空言。","不可以理揆，理直情易捐。","君子慎当念，转瞬分岳渊。","李陵终负汉，苏武幸生还。","豫让徒自苦，荆轲易水寒。","四子皆贤豪，硁硁各自存。","衰利从中来，久暂非所存。","三良临穴时，抚膺岂偶然。","持此必死心，金石不能坚。","圣贤行终身，名谊空周旋。","此道谁与知，黄鸟哀无期。"]},{"t":"刘参军","f":"五言古诗","c":["蜉蝣与龟鹤，延促一弹指。","刘伶闭关键，穷年学周史。","不见猥无目，不闻安用耳。","神将守汝形，醉昏终不似。","心若死灰积，形如槁木曳。","耳目心形殂，虽生亦已死。","何不未死时，云霄恣高视。","饮啄犹生平，吟笑深竹里。","客至或放谭，不欲见即止。","所忧叩门难，麦粥今年苦。"]},{"t":"哭澹归","f":"五言古诗","c":["人生莫不死，既死安可伤。","形役一百年，终归无何乡。","况已六十七，讵足论短长。","所伤法运衰，死者皆贤良。","法眼在一时，岁月多荒唐。","波旬入人心，善观其向方。","狂者中以名，狷者与世忘。","忘世非佳士，徇名岂道望。","名反以利终，菽林杂兰芳。","斯人向予言，相对生悲凉。","已矣无真人，少壮犹茫茫。","掩户坐晨夕，泪血沾巾裳。"]},{"t":"挽愿海","f":"五言古诗","c":["国久无真忠，忠者多见戮。","家久无真孝，孝者先无禄。","为孝岂凶德，老病宜孤独。","秋中痛吴门，气咽不能续。","再展海云章，零泪继宵夙。","天高霜气寒，林空山木秃。","代谢理恒然，老少相往复。","委运付生平，饥食聊自足。","早不闻孝思，使汝长受福。"]},{"t":"孝子吟","f":"五言古诗","c":["我有一孝子，不幸先我死。","子死父为瘗，父死当谁理。","今年七十四，建立犹未已。","法界如转环，谁起复谁止。","努力且向前，有事如无事。","无事即坐禅，有事随时处。","处到没遮阑，两脚捎空去。","生死与涅槃，大众留不住。","违顺争目前，身后还归汝。","顺亦汝心生，违亦汝心起。","生起即为因，形影相依倚。","法空汝不空，有无成妄计。","先佛曾有言，慎莫信汝意。"]},{"t":"吾生","f":"五言古诗","c":["吾生岂不乐，人事转参差。","所愿殊未酬，腼腆纡岁时。","举世无真人，将以迟初机。","愚昧寡所见，异同为是非。","道衰绝俦辈，相对强言辞。","惧以小人心，翻成爱见悲。","久割三界因，恋恋欲何为。","先德不可负，后死安可期。","垂垂衰病年，饮泪岂自知。","绸缪苦不早，叹息贻来兹。"]},{"t":"答居士","f":"五言古诗","c":["至理便为渗，大道落蹄筌。","西来无旨意，何处有单传。","生心已非性，离人谁是天。","不立立自昧，动必伤自然。","饥餐知饥餐，倦眠为倦眠。","只此一念差，过乃踰大千。","特地自知非，金销石匪坚。","举头天外看，所见皆先贤。"]},{"t":"示禅人","f":"五言古诗","c":["闻君五十一，七月是生日。","汝徒欲称寿，请我为着笔。","为问生何来，以何为真实。","过去已过去，未来未可述。","目前者一着，明白而深密。","特地指向君，回首日又出。"]},{"t":"赠妙峰","f":"古风","c":["妙峰今年五十一，适值持船放生日。","湛子乞言作寿言，山僧清晨为捉笔。","但愿年年护此生，无生即在生中得。","君不见青莲池上草芊芊，长空雁过无踪迹。"]},{"t":"文玉居士七十一歌","f":"七言古诗","c":["天地之大德日生，圣人大宝不必位。","世间所重谁仁贤，况复降心归善逝。","法交犹忆十年前，十里香花拥法筵。","选佛君家半筹室，阶前玉树犹翩翩。","江门一别江水深，烽烟云水两浮沉。","三老重来秋再半，闻君慕道同初心。","白衣护法如护己，等视群生如一子。","大觉金仙曾有言，长寿因缘秖有此。","祝君从此更七十，存心济物长如佛。"]},{"t":"金刚说法图引","f":"七言律诗","c":["著衣持钵柳风长，洗足跏趺华雨香。","希有世尊唯自喻，如来护念为人忙。","千年古镜当空鉴，一室传灯五岭光。","黄梅夜半袈裟话，华梵同音到海幢。"]},{"t":"题普贤图","f":"七言古诗","c":["心本无生示现生，示现之中无有我。","无我我亦虚心境，诳惑世间与同事。","一切世间悉如幻，识取如幻真实现。","差别无非根本智，根本差别无有二。","文殊为倡普贤和，二妙圆成如来住。","何人以此微妙笔，绘出普贤无相身。","骑象直向华屋中，一毛头上帝珠重。"]},{"t":"解空阁制砚歌","f":"七言古诗","c":["混沌以前无黑白，未剖人文先诞石。","海岳成形天梵来，圣愚凡哲多奇迹。","陆亘一片坐卧常，镌得不得非所择。","深山大小空嶙峋，千年路滑犹荒僻。","解空老人补南天，攫取端岩不盈尺。","欲蘸毫端染太虚，一画大千青碧碧。","钟王怀褚战龙蛇，如虫御木何狼藉。","珍重云中似虎形，香水磨砻生羽翮。"]},{"t":"桃花辞","f":"古风","c":["桃花红，桃花红，年年一度二月中。","不羡汝艳如人面，亦不取汝醺醉容。","武陵溪上，流水已空。","谁管他刘伶去后，洛阳城东。","可煞是梅花初落，牡丹未开，夐夐一树，笑倚东风。"]},{"t":"庭树曲","f":"古风","c":["庭前一树落，庭前一树荣。","荣时双双不见落，落时已落不知荣。","落不知荣荣暗惊，年年忽听寒风声。","大块生物恒不平，既生落者何生荣。","胡不同入溪流清，使我独立貌长生。","一朝伐木山丁丁，千古叹息徒虚名。"]},{"t":"喜雀吟","f":"古风","c":["净成喜雀不见喜，日日噪檐贫似水。","水贫流入溪，溪流直到蠡湖止。","湖水随风吹，北风吹上滩头逢石齿，舟破货沉贾客死。","风息顺流入大江，江水深无底，多凶少吉何时已。","水富岂如贫，山中一勺青无滓。","数杯雨前香，一任喜雀噪檐，日高僧不起。"]},{"t":"乌鹊吟","f":"古风","c":["乌鹊声嘈嘈，飞上飞下不离树上巢。","树杪畏风吹，风吹犹自可，低树蛇侵无处躲。","去年逐一雏，今年吞卵巢几破。","乌鹊那，人情物理一等招因果。","勿贪沙边鱼，林间岸畔自死虫蛙随时过。","养成毛翮健且长，旷大虚空一任东冲西突何曾奈得我。"]},{"t":"种蔬","f":"五言律诗","c":["道人何所事，生计钁头边。","举世无相识，锄云幸自怜。","山花没小径，春水满荒田。","客到且休问，郊原尚未平。"]},{"t":"送袁普类还宝安","f":"五言律诗","c":["送汝且归隐，难逢无事人。","才多常悯乱，母老莫嫌贫。","安攘千秋业，田园此日春。","悠悠尘世外，犹有草茅臣。"]},{"t":"夏日雨后","f":"五言律诗","c":["木桥人初度，云树尚微茫。","持此幽閒意，如闻兰蕙香。","风轻帘欲动，荷静院生凉。","午睡梦方足，一声清磬长。"]},{"t":"黄石藏惠药","f":"五言律诗","c":["从来不厌病，以此入无生。","万境皆休歇，一心无所轻。","鸟归深树噪，月向高空明。","惟有石藏老，能羁予俗情。"]},{"t":"梁未央死难二首 其一","f":"五言律诗","c":["嗟予肠欲断，念子且何之。","学道生平笃，遣情此际迟。","声名世共仰，生死君须知。","白刃春风冷，悬崖撒手时。"]},{"t":"梁未央死难二首 其二","f":"五言律诗","c":["嗟予肠欲断，念子且何之。","遂志应无憾，修名亦是痴。","当观身世幻，莫动黍离悲。","回首云山阔，龙华为尔期。"]},{"t":"霍觉商父子四人死难二首 其一","f":"五言律诗","c":["生平多慷慨，死国在儒林。","父子情偏重，君臣义独深。","碧潭今日事，明月古人心。","俯仰堪谁语，一堂玄对森。"]},{"t":"霍觉商父子四人死难二首 其二","f":"五言律诗","c":["共明千古节，就义且从容。","生死去来际，衣冠谈笑终。","草堂云漠漠，寒夜雨溶溶。","一片情孤绝，相期入碧峰。"]},{"t":"出小持船","f":"五言律诗","c":["一住两三月，莲花空满池。","郊原戎马急，里巷故人思。","不了蒲鞋债，仍还茅舍移。","悠悠无着意，何日白云期。"]},{"t":"次韵答晋江陈文长","f":"五言律诗","c":["随处生涯足，锄云带晚霞。","窗开青滴树，人在碧笼纱。","问道看庭柏，当机指菊花。","知君非俗骨，何日唱还家。"]},{"t":"夏日即事","f":"五言律诗","c":["荒山无一事，当户数松疏。","夜短眠不足，日长饥有馀。","风声撼林谷，雨气浸庭除。","对此莫须惜，解襟空自娱。"]},{"t":"秋日写怀","f":"五言律诗","c":["秋月年年白，秋风岁岁清。","自从一心静，遂使万缘轻。","落落疏林意，萧萧寒夜情。","旷观尘世里，谁拟学无生。"]},{"t":"题东坡画竹","f":"五言律诗","c":["尘垢满天地，此君清欲狂。","浓烟生素绢，薄荫到绳床。","覆我真难待，披人似亦凉。","东坡千古意，相对共茫茫。"]},{"t":"开北径二首 其一","f":"五言律诗","c":["北园开一径，小景足幽情。","俯仰乾坤阔，优游林木平。","海连天逾白，人共月长明。","我亦逃名者，谁当混独醒。"]},{"t":"开北径二首 其二","f":"五言律诗","c":["古者知何似，吾今独杖筇。","白云常入户，青霭数当峰。","薄照明秋雁，疏林起暮钟。","不堪人事改，谁与觅高踪。"]},{"t":"偶述","f":"五言律诗","c":["秋雨满岩壑，横流似海潮。","漫漫天地外，望望水云迢。","白日知何处，晴峦不可招。","坐看人境寂，魂梦一时销。"]},{"t":"秋夜登楼二首 其一","f":"五言律诗","c":["高楼一以望，顿觉野怀赊。","月射潮头动，云流山背斜。","寒塘孤雁影，烟树万人家。","百尺应难再，凭空思未涯。"]},{"t":"秋夜登楼二首 其二","f":"五言律诗","c":["俯仰江山外，悠悠孰共看。","有怀瞻野岸，无语倚栏干。","鹤下寒空净，风高碧汉宽。","欲明今夕事，相对莫顸颟。"]},{"t":"与崔石师泛舟","f":"五言律诗","c":["与子乘桴去，何妨尽日游。","江山能友我，渔佃总方舟。","拚醉不须酒，无心亦似秋。","他年回首处，风起绿榕洲。"]},{"t":"勉诃林诸衲","f":"五言律诗","c":["寒到惊秋尽，无云天欲垂。","道情添老大，人事暗迁移。","扫叶供烹茗，担泉先灌葵。","韶光应共惜，世路此何时。"]},{"t":"出关前一夕","f":"五言律诗","c":["遂有出门意，方知破院閒。","野云常漠漠，流水自潺潺。","此夜望中月，他时梦里山。","坐寒松影怯，归雁度前湾。"]},{"t":"诃林春归二首 其一","f":"五言律诗","c":["廛居日易逝，不觉报春归。","雁影空潭尽，禅声远树微。","江山三月里，人事十旬违。","积雨留寒色，焚香但掩扉。"]},{"t":"诃林春归二首 其二","f":"五言律诗","c":["忽忆登临处，风烟足往年。","山悬千里外，春别一旬前。","岁月催华鬓，乾坤限远天。","玄心惟自鉴，去住总茫然。"]},{"t":"羊城即事","f":"五言律诗","c":["一郡旌旗满，孤城落照间。","散骑何日出，大将几时还。","近海归无渡，连云旧有关。","犹怜竹径外，徙倚独看山。"]},{"t":"侯若孩过访","f":"五言律诗","c":["忆别当残腊，重来又在秋。","多君霜雪意，重我石林游。","风雨摇山岳，池塘泛海鸥。","席帘香正煖，天地一虚舟。"]},{"t":"寄无得","f":"五言律诗","c":["道人生计拙，缓步出山门。","日日看高岭，行行过别村。","无人知此意，有口不堪论。","远讯熊禅者，年来或未谖。"]},{"t":"苦雨","f":"五言律诗","c":["一雨经旬日，闭门谁与同。","人从烟暝出，心付水云空。","历历江山外，濛濛天地中。","放歌殊未已，学得古人穷。"]},{"t":"喜晴","f":"五言律诗","c":["清晨一开户，澄霁如平时。","不减青山色，多添绿树姿。","白云归洞急，红日上梢迟。","策杖园林外，鹧鸪啼向谁。"]},{"t":"出小持船作二首 其一","f":"五言律诗","c":["严城不易出，独许看云人。","附郭馀孤木，空斋无四邻。","水亭深夜月，烟树旧时春。","对此清幽趣，谁怜梦里身。"]},{"t":"出小持船作二首 其二","f":"五言律诗","c":["帘疏月到簟，高卧独依违。","黄鸟声何急，青山梦亦非。","一庵烟水阔，千里雾云微。","无限伤心处，孤城人影稀。"]},{"t":"闻亦非隐天目","f":"五言律诗","c":["天目中峰变，晴岚万壑阴。","马嘶荒草断，人宿暮云深。","何日乘潮上，别峰清欲临。","遥知携手处，应尽故园心。"]},{"t":"登楼","f":"五言律诗","c":["濛濛烟雾里，峰岫隐如无。","地近市廛旧，人看世界殊。","白云迷晓日，青燕引飞雏。","一上楼头望，临风涕欲俱。"]},{"t":"赠范华宇","f":"五言律诗","c":["将军不尚武，矢志在安民。","万户伤心处，孤城此日春。","高山曾有梦，流水付何人。","笑指溪桥近，相看忆旧因。"]},{"t":"诃林忆旧山二首 其一","f":"五言律诗","c":["不见雷峰顶，心知海寺东。","闻钟疑隔岸，对雨忆长松。","风鹤从来旧，烟霞此际隆。","百年多病日，归思正无穷。"]},{"t":"诃林忆旧山二首 其二","f":"五言律诗","c":["情深山水日，岂为觅桃源。","倦鸟藏深树，惊鱼沉巨川。","拂波杨柳月，依岸竹林烟。","一自不知乐，浮生空惘然。"]},{"t":"与梁同庵王说作夜坐风幡堂","f":"五言律诗","c":["中夏坐宜夜，夜深鸟不啼。","相看今古尽，无语是非齐。","殿迥薰风细，楼高云气低。","等閒过一夕，险韵漫分题。"]},{"t":"一啸","f":"五言律诗","c":["一啸江天暮，长吟风物新。","无家终作客，有钵未曾贫。","不识云山路，空知林木亲。","平生多意气，强半为人瞋。"]},{"t":"送陈康叔复徙仁化","f":"五言律诗","c":["惜别非归路，胡为千里行。","客心徒自苦，去住此时轻。","暴雨中席至，西风向晚生。","前途望秋月，莫动故乡情。"]},{"t":"示梁同庵","f":"五言律诗","c":["懒僧居破寺，岂是世间情。","幸托随缘趣，相将寄此生。","爱閒嗟往事，畏俗厌时名。","念汝年差近，堪为林下盟。"]},{"t":"与王说作","f":"五言律诗","c":["君但先为复，年来欲住山。","多因酬世拙，以此乐吾閒。","黄独岂真美，青松未可删。","尚能不贱目，云水去留间。"]},{"t":"己丑冬赴古冈大云请因示诸衲","f":"五言律诗","c":["万里寒烟直，虚空起大云。","长廊风叶捲，古殿月华分。","历历应非物，忉忉何所云。","一堂僧与俗，谁见复谁闻。"]},{"t":"古冈除夕","f":"五言律诗","c":["忽忽过今夕，迢迢遂去年。","空居人世外，犹共岁时迁。","野火横星汉，寒鸦落雾烟。","江城除夜禁，春色自林泉。"]},{"t":"与诸衲游知园","f":"五言律诗","c":["名园誇独胜，想见古人心。","渍水成寒渚，为山控碧岑。","平台歌舞歇，荒径草莱深。","相对同他日，悠悠自古今。"]},{"t":"游圭峰","f":"五言律诗","c":["人日寻幽壑，圭峰旧有名。","徐行怜日暖，小坐爱风清。","败叶残碑覆，枯椿野鸟鸣。","青山空垒垒，无限古今情。"]},{"t":"古冈闻警","f":"五言律诗","c":["所见非今日，惊闻又一时。","天心不厌乱，人事欲何为。","薄海旌旗蔽，孤城画角悲。","十年尘世外，归梦亦迟迟。"]},{"t":"将还雷峰留别古冈诸子","f":"五言律诗","c":["一自闻风鹤，深惭遁者讥。","寻生人有路，策杖我何归。","旧筑青山稳，征帆野岸微。","江城重回首，春草绿依依。"]},{"t":"诸子送予江门口占慰别","f":"五言律诗","c":["岸柳难为别，江风欲送行。","迢迢村路迥，漠漠野烟横。","挥涕怜儿女，牵衣愧父兄。","不看分手意，谁识住时情。"]},{"t":"过蓝田访岑梵则二首 其一","f":"五言律诗","c":["何期当此日，复见老成人。","未乱先归隐，为园及早春。","沙田将播种，茅屋绝无邻。","借问生涯事，年来欲慕真。"]},{"t":"过蓝田访岑梵则二首 其二","f":"五言律诗","c":["惜别自今日，交游忆十年。","雁归芦渚冷，人到杏花前。","往事不堪论，遐心总入玄。","悠悠江上水，遥望白云边。"]},{"t":"还雷峰","f":"五言律诗","c":["夜夜还山梦，梦中山宛然。","青松犹夹岸，绿竹已参天。","却恨忙年月，深怜旧草玄。","看看秋又尽，归雁入寒烟。"]},{"t":"还雷峰寄王说作","f":"五言律诗","c":["归卧雷峰下，闻君去古冈。","同时见秋雁，一棹入寒塘。","篱菊何年醉，溪云看独长。","人生几回别，老大畏行藏。"]},{"t":"蕉林看岩关主病","f":"五言律诗","c":["昔年曾病肺，以此独怜人。","赖有诗能懒，兼之道欲贫。","轻风衣外冷，微月柳中新。","疏拙林泉下，谁知閒处真。"]},{"t":"送商丘伯侯若孩","f":"五言律诗","c":["历乱沅湘道，迢遥潮汐西。","身名吾辈重，离别世人迷。","寂寂夜猿啸，萧萧斑马嘶。","安危付君国，千里绿杨堤。"]},{"t":"喜老父薙发","f":"五言律诗","c":["七十方离俗，皤然成老僧。","人间犹父子，世外得亲朋。","底事商尘劫，清宵共佛灯。","隐峰曾有妹，先此乐仍仍。"]},{"t":"秋雨","f":"五言律诗","c":["积雨沉秋汉，寒云没太清。","长林迷去路，栖鸟暗闻声。","天地何曾别，江山此一更。","坐观烟暝阔，徒有古今情。"]},{"t":"中秋冯紫光过雷峰二首 其一","f":"五言律诗","c":["年光惊易过，忽忽又中秋。","不见故人久，相携山径幽。","白云横岭路，黄叶断溪流。","借问生涯事，百年谁短修。"]},{"t":"中秋冯紫光过雷峰二首 其二","f":"五言律诗","c":["客心差不俗，僧况亦殊清。","共坐长林下，难忘故国情。","水流寒雁影，林噪暮鸦声。","郑重怜兹日，蒹葭白露盈。"]},{"t":"梁同庵书辞北上赋此寄别兼讯祖心弟","f":"五言律诗","c":["因乱频相失，惊闻复远行。","长安从旧路，出处此时情。","万里山川险，三春风雪清。","故人犹可晤，期以慰生平。"]},{"t":"冬日","f":"五言律诗","c":["厌闹思投老，甘心堕小乘。","时危村寺稳，道替竹林增。","适意惟高枕，清谈共数僧。","海门红日下，危坐剔孤灯。"]},{"t":"冬夜","f":"五言律诗","c":["独坐高峰上，双眸寒夜中。","乾坤容我拙，今古与谁同。","入望青山旧，当怀明月空。","何人知此意，冷冷忆卢公。"]},{"t":"元旦","f":"五言律诗","c":["元日晴明好，林泉天地宽。","竞看新草木，犹忆旧衣冠。","野鸟啼春昼，山僧耐晓寒。","莫愁时序改，不尽碧云团。"]},{"t":"落齿吟","f":"五言律诗","c":["食笋忽落齿，方知非壮年。","人生愁渐老，吾道乐其天。","岁月忙中过，沧桑梦里迁。","一杯清茗罢，吟啸自便便。"]},{"t":"新月","f":"五言律诗","c":["桥头初月上，相见隔年新。","影落千江冷，光生万户春。","海门潮淼淼，山路石磷磷。","何必清辉满，娟娟早可人。"]},{"t":"送王说作归龙江","f":"五言律诗","c":["别去当正月，相期二月还。","三旬风雨夜，百里海云间。","吾道难为俗，君心亦自閒。","梨花凉月上，人影待春山。"]},{"t":"诸子夜集方丈","f":"五言律诗","c":["相对今何事，相期尽一生。","夜寒茶椀重，人静烛花明。","密坐偏多意，微言岂为名。","山中与山外，谁会此时情。"]},{"t":"喜诃衍还山","f":"五言律诗","c":["入山将午食，风暖日光迟。","乍别惊予瘦，归来爱汝痴。","渐深杨柳色，应长薜萝思。","观世同春梦，閒心欲付谁。"]},{"t":"宿诃林","f":"五言律诗","c":["不到诃林久，悠然钟磬音。","战争成佛地，云树几人心。","画角孤城暮，春风古殿深。","徘徊今夜梦，依旧在长林。"]},{"t":"病四首 其一","f":"五言律诗","c":["始信我能病，闭门惟一閒。","鸟声喧瘦日，人影谢空山。","茶为伤脾少，诗因摄虑艰。","年来方有愿，独宿寒云间。"]},{"t":"病四首 其二","f":"五言律诗","c":["不耐秋山色，扶筇一启扉。","畏风因步缓，倚竹觉身微。","衰柳拂茅屋，孤鸿立钓矶。","夕阳村犬吠，林外有僧归。"]},{"t":"病四首 其三","f":"五言律诗","c":["久矣无人事，病来心更休。","只嫌筋力少，难上碧峰头。","野火烧何处，海风吹暮秋。","寒房掩深径，落叶空飕飕。"]},{"t":"病四首 其四","f":"五言律诗","c":["寒月复相见，霜天此较新。","下庭双屦重，倚槛数峰真。","瘴海高秋迥，清溪白石粼。","一回伤老病，万事但随人。"]},{"t":"梦达此","f":"五言律诗","c":["独行傍山水，病中知汝情。","两年归未得，昨夜梦分明。","兵火经州县，遭逢数姓名。","帘前悲喜处，山犬吠秋声。"]},{"t":"挽陈慧业道人","f":"五言律诗","c":["生死泥洹等，多君一去来。","因缘如及尽，迷梦未曾乖。","白鹭烟光净，金牛月影回。","精魂他日旧，回首话生台。"]},{"t":"九日扫老父塔","f":"五言律诗","c":["尚有孤坟在，空闻松柏哀。","青山怜我瘦，黄菊向人开。","日落大江阔，风高独雁来。","明年记此日，珍重几登台。"]},{"t":"送思圆","f":"五言律诗","c":["世外应无恨，忘情亦大难。","话空千绪失，梦剧五更寒。","云水何人趣，溪山后日看。","送君从此去，相忆路漫漫。"]},{"t":"赠姚梦峡","f":"五言律诗","c":["世乱方知道，遐心滞草庐。","欲明今日事，莫误古人书。","独坐疏钟外，相携寒月初。","身名殊可已，鉴此百年馀。"]},{"t":"送商丘伯侯若孩扶柩归中州","f":"五言律诗","c":["子有君与母，死别复生离。","寒月空相照，白云殊未知。","驱车出庾岭，归里正秋期。","望望商丘路，徘徊系所思。"]},{"t":"因侯若孩寄匡山蠡云","f":"五言律诗","c":["十载匡山梦，因君寄短吟。","为停彭蠡楫，一讯虎溪音。","塔影千岩出，松关积雪深。","寒灰犹可拨，欲避俗人寻。"]},{"t":"送人入匡山","f":"五言律诗","c":["我有匡庐约，君先问落星。","十年松树火，此日石头形。","梦入溪声细，桥分山色青。","为言林下叟，出岁返蓬扃。"]},{"t":"姚梦峡生日戏赠","f":"五言律诗","c":["三十四年前，当知亦偶然。","胡为于此日，更欲贺初年。","雁过长空澹，江摇寒日圆。","一生魂梦里，荣落在谁边。"]},{"t":"十一月三十夜","f":"五言律诗","c":["明朝又腊月，因病觉时过。","祖意逢人少，青山去日多。","亮公曾有约，瓒老定如何。","早岁深云志，而今鬓渐皤。"]},{"t":"元旦怀止言澹归诸衲","f":"五言律诗","c":["念子远行役，况复上元时。","灯火何方照，川原此夕思。","柳风吹客袂，春月映山池。","夜永寒云重，应怜江雪迟。"]},{"t":"孤松和诸子作因忆归宗复生松","f":"五言律诗","c":["寒影敛幽壑，涛声响万山。","一株非我意，孤韵共人閒。","干入春云里，枝横夜月间。","鹤巢应未改，犹待老僧还。"]},{"t":"偶叹","f":"五言律诗","c":["近海山犹浅，平林春尚寒。","一从淇水北，五见梅花残。","自好终无术，因人亦复难。","旧居匡岳麓，时向望中欢。"]},{"t":"闻转一讣","f":"五言律诗","c":["肺病知难待，终伤朝露情。","形骸一日重，海岳百年轻。","月落梅花夜，云寒竹叶坪。","横梁与孤屿，徒有昔人名。"]},{"t":"闻采石讣","f":"五言律诗","c":["花发当朝露，莺啼怯暮春。","谁怜老病日，恸哭少年人。","薄虑频经乱，移忧岂厌贫。","虽馀诸梵侣，亦复渐相沦。"]},{"t":"闻范华宇治圃却寄","f":"五言律诗","c":["于世复何事，随时学种园。","一身馀草泽，八口待辕门。","城柳移畦影，春禽啄月痕。","相思聊以寄，寒暖不堪论。"]},{"t":"送山品台设领诸衲上华首","f":"五言律诗","c":["三老潮头暗，百花春后明。","莫频回首处，遥慰故山情。","离乱田庄旧，辛勤手足轻。","吾门多乐事，不是畏时名。"]},{"t":"萤火","f":"五言律诗","c":["尚尔微明志，遐心共隐沦。","昏霾应自见，白日畏投人。","春草独行处，禅房閒坐身。","高低怜羽短，曾不却迷津。"]},{"t":"分粥与饥者","f":"五言律诗","c":["戎马嗟何已，秋田苦未登。","井闾无少壮，贫病绝亲朋。","笑我生方拙，怜人强不能。","一瓢分众粥，惭愧远投僧。"]},{"t":"离欲为众乞食","f":"五言律诗","c":["山浅松花少，枝危鹤影高。","图将六月息，不爱一人劳。","俯仰随双屦，风尘有敝袍。","秋风初入户，迟尔返蓬蒿。"]},{"t":"食荔子怀止言澹归","f":"五言律诗","c":["去年同擘荔，坐月板桥新。","复见手中物，顿思江上人。","紫霄朝暮石，京口去留津。","一纸南安信，浮沉十二旬。"]},{"t":"得吼万琼州信","f":"五言律诗","c":["海外行人少，艰难远寄书。","兵荒千里外，存殁九年馀。","目尽无飞雁，天长只敝庐。","徘徊山日下，一倍惜居诸。"]},{"t":"酬王园长兄弟","f":"五言律诗","c":["羡尔难兄弟，烟云共此遐。","心閒馀岁月，世乱苦桑麻。","野寺门前路，石楼峰上霞。","因君思旧隐，山色十年赊。"]},{"t":"因乱奉母蕉林阿字频为省视感而赋诗","f":"五言律诗","c":["乱离惭我母，辛苦赖人将。","影息秋畦近，钟鸣蕉叶长。","山中一食暇，林外几家忙。","因数振嚣俗，超然及上皇。"]},{"t":"溪桥古木为雨所仆戏示阿字","f":"五言律诗","c":["四时停热客，一雨叹离群。","对月全无影，临风那复闻。","根看仍屈曲，叶积故纷纭。","物理此中得，荣枯岂足云。"]},{"t":"挽英目青","f":"五言律诗","c":["山上曾来往，悄然生道心。","去秋犹有约，此日竟难寻。","草色青还白，溪流浅复深。","伊人不可见，残月想微吟。"]},{"t":"悼目青却寄社中","f":"五言律诗","c":["忽闻高士讣，未免一长嗟。","白社人难再，青山日易斜。","此生如可托，何事欲离家。","飒飒秋风起，应怜两鬓华。"]},{"t":"将出岭留别雷峰诸子","f":"五言律诗","c":["一别榕溪寺，萧然独杖藜。","六年林磬渺，千里暮云低。","山水何曾异，乡关各自迷。","夜帆忘所向，恍惚隔溪西。"]},{"t":"留别华首诸子","f":"五言律诗","c":["避乱寻深处，遥空一别难。","昔时相勉句，今日尽须看。","便舫知何去，投人强作欢。","北风吹暮雪，应念石门寒。"]},{"t":"留别张梦回","f":"五言律诗","c":["惜别张居士，慇勤寄一言。","干戈犹未已，瓢笠尚能存。","山浅无黄独，林深有白猿。","古今看欲尽，相待惟蓬门。"]},{"t":"留示吼万吼万期以九月至雷峰","f":"五言律诗","c":["君将从海发，我复向山归。","去住一何定，佳期多所违。","秋波风色急，寒月岭头稀。","若到雷峰夕，怀人望翠微。"]},{"t":"台阁滩怀时尽","f":"五言律诗","c":["旅病方思汝，衷怀未可论。","所施惭所报，知己重酬恩。","滩浅石流疾，秋高霜鬓繁。","到山黄叶尽，寒夜感谁存。"]},{"t":"泊韶石四更见月","f":"五言律诗","c":["山月出残夜，清波寒照人。","推篷惟独坐，高咏孰为邻。","塔影看何似，江声闻最亲。","村鸡催曙色，烟棹又前津。"]},{"t":"病留凌江寺","f":"五言律诗","c":["避地思投老，征途复苦辛。","古城寒戍火，多病老僧身。","寂寂凌江寺，萧萧枫叶津。","昨来云水客，云是庐山人。"]},{"t":"旅病忆梁同庵","f":"五言律诗","c":["归山愁旅病，因病益怀人。","寒日残流乱，秋风永夜真。","此中无可语，他外只閒身。","十日前来梦，庐山见欲亲。"]},{"t":"韶阳道中病起适无侍者复病","f":"五言律诗","c":["我病差能饭，君行复被风。","心悬千里切，途哭两人穷。","忍冻推残絮，频兴候曙钟。","青山岂易得，珍重百年中。"]},{"t":"度大庾岭","f":"五言律诗","c":["爱雪辞乡国，秋风送马蹄。","庾关终古峙，猿狖至今啼。","五老人初望，三山日渐西。","徘徊下原隰，叠叠白云迷。"]},{"t":"道中被诘","f":"五言律诗","c":["问我何处去，拟归庐山岑。","途艰多病衲，虑淡无机心。","一钵陈年饭，数篇行路吟。","生平颇自信，何事苦稽寻。"]},{"t":"道中忆止言澹归","f":"五言律诗","c":["匡山计日至，京口望人来。","几时同到岸，扶我一登台。","群雁惊风起，孤舟乘月开。","章江寒色动，无那暮砧哀。"]},{"t":"过十八滩二首 其一","f":"五言律诗","c":["世事当今日，时时十八滩。","激流飘作雨，危石望成峦。","牵缆烟波渺，随人出没宽。","闻钟知近寺，翘首倚船栏。"]},{"t":"过十八滩二首 其二","f":"五言律诗","c":["漩澓无行径，波涛不忍看。","舟穿叠石捷，篙放急流难。","沙鸟立何意，渔人坐自安。","诗成聊独咏，不觉夕阳残。"]},{"t":"阻风宿险处","f":"五言律诗","c":["旅泊不知处，深村似有人。","波涛殊未已，舟子益相亲。","乾叶弄寒月，凄风吹夜燐。","无心造物妒，辛苦隐山身。"]},{"t":"晓过螺川","f":"五言律诗","c":["螺川寒日上，依旧照金牛。","烟水流残磬，江风吹暮秋。","战争虚岁月，存殁几交游。","都是归山事，人间易白头。"]},{"t":"舟中口号","f":"五言律诗","c":["湾湾江上水，直直渡头烟。","烟散乌啼岸，水寒渔聚船。","已过残邑里，未到好山川。","欲慕东林远，高眠槐柳边。"]},{"t":"峡江望匡山","f":"五言律诗","c":["停棹望匡岳，几非人世间。","两月江中水，十年湖上山。","风波行欲尽，岩壑终当还。","沙鸥与松鹤，见我何时閒。"]},{"t":"吴城望匡山","f":"五言律诗","c":["十年归梦积，一望白云乡。","山近江流缓，天空霜夜长。","明朝彭蠡水，向夕古松堂。","老大深为计，风波不可忘。"]},{"t":"到归宗怅止言澹归未至","f":"五言律诗","c":["匡山不易到，之子滞江城。","更忆临岐话，难为旷别情。","衲衣千缕薄，楖栗万山轻。","多是少年事，风尘愧老成。"]},{"t":"到匡两月叠闻梁同庵崔石师讣音","f":"五言律诗","c":["宿约成虚梦，初闻复自疑。","益伤离别易，难免死生悲。","夏木蝉声急，朝钟日影迟。","暮年惟有隐，莫遣世人知。"]},{"t":"顿修三决之镇江寄候月鹭兼促止言澹归诸子回山","f":"五言律诗","c":["闻君在京口，我已到匡庐。","信息凭诸衲，寒温懒作书。","风烟平溆浦，人物乱樵渔。","空谷待归客，白云横太虚。"]},{"t":"寄止言澹归","f":"五言律诗","c":["有约今秋返，相携五老前。","知尔南中苦，怜予海外偏。","溪声僧梦稳，江色客心悬。","且归就禅寂，休计买山钱。"]},{"t":"与须识夜话","f":"五言律诗","c":["是非非我计，今古皆空名。","肝胆尚须惜，胸怀岂易明。","人心离复合，世事败还成。","何似寒溪水，朝朝霜气清。"]},{"t":"同善邻须识游玉帘泉","f":"五言律诗","c":["归山不出户，初过玉帘泉。","万壑危桥隐，一峰寒瀑悬。","何人开石径，引我入云烟。","最爱金轮近，閒携三两禅。"]},{"t":"促诸禅还山而渐侍者独返且有期予下山之约怪而示之","f":"五言律诗","c":["人间不可住，决意向栖贤。","乞食从桥外，编茅傍水边。","一生丘壑性，半世友生缘。","怪尔还山后，相期话未圆。"]},{"t":"对雪示诸子","f":"五言律诗","c":["万里溪无色，千峰影到栏。","莫将银世界，空作月明看。","开眼皆怜白，何人不畏寒。","群公知此意，无复悔衣单。"]},{"t":"初住栖贤口占","f":"五言律诗","c":["为爱匡庐僻，寻幽到峡桥。","山围松树老，泉逐夜钟飘。","午食蒸藜暖，朝锄乞种遥。","茅居犹未缚，辛苦木铃摇。"]},{"t":"病二首 其一","f":"五言律诗","c":["此身原可厌，况复病相因。","出入难如意，辛勤徒累人。","形从衣里怯，山向窗中新。","情境何曾定，低头祇自亲。"]},{"t":"病二首 其二","f":"五言律诗","c":["万缘教散去，一衲且相依。","身共水云淡，心随钟磬微。","未须分彼此，无复计从违。","语默二俱丧，人疑鲁祖机。"]},{"t":"高泉感赋","f":"五言律诗","c":["意重难为继，恩深每易谖。","但知无限苦，只是不能言。","放辱非吾事，沉沦有母存。","一春风雨恶，愁倚杏花村。"]},{"t":"栖贤山居十首 其一","f":"五言律诗","c":["爱友寻山住，山深人未归。","不知秋色暮，空见雁南飞。","树密溪云重，峰高霜月微。","夜来松火怯，独自理寒衣。"]},{"t":"栖贤山居十首 其二","f":"五言律诗","c":["门前看五老，石上待三更。","望月不知处，沿溪每独行。","云开见雁影，泉远闻人声。","莫讶无相顾，高情感易生。"]},{"t":"栖贤山居十首 其三","f":"五言律诗","c":["潦倒一枝筇，逍遥十里松。","偶逢犊鼻叟，同听石溪钟。","骤雨不出谷，晴云隐乱峰。","忽然残照起，犹见金芙蓉。"]},{"t":"栖贤山居十首 其四","f":"五言律诗","c":["自笑吾生足，支藤上紫霄。","松门山日近，野火石云烧。","老母留芋供，邻僧隔水招。","一声樵笛响，催我下峰腰。"]},{"t":"栖贤山居十首 其五","f":"五言律诗","c":["老病心逾澹，饥寒韵更偏。","独怜山月外，无计秋风前。","拾栗煨牛火，驱茅下麦田。","明朝重九日，容易度残年。"]},{"t":"栖贤山居十首 其六","f":"五言律诗","c":["客到无留处，情乖懒见人。","床头多病衲，殿角一閒身。","夜色秋旻净，泉声晓梦真。","昨闻江上信，又阻白门津。"]},{"t":"栖贤山居十首 其七","f":"五言律诗","c":["我自立溪上，水流何太忙。","年年松树绿，日日峡桥长。","林月窥岩户，山风压草堂。","几人相对暇，熟炙橘皮汤。"]},{"t":"栖贤山居十首 其八","f":"五言律诗","c":["偶来枫树下，孤影息秋阴。","涧浅摇清濑，风轻爽素襟。","行人归竹远，散犊入林深。","何处不相似，时时压此心。"]},{"t":"栖贤山居十首 其九","f":"五言律诗","c":["病骨怜秋夜，夜长不可眠。","久疏芦菔味，惭愧白云禅。","开户望霜月，随身过野田。","晴空山势耸，一雁入寒烟。"]},{"t":"栖贤山居十首 其十","f":"五言律诗","c":["山中常作梦，梦里不知山。","双屦随人去，千门得食还。","夜泉寒竹簟，秋月白柴关。","同道如相忆，归来共学顽。"]},{"t":"诸衲侍长庆老人扫博山塔诗以勉之二首 其一","f":"五言律诗","c":["乱山残雪后，病骨尚能支。","乃祖思先泽，而师爱汝痴。","春寒青黛草，烟煖白云芝。","此道惟高隐，毋忘金井池。"]},{"t":"诸衲侍长庆老人扫博山塔诗以勉之二首 其二","f":"五言律诗","c":["道衰知自贵，后死倍应难。","微尚因人僻，能言为汝欢。","隐甘三亩宅，贫忆半旬餐。","未可辜先觉，层岩只耐寒。"]},{"t":"送长庆老人先入岭南","f":"五言律诗","c":["不敢更言别，师行随后归。","幢幡迁柳岸，童行返柴扉。","云覆庾公岭，香迎荔子矶。","到时应夏尽，秋气袭人衣。"]},{"t":"寓绍隆","f":"五言律诗","c":["偕隐寻深处，无缘遂半生。","病同松鹤瘦，贫共雪山清。","敛目常终日，横眠每四更。","不知连夜雨，空有水流声。"]},{"t":"解即觉寺事欲处以侍寮栖贤人至始知其行乞江北感而怀之作诗四首 其一","f":"五言律诗","c":["罢汝栖贤守，归余侍者寮。","遽闻北地去，竟负南山招。","积绪千言少，离忧一梦遥。","更怜去秋事，零泪纸窗飘。"]},{"t":"解即觉寺事欲处以侍寮栖贤人至始知其行乞江北感而怀之作诗四首 其二","f":"五言律诗","c":["汝志堪谁副，予心独汝知。","爱人徒自苦，遇事但成痴。","不可为啼笑，宁当问信疑。","归程须早计，莫畏晚风吹。"]},{"t":"解即觉寺事欲处以侍寮栖贤人至始知其行乞江北感而怀之作诗四首 其三","f":"五言律诗","c":["近有调心法，随缘一味憨。","肝肠惟自笑，面目向人惭。","夏雨将秋气，朝云起暮庵。","斯文还后死，荣落不成谈。"]},{"t":"解即觉寺事欲处以侍寮栖贤人至始知其行乞江北感而怀之作诗四首 其四","f":"五言律诗","c":["世人心似面，岂敢爱长生。","苦乐一身尽，悲欢百岁成。","澄潭难见底，孤鹤不堪鸣。","以此怀渔父，乘槎何处轻。"]},{"t":"送渐侍者","f":"五言律诗","c":["难为慈母道，养子自应知。","信伏丛疑日，瞋多在喜时。","去惊秋陇早，归讶雪堂迟。","风雨百年暂，寒山影未移。"]},{"t":"自慰","f":"五言律诗","c":["不到伤心处，谁当便尔休。","嬴来方寸暇，放去百千愁。","鹤颈终难短，凫胫未易修。","愿从今日往，高举白云头。"]},{"t":"丙申冬日来机奉母南归","f":"五言律诗","c":["同生惟有汝，远俗得予心。","奉母三千里，侨居最上岑。","随缘归岭表，重别立庭阴。","此去应无憾，庐山面目深。"]},{"t":"因老母南还寄酬王说作","f":"五言律诗","c":["佳诗劳远锡，又是一年馀。","无意为疏节，行人落报书。","故园应不改，深谷已成居。","幸自归慈氏，知君待敝庐。"]},{"t":"闻雁怀阿字","f":"五言律诗","c":["塞雁几时发，羁人来未曾。","归期看已过，计日尚相应。","年迈悲穷子，薪传愧五灯。","举头唯见月，何以慰山僧。"]},{"t":"偶成","f":"五言律诗","c":["但见寒暄易，不知何所为。","海潮两度至，涧瀑四时垂。","独立看云变，閒行任路岐。","吾衰矜道贵，顿起远人思。"]},{"t":"岁暮示诸子","f":"五言律诗","c":["岁暮归人少，年高去日多。","时违成荏苒，缘在莫蹉跎。","此道非难易，论功费琢磨。","法庭伤晚近，相对意婆和。"]},{"t":"悼无方二首 其一","f":"五言律诗","c":["归山将一岁，哭子畏心伤。","因悼袁高老，重添泪数行。","死生真电火，来去怯冰汤。","濒海无人处，春蛙聒夜塘。"]},{"t":"悼无方二首 其二","f":"五言律诗","c":["一上金仙殿，常思作殿人。","香台频咒愿，愿汝记前身。","海鸟千波影，山花隔岁春。","论因无苦系，当不重迷津。"]},{"t":"闻阿字还栖贤有怀","f":"五言律诗","c":["豫章游客至，云已返庐山。","沙漠方辞苦，云林知就閒。","玉渊新瀑水，石峡旧松关。","有兴终难已，何时到此间。"]},{"t":"旋庵四十七初度","f":"五言律诗","c":["汝年四十七，今日是生辰。","自托应无地，因人亦厌贫。","一山松柏密，百口稻粱辛。","古道知难和，同谁与认真。"]},{"t":"祝本师空老人六十初度二首 其一","f":"五言律诗","c":["薰风动寰海，慈日满高林。","道在人天重，机停岁月深。","千年松鹤骨，万壑水云心。","赖有群生愿，罗浮花气森。"]},{"t":"祝本师空老人六十初度二首 其二","f":"五言律诗","c":["未遂西山志，难忘尘刹恩。","大悲劳父母，得力愧儿孙。","庚子春风正，珊瑚海日温。","愿同龙象祝，岁岁法庭尊。"]},{"t":"闻云南报因酬汪居士是日海幢老人六十初度澹归侍坐","f":"五言律诗","c":["十载汪居士，相看各皓然。","见闻成异代，悲喜但随缘。","幸有吾师在，还生子弟怜。","入河归寿海，吾道至今传。"]},{"t":"辛丑闻雁","f":"五言律诗","c":["塞雁何时至，今秋不欲闻。","天高江水渺，地阔岭云分。","澹影寒塘静，疏林落叶纷。","一声随泪下，缭乱不成云。"]},{"t":"怀石鉴姜山","f":"五言律诗","c":["发棹已一月，行程计二千。","螺川接风日，匡埠望林泉。","幽谷危楼隐，深溪古木悬。","三杯招隐下，怀我石梁边。"]},{"t":"怀足两","f":"五言律诗","c":["带雨请经去，扬帆不问程。","愿归三峡寺，知返九江城。","霜叶留山色，风林隐涧声。","冷情宜绝壑，吟咏寄生平。"]},{"t":"遣云中视睹者灵","f":"五言律诗","c":["一茗将灵几，遥空愧老憨。","春风寒古殿，蜡炬暗新龛。","已尽生前句，难为身后谈。","大云烟雨旧，山鸟自諵諵。"]},{"t":"送祖印之庐山","f":"五言律诗","c":["匡山不可到，到者即宜家。","我昔曾将母，君今欲学畬。","望湖千树里，入涧一峰斜。","深谷喜人至，烹泉话晚霞。"]},{"t":"悼铁机二首 其一","f":"五言律诗","c":["年高见少亡，事苦心弥伤。","人固无长在，子尤未易忘。","森森云树密，濯濯海天长。","试问身前后，悲歌时欲狂。"]},{"t":"悼铁机二首 其二","f":"五言律诗","c":["诚求未易达，谁度他人心。","父母忧从昔，乾坤惨自今。","晨参疑在列，夕步似微吟。","此恨终予世，山高共海深。"]},{"t":"寿张梦回五十一初度","f":"五言律诗","c":["老叟归山后，梅花作蕊时。","闻君过学易，愧我未吟诗。","子大家声播，名逃身累遗。","十年岩壑梦，云水正相期。"]},{"t":"丹霞山居十二首 其一","f":"五言律诗","c":["忆住庐峰寺，因人每著忙。","十年情已淡，千指计偏长。","竹影移新月，松声到夜床。","閒心犹有此，吟咏自相将。"]},{"t":"丹霞山居十二首 其二","f":"五言律诗","c":["日落千峰失，蝉声远树微。","月光先见水，山气静侵衣。","绝顶重泉下，遥空一鹤飞。","此间谁不到，扶策独行归。"]},{"t":"丹霞山居十二首 其三","f":"五言律诗","c":["久住如初到，春山雨过时。","重云笼瘦石，枯树吐新枝。","水满河梁没，虫藏野鸟饥。","开门观日上，来往百情移。"]},{"t":"丹霞山居十二首 其四","f":"五言律诗","c":["敛想成虚咎，抬眸见佛灯。","钟声随叶落，日色照江澄。","牧竖歌方出，林僧归未曾。","绕坛方一匝，足力减乌藤。"]},{"t":"丹霞山居十二首 其五","f":"五言律诗","c":["启户竟何之，行行空自知。","三休林下径，独照岛边池。","日落云根透，风摇竹影移。","都因心想憩，嬴得目前机。"]},{"t":"丹霞山居十二首 其六","f":"五言律诗","c":["乞食叩门出，携锄候雨晴。","啼林山鸟悦，过竹晓风清。","入涧知云重，分畦到月生。","生涯予自足，辛苦一身轻。"]},{"t":"丹霞山居十二首 其七","f":"五言律诗","c":["万事不须计，千差只目前。","无人长自默，有月不成眠。","山峻星辰近，溪连草木鲜。","看云殊未已，回望一灯悬。"]},{"t":"丹霞山居十二首 其八","f":"五言律诗","c":["连年频舌病，今夏喜身强。","六十又过二，山林多夕阳。","雨来云脚白，泉落夜风长。","老眼难成寐，晓闻松柏香。"]},{"t":"丹霞山居十二首 其九","f":"五言律诗","c":["生长蓬蒿性，居山不怕穷。","柴门开向日，石磴步乘风。","望远高为室，谋生蚤种桐。","心知明月外，迢递泬寥东。"]},{"t":"丹霞山居十二首 其十","f":"五言律诗","c":["老去住山好，山深逸事兼。","懒眠青竹簟，横睇白云檐。","茶气胜春酿，香烟透夜帘。","幽怀成独往，微月上松尖。"]},{"t":"丹霞山居十二首 其十一","f":"五言律诗","c":["频年无俗梦，始觉住山深。","月落猿啼雾，烟销鸟在林。","半开青竹牖，一畅白云吟。","目送江帆远，焉知世上心。"]},{"t":"丹霞山居十二首 其十二","f":"五言律诗","c":["开门见白鹤，独立门前松。","敛翮能无忆，凝眸虚所从。","夜泉添过雨，新月起高峰。","摇曳复何处，幽寻信短筇。"]},{"t":"送雪木毬侍者出主会龙","f":"五言律诗","c":["何曾两辜负，十载菔芦禅。","担荷良非易，撑持聊试先。","智眼澄湘水，悲心混市廛。","眉须应自惜，遮莫怪天然。"]},{"t":"赠姜山","f":"五言律诗","c":["有衲学无为，千峰随杖藜。","负薪时见苦，种药竟亡疲。","爱友心常拙，吟诗月每移。","肝肠从自许，不愿世人知。"]},{"t":"赠角子","f":"五言律诗","c":["閒窗爱独坐，禅暇稍吟诗。","与世真无涉，逢人辄解颐。","幽栖偏得性，辛苦勉从师。","所赖惟多病，投艰或可迟。"]},{"t":"雪木院主入山却赠","f":"五言律诗","c":["湘江成久住，数月未曾閒。","无事难离院，因人时入山。","落帆摇鸟外，走马出林间。","冠盖南城近，陪欢莫上关。"]},{"t":"喜陆太守孝山长斋因其生日作诗四首寄之 其一","f":"五言律诗","c":["山中传好信，数月已长斋。","悟物知生事，平情近道怀。","幅巾称弟子，梵呗响庭阶。","更忆莲池上，刍言次第谐。"]},{"t":"喜陆太守孝山长斋因其生日作诗四首寄之 其二","f":"五言律诗","c":["公堂宁碍道，隐几忽闻雷。","侧耳承谁力，古人今再来。","竹声和午磬，云影落香台。","寂寞官斋里，居然万壑回。"]},{"t":"喜陆太守孝山长斋因其生日作诗四首寄之 其三","f":"五言律诗","c":["谁云吾道隘，太守近能禅。","视事经坛外，观心晓箭前。","护生先茹澹，息讼共清缘。","多士南州遍，弦歌钟梵边。"]},{"t":"喜陆太守孝山长斋因其生日作诗四首寄之 其四","f":"五言律诗","c":["悲心犹及物，窒欲见初生。","寂感于何兆，形骸空有名。","一身从隐显，万汇托生成。","月落秋潭夜，分明雁过声。"]},{"t":"秋风二首 其一","f":"五言律诗","c":["飕飕不可闻，霜叶落纷纷。","送雨归深壑，催钟度远云。","一帆天外至，众籁枕边分。","萧索当秋意，冷然聊赠君。"]},{"t":"秋风二首 其二","f":"五言律诗","c":["秋草吹将尽，寒香忽送来。","轻盈衣带下，叱吸纸窗开。","羽客归何处，幽人独上台。","徘徊山日落，萧瑟夜猿哀。"]},{"t":"秋月二首 其一","f":"五言律诗","c":["一片寒光彻，山河影自分。","雁翎空里映，鹤唳镜中闻。","藉草明衣露，盈梢湿水云。","西风吹浪起，江色白纷纷。"]},{"t":"秋月二首 其二","f":"五言律诗","c":["万里光如昼，谁能别一天。","澄江沙际迥，贾客夜深眠。","银烛照难见，涧泉清可怜。","捲帘看独远，浩淼欲茫然。"]},{"t":"秋灯二首 其一","f":"五言律诗","c":["静夜疏林透，遥山一点微。","风高围土屋，月落上人衣。","不共华筵醉，如怜独策归。","寒云千嶂合，谁与待朝晞。"]},{"t":"秋灯二首 其二","f":"五言律诗","c":["西风月未上，明灭出秋原。","我自暗中见，人从光里昏。","归舟摇远浦，落叶点孤村。","掩映前林动，夜深疑有猿。"]},{"t":"秋雁二首 其一","f":"五言律诗","c":["雪消方北迈，霜动又南征。","生自冱寒地，曾无炎热情。","河山今古暂，云水去来轻。","为爱空潭影，长留秋月明。"]},{"t":"秋雁二首 其二","f":"五言律诗","c":["溪关非所计，芦苇是生涯。","自顾寒云影，谁怜明月怀。","一泓秋水怯，几字晓天排。","南北空沙渚，飞鸣成独谐。"]},{"t":"看病二首 其一","f":"五言律诗","c":["日日忧人病，不知余病深。","何曾增药力，空费老婆心。","夜月虚阶步，山钟促曙襟。","久安生老死，犹自独沉吟。"]},{"t":"看病二首 其二","f":"五言律诗","c":["余心不得已，静想亦奚为。","续命非关药，劳形只是痴。","百年同旦夕，转盼忽支离。","独坐空长啸，人天何太迟。"]},{"t":"春晴","f":"五言律诗","c":["春日丽如此，云开应有时。","落花红点径，垂柳绿成丝。","海燕频将子，山泉已满池。","老来閒步履，安得少年知。"]},{"t":"寄端州文社诸公","f":"五言律诗","c":["端州有莲社，闻欲入丹山。","思见宗雷久，方惭慧远閒。","临风裁素札，对月待春关。","须忆身前后，茫茫去住间。"]},{"t":"送衣石下山兼订复来","f":"五言律诗","c":["六十又过四，千华重授衣。","青山不可再，白首好相依。","梅发随流去，春来逐雁归。","相期寒食候，垂绿半开扉。"]},{"t":"得澹归稍病即愈之讯时会龙拟新搆走笔寄之","f":"五言律诗","c":["岌岌忧予老，劳劳爱汝贤。","尽教身外绊，何可病相缠。","近水还成屋，临门见泊船。","展书欢无极，此意孰相怜。"]},{"t":"月下见水仙残叶","f":"五言律诗","c":["寒月照残叶，花疑入月中。","似看空有色，不见雪乘风。","香远馀兰质，冰销湿桂松。","莫将摇落意，孤负藐山翁。"]},{"t":"杜鹃花","f":"五言律诗","c":["千株红照日，深浅染啼痕。","不尽湘妃泪，难招蜀帝魂。","芳心随野阔，春色向人论。","莫以悲欢态，年年醉石门。"]},{"t":"望石鉴归舟不至二首 其一","f":"五言律诗","c":["遥闻石长老，归自栖贤堂。","知尔风尘苦，怜予海日长。","江深连夜雨，风逆半程樯。","出户望春树，新晴泛夕阳。"]},{"t":"望石鉴归舟不至二首 其二","f":"五言律诗","c":["眼望千峰迩，心悬一夜遥。","山禽迷野岸，春柳暗横桥。","夕照江河阔，风灯云树摇。","何堪更筹量，欢会在明朝。"]},{"t":"何事二首 其一","f":"五言律诗","c":["何事独愁绪，年高犹未閒。","坡悬筋力少，人病药囊悭。","薄曙先钟起，深宵后月还。","不如闻见远，甘学二乘顽。"]},{"t":"何事二首 其二","f":"五言律诗","c":["何事独愁绪，劳劳空自知。","势穷那可已，心苦欲谁为。","学道翻成累，投閒已恨迟。","坐看山月上，遮莫夜猿悲。"]},{"t":"已许二首 其一","f":"五言律诗","c":["已许老来暇，忙忙六十三。","知从今日去，复作几年憨。","薄劣唯堪隐，愚狂不自谙。","晓看春又尽，竹影入澄潭。"]},{"t":"已许二首 其二","f":"五言律诗","c":["已许逃人世，深山愧道名。","自甘不是佛，人乃未忘情。","柳暗藏莺密，天高见鹤清。","幽栖堪卒岁，何苦独营营。"]},{"t":"春晴月下与诸子散步","f":"五言律诗","c":["共步层峰下，新晴夜月初。","松高人影怯，云散鸟声虚。","倚石听泉落，迎风过竹疏。","人生如此夕，消得几踌躇。"]},{"t":"江涨","f":"五言律诗","c":["江涨因春雨，群山汇巨流。","水禽飞上树，贾客不登舟。","稚子争持钓，村翁忙凿沟。","茫茫烟树合，吾自倚高楼。"]},{"t":"慰栖贤石长老病二首 其一","f":"五言律诗","c":["荦荦堪谁道，轩渠为尔吟。","一年愁去路，千里独归心。","世故逢人浅，肝肠与病深。","且将形影息，高卧锦江岑。"]},{"t":"慰栖贤石长老病二首 其二","f":"五言律诗","c":["何曾吾道拙，带病事深耕。","辛苦酬先泽，绸缪淡俗情。","千溪停鹤梦，一枕入蝉声。","金井桥边水，秋来彻底清。"]},{"t":"康熙庚戌孟秋制府周彝初持服北归道出韶石订入山不果赋诗三首奉柬兼以为别 其一","f":"五言律诗","c":["奉命临南越，含哀返蓟门。","双旌发穗水，千骑指相原。","布地初成果，论因知有源。","途中应计日，遥礼法王尊。"]},{"t":"康熙庚戌孟秋制府周彝初持服北归道出韶石订入山不果赋诗三首奉柬兼以为别 其二","f":"五言律诗","c":["孝治兴朝重，覃恩守制还。","哀音联北雁，遗爱见南蛮。","愿深楼至后，心许懒残閒。","渺渺江云暮，停舟何处湾。"]},{"t":"康熙庚戌孟秋制府周彝初持服北归道出韶石订入山不果赋诗三首奉柬兼以为别 其三","f":"五言律诗","c":["节钺王臣贵，灵山嘱自今。","断肠萦子舍，翘首望祇林。","云影藏龙浅，天花积雨深。","他年重奉诏，应记入山心。"]},{"t":"云从大士随制府还北口占寄别","f":"五言律诗","c":["专阃军威重，陪驺入帝乡。","相水摇龙虎，丹山仰凤凰。","金绳天界现，玉轴梵宫藏。","盛事非今昔，空闻姓字香。"]},{"t":"挽刘平田仪部","f":"五言律诗","c":["文章传胜国，苦节著当今。","高寄遗民迹，徘徊选佛心。","八行馀绪论，千里想清音。","邈矣嗟梁木，典型何处寻。"]},{"t":"病中刘德馨太史过访","f":"五言律诗","c":["再访情弥笃，人扶出见难。","病魔辜客意，官舫送秋寒。","暂作江淮别，宁知天地宽。","明春有归雁，消息到长干。"]},{"t":"黎同三见访索诗时予在病中","f":"五言律诗","c":["广南有佳士，远访庐山岑。","卧病机输我，维摩默至今。","隔林人影怯，掩烛夜堂深。","写照霜筠月，三年出袖吟。"]},{"t":"复生松用谢秋水韵","f":"五言律诗","c":["铁干嗟犹在，相看各自怜。","冰霜还暮岁，泽溉不乘权。","吊古成今日，伤生忆往年。","祇须同后死，珍重未凋前。"]},{"t":"玉帘泉用伦使君韵","f":"五言律诗","c":["界破青山色，相看面目真。","不因矜碎玉，何事到金轮。","莫问东流意，还同此日春。","云烟笼不住，迢递出风尘。"]},{"t":"送端严侍者归省","f":"五言律诗","c":["宁亲千里去，一衲念春寒。","匡岳经初隐，黄梅莫久安。","燕雏新引子，竹笋未成竿。","望汝归长夏，南薰山日漫。"]},{"t":"用韵送方楼冈之楚","f":"五言律诗","c":["泉石添新梦，干戈滞故乡。","兴亡非我事，去住为人伤。","归雁逢春雪，饥蚕念古桑。","江淮千万里，湘水旅魂长。"]},{"t":"初秋示大绍禅人归省","f":"五言律诗","c":["送汝宁亲去，西风妒晚荷。","蝉声辞石镜，雁影到淮河。","故里白云少，家山黄叶多。","夜来牛火怯，须忆老婆和。"]},{"t":"题一树轩示诸子二首 其一","f":"五言律诗","c":["将军无此树，独立叹当时。","荫阔人空过，风多鸟不知。","高柯怜曲干，密叶覆低枝。","暂托安禅处，还山尔莫悲。"]},{"t":"题一树轩示诸子二首 其二","f":"五言律诗","c":["梦里水云隔，贪凉附薜萝。","海隅疑广莫，瓠落对山河。","席户迎风细，推窗得月多。","荣枯不可问，寥寂当如何。"]},{"t":"送严天莫入京谒选","f":"五言律诗","c":["送尔选官去，天然今不然。","幞头无道俗，朝宁赖英贤。","湖水通淮直，庐峰逼汉连。","匡时须努力，投老在何年。"]},{"t":"悼旋庵湛都寺六首 其五","f":"五言律诗","c":["行业人天重，因缘吾道轻。","庄生宁厌死，尚子欲如生。","易引丹霄步，难辞荆棘行。","洪波鼓冥壑，长人亦自惊。"]},{"t":"悼旋庵湛都寺六首 其六","f":"五言律诗","c":["色声情易尽，来往梦难消。","眼见浮沤幻，生当识浪娇。","莫嫌千仞壑，珍重一梢瓢。","与尔他生别，应防独木桥。"]},{"t":"秋夜坐竹下口占示净成诸子四首 其一","f":"五言律诗","c":["开径岂容易，搴萝赖汝曹。","閒时须得趣，忙里莫辞劳。","竹月筛空地，松风走怒涛。","纵观尘世苦，无过住山高。"]},{"t":"秋夜坐竹下口占示净成诸子四首 其二","f":"五言律诗","c":["月色入林悄，溪声到枕寒。","山中风味别，人外泬寥宽。","有力耕锄易，无钱结构难。","莫嗟生事薄，乘夜绕秋坛。"]},{"t":"秋夜坐竹下口占示净成诸子四首 其三","f":"五言律诗","c":["往返含鄱路，鸠材作栋梁。","他时茅殿月，此日草头霜。","莫笑买山拙，应怜避世狂。","请看秋雁影，随意上潇湘。"]},{"t":"秋夜坐竹下口占示净成诸子四首 其四","f":"五言律诗","c":["秋汉连湖白，山枫入涧红。","孤尔独行外，惭予静对中。","境疑劳逸异，心与忆忘同。","归鸟投林疾，高低息夜钟。"]},{"t":"诃衍摩静主五十初度","f":"五言律诗","c":["五十年前事，能无堕悄然。","视生如汝否，掩室占谁先。","竹密栖云煖，山高见月圆。","风光犹未晚，汨汨念时贤。"]},{"t":"送尘异归省","f":"五言律诗","c":["宁亲为令子，何以慰而师。","万里干戈日，三冬霜雪时。","入关逢旧识，出岭数新诗。","予老无人侍，言归莫过期。"]},{"t":"遣慧潜随尘异但子归省","f":"五言律诗","c":["劳汝送予子，子安予乃安。","临风须早泊，戴月慎朝餐。","去路桃花煖，回山梅蕊繁。","此心随所到，梦倚碧琅玕。"]},{"t":"一峰辞予泪下感而示此","f":"五言律诗","c":["辞我归丹岫，潸然泪满襟。","去留伤老大，山水畏高深。","为道思初日，离情盼远岑。","及时须努力，莫负古人心。"]},{"t":"偶成","f":"五言律诗","c":["世情何足论，寿夭亦徒然。","妙指法琴瑟，同根翻地天。","白云笼嶂北，溪水绕门前。","高卧镜楼下，谁云造物偏。"]},{"t":"送尘异掩关","f":"五言律诗","c":["绕肠离我子，冷面作而师。","祖道于今坠，天龙舍汝谁。","莫尝刀上蜜，休系藕中丝。","十载清霜操，斯文允在兹。"]},{"t":"刘莘叟携其子二人孙四人入山有诗见赠而韵四出予即依其格答之盖诗取见情不必区区也","f":"五言律诗","c":["别驾刘莘老，遥来看老僧。","言真无巧拙，情至少逢迎。","话我似弥勒，谁当辨浊清。","多携孙若子，相视笑亭亭。"]},{"t":"忆方楼冈","f":"五言律诗","c":["之子颇好道，难忘是世心。","劝归江上稳，偏向楚中寻。","失路疑南北，乘风竟陆沉。","普施应有作，休负白头吟。"]},{"t":"和尘异松下春兰诗二首 其一","f":"五言律诗","c":["春兰松下放，弱质倚松盘。","岂易承春暖，曾经怯岁寒。","枝蟠香自结，月照影成澜。","大树知能护，寻源人共看。"]},{"t":"和尘异松下春兰诗二首 其二","f":"五言律诗","c":["花瘦松脂毓，根盘兰叶张。","春霜难损色，夜月暗生香。","高荫朝昏静，深藏臭味长。","仰看云影布，荣落岂相忘。"]},{"t":"送泽萌遇长老住华首","f":"五言律诗","c":["吾师开法地，虚席已多年。","鈯斧承先匠，雄风仰后贤。","高标千嶂木，深牧两溪烟。","坐断飞云上，红轮覆五天。"]},{"t":"初春送山燄监寺之西安","f":"五言律诗","c":["出山何所适，百二秦关长。","旅次谋晨夕，春寒慎俶装。","垂鞭堤柳短，中食客途忙。","宝殿赖经始，倚门夏日长。"]},{"t":"病中三首 其一","f":"五言律诗","c":["老去因人病，情疏且自宽。","蒙头销意气，拨火耐春寒。","霜月澄潭迥，梅花积雪残。","一双青白眼，长日似流湍。"]},{"t":"病中三首 其二","f":"五言律诗","c":["俯仰成辜负，思量总惘然。","博山临别语，寝室抚膺年。","举目看朝菌，遐心托杜鹃。","老成匏落尽，遮莫误先传。"]},{"t":"病中三首 其三","f":"五言律诗","c":["自顾愿王在，残灯岂复明。","馀生犹有待，后死得无成。","我法如江汉，倾怀托弟兄。","诲人吾不倦，宁更惜身名。"]},{"t":"新种梅花开一朵朵","f":"五言律诗","c":["去年栽此梅，今岁一花开。","稍露知根在，不萌畏雪摧。","枝繁怜独立，寒尽待人来。","白眼应谁见，凭栏香暗回。"]},{"t":"诗成行者报再放一朵","f":"五言律诗","c":["一花开可喜，况又一花开。","清韵非无偶，幽姿不待媒。","双双寒月并，寂寂暗香陪。","莫道知希贵，孤根护宝胎。"]},{"t":"叹逝","f":"五言律诗","c":["天高不可问，人事日荒唐。","芳草绿绵密，王孙归渺茫。","释子平湖殁，无禅穗石亡。","馀生多涕泪，孤雁入寒塘。"]},{"t":"季春书怀","f":"五言律诗","c":["山静无人到，春深鸟不知。","少眠怜夜短，多病厌身危。","不觉夕阳下，空嗟朝槿迟。","双眸青复白，岂敢忆当时。"]},{"t":"镜","f":"五言律诗","c":["当台光自满，与像一无穷。","信此空成色，悬知异亦同。","徽猷千古上，掩映十方中。","寒照无人处，深潭吼夜龙。"]},{"t":"空","f":"五言律诗","c":["谁拟虚空相，所见是顽空。","钝置僧繇笔，徒劳造化功。","易开云里月，难系岭头风。","廓尔无知识，寥寥太古中。"]},{"t":"水","f":"五言律诗","c":["本自无筋骨，能乘万斛舟。","入河惟一湿，到海汇千流。","且莫惊波浪，还须识泡沤。","相逢冷暖意，智者翻增愁。"]},{"t":"风","f":"五言律诗","c":["号号吹万窍，难触是虚空。","岂费纤毫力，惟观动静同。","谁当随所转，势尽恨无穷。","有感斯皆累，休誇列子功。"]},{"t":"卜隐洪岩","f":"五言律诗","c":["解院寻深隐，洪岩最上关。","碧霄怜老拙，高视谢人寰。","举世魔风炽，惭予壮志顽。","愿生真有道，早慰圣明颜。"]},{"t":"归宗山籁一百四首 其一","f":"五言律诗","c":["滂沱昨夜雨，晴好忽今朝。","策杖归初地，登堂布旧条。","老成怀德在，小子习心销。","从此风规远，金轮瑞气昭。"]},{"t":"归宗山籁一百四首 其二","f":"五言律诗","c":["胜地传匡岳，名蓝属此间。","右军初舍宅，耶舍接开山。","六朝频易主，一代愧为颜。","绍续兵荒后，安禅但掩关。"]},{"t":"归宗山籁一百四首 其三","f":"五言律诗","c":["来日嗟犹及，去年何足云。","归乌愁暮雨，衰草怯秋云。","林下惟行道，山斋罢论文。","时名焉可苟，垂老畏空闻。"]},{"t":"归宗山籁一百四首 其四","f":"五言律诗","c":["昔年曾住此，屡梦到山中。","彭蠡城边月，鸾溪寺里钟。","簇新春草绿，依旧野花红。","黄鸟知予意，关关啭晚风。"]},{"t":"归宗山籁一百四首 其五","f":"五言律诗","c":["梅花开雪里，不畏寒风吹。","百卉凋伤日，一溪烟雨时。","枝从行路折，香爱晓窗知。","自惬幽人意，宁辞鸿雁疑。"]},{"t":"归宗山籁一百四首 其六","f":"五言律诗","c":["已得溪山意，何疑世上情。","腊穷松自见，寒尽草频生。","撼树风声惨，入潭人影清。","嗒然忘语默，不但百怀轻。"]},{"t":"归宗山籁一百四首 其七","f":"五言律诗","c":["世间贵文字，吾道慎支离。","以此薄词藻，相看空墨池。","凿沟疏水路，先雨葺茅茨。","莫笑禅枯澹，清宵试一思。"]},{"t":"归宗山籁一百四首 其八","f":"五言律诗","c":["管奏石泉细，图开峦岫横。","临池爱人影，近柳羡莺声。","日落溪云重，月明山雾轻。","万缘何处去，持此慰生平。"]},{"t":"归宗山籁一百四首 其九","f":"五言律诗","c":["日暮欲何去，迢遥咫尺中。","繁花红岸北，细草绿畴东。","舐犊怜牛老，回车念客穷。","涂长谁信宿，条柳倚春风。"]},{"t":"归宗山籁一百四首 其十","f":"五言律诗","c":["观世得无我，随时且爱人。","山川若是画，泡幻更谁真。","寒鸟生台饭，空林雪夜春。","等閒离合处，迢递总风尘。"]},{"t":"归宗山籁一百四首 其十一","f":"五言律诗","c":["云水何曾异，茅房独自真。","晴空休瞪目，寒色更宜人。","岂爱潭中月，知无花外春。","莫随吾与若，疑误住山身。"]},{"t":"归宗山籁一百四首 其十二","f":"五言律诗","c":["高峰月正白，一半是溪云。","空满川光合，烟沉石溜分。","寒灰香后散，归鸟声先闻。","如梦谁堪似，吾今不欲云。"]},{"t":"归宗山籁一百四首 其十三","f":"五言律诗","c":["衰老成疏节，孤危寄上岑。","钟声霜殿湿，月色夜堂深。","雪鸟无寻处，春花不择林。","岂甘为散诞，随分见余心。"]},{"t":"归宗山籁一百四首 其十四","f":"五言律诗","c":["石镜摇初日，金轮隐暮云。","如何此际见，不似昔年闻。","雨过寒塘静，风交春树殷。","从来人贵耳，伫望独云云。"]},{"t":"归宗山籁一百四首 其十五","f":"五言律诗","c":["名利能生诈，人心各自良。","常因徇理处，迸起护情方。","泉石能降习，烟霞别有长。","曾随寒涧水，一鉴得参商。"]},{"t":"归宗山籁一百四首 其十六","f":"五言律诗","c":["坐月候钟鸣，阶前虫韵清。","定中山觉静，闻外水无声。","花影何曾动，天光空自横。","禅房门半掩，廊外有人行。"]},{"t":"归宗山籁一百四首 其十七","f":"五言律诗","c":["厨灰方欲冷，添钵望归来。","朱户知难扣，青苗犹未栽。","香烟迟午食，鸟雀下空台。","松径无生客，庭阴长绿苔。"]},{"t":"归宗山籁一百四首 其十八","f":"五言律诗","c":["轻飙不入户，就地且乘凉。","殿后垂枫密，门前藉草芳。","江山宁有尽，寒暖但随方。","得意即为乐，长歌过夜塘。"]},{"t":"归宗山籁一百四首 其十九","f":"五言律诗","c":["雨足期秋熟，无云嗟去年。","适予复来此，一众总茫然。","到处扣门拙，还山得食偏。","好从今日始，努力耕山田。"]},{"t":"归宗山籁一百四首 其二十","f":"五言律诗","c":["昨日米船到，肩担出郡河。","正当秧好插，更值吏催科。","午食尚难给，差徭且奈何。","青山岂易得，勉矣莫蹉跎。"]},{"t":"归宗山籁一百四首 其二十一","f":"五言律诗","c":["负米远千里，开书欣八行。","吾门犹有此，一众岂虞荒。","稚子白葵扇，老翁青竹床。","当轩且磅薄，乘倦到羲皇。"]},{"t":"归宗山籁一百四首 其二十二","f":"五言律诗","c":["行行自行行，性住步常轻。","一往知何事，周遭空复情。","鹤鸣还子和，鱼乐果谁明。","久矣忘渠我，何须辨浊清。"]},{"t":"归宗山籁一百四首 其二十三","f":"五言律诗","c":["心知非一一，林木自森森。","不识云烟幻，惟同岩壑深。","枕窥明月白，溪近野棠阴。","绝迹何云易，谁从行处寻。"]},{"t":"归宗山籁一百四首 其二十四","f":"五言律诗","c":["一条云路直，千顷野田平。","湖气干霄汉，松涛引梵声。","山深不数夏，僧老渐忘名。","吾欲从兹去，相将混耦耕。"]},{"t":"归宗山籁一百四首 其二十五","f":"五言律诗","c":["山云时出没，溪水日平漫。","世外无拘束，人间有易难。","屋疏宵不寐，肺病午方餐。","野鸟真堪近，喃喃不畏寒。"]},{"t":"归宗山籁一百四首 其二十六","f":"五言律诗","c":["出门遂觉远，仍在此山丘。","独自有馀乐，于人无复求。","绿畴眠白鹳，赤土涂黄牛。","所向何曾异，从生至白头。"]},{"t":"归宗山籁一百四首 其二十七","f":"五言律诗","c":["茅堂饮啄惯，不愿朱门多。","林下拾朝菌，池边赏晚荷。","无人常独立，有兴忽长歌。","恃此能无病，兼之遣睡魔。"]},{"t":"归宗山籁一百四首 其二十八","f":"五言律诗","c":["目前生意满，到处野情疏。","藤挂偷梨鼠，苔沉入涧鱼。","农夫忙播种，稚子懒观书。","旷大劫来事，悠然见太初。"]},{"t":"归宗山籁一百四首 其二十九","f":"五言律诗","c":["山池荷未放，忽已过端阳。","花木宜天暖，人情耽夜凉。","去年苦不雨，今夏满方塘。","预卜秋田稔，可能无再荒。"]},{"t":"归宗山籁一百四首 其三十","f":"五言律诗","c":["主人有逸兴，招我坐龙潭。","危瀑乘风下，平流倒日涵。","纵观心欲一，细听耳成三。","明日端阳节，携筇返故龛。"]},{"t":"归宗山籁一百四首 其三十一","f":"五言律诗","c":["是非何日已，同异百年身。","了此不相顾，何劳问幻真。","天高云出没，林阔鸟疏亲。","秋草自衰变，西风宁与人。"]},{"t":"归宗山籁一百四首 其三十二","f":"五言律诗","c":["山深气序易，六月著寒衣。","酷暑不终日，轻飙时到扉。","欺人夜色冷，落涧泉声微。","久矣忘艰苦，谁为别是非。"]},{"t":"归宗山籁一百四首 其三十三","f":"五言律诗","c":["年来无彼我，谁谓匪心安。","古道于今少，人情到此难。","鹏飞六月息，鹪寄一枝寒。","相笑何时已，逍遥海岳宽。"]},{"t":"归宗山籁一百四首 其三十四","f":"五言律诗","c":["山岚朝不散，水雾午犹遮。","地僻惟僧到，县贫无药赊。","崖头悬拄杖，石上晒袈裟。","只此自知处，须怜日易斜。"]},{"t":"归宗山籁一百四首 其三十五","f":"五言律诗","c":["山远有猿噭，溪深无水声。","夜来云际火，照见古湓城。","微月入林浅，归鸦到树轻。","心间纡暝色，含盼不胜情。"]},{"t":"归宗山籁一百四首 其三十六","f":"五言律诗","c":["别去三千里，传来一纸书。","王家增佛日，山叟爱吾庐。","华屋少年侈，茅檐老景舒。","仰人殊未易，服食倚耕锄。"]},{"t":"归宗山籁一百四首 其三十七","f":"五言律诗","c":["閒心山事夥，堪见不堪云。","鹤照池中影，人行岭上云。","林交容马过，池阔到村分。","日夕疏钟起，谁从定后闻。"]},{"t":"归宗山籁一百四首 其三十八","f":"五言律诗","c":["懒眠常竟日，纸被喜新成。","门外无人候，床头有鼠声。","鸟来从自去，雨过不知晴。","寄语朝中贵，能无此夕情。"]},{"t":"归宗山籁一百四首 其三十九","f":"五言律诗","c":["莫道丹霞热，鸾溪热有馀。","云高峰顶薄，雨少柏阴虚。","树密风过岸，篱穿日照庐。","但除心里火，随分且耕锄。"]},{"t":"归宗山籁一百四首 其四十","f":"五言律诗","c":["百岁行过半，全身托翠微。","犹嫌刍食恶，更觅菜羹肥。","过午金仙训，忧贫鲁士讥。","我心真匪石，抗手谢同衣。"]},{"t":"归宗山籁一百四首 其四十一","f":"五言律诗","c":["只今惟守拙，闭户逊时贤。","身退名何在，情穷道不迁。","朝看云里岫，暮听竹边泉。","与众同居止，降心一味禅。"]},{"t":"归宗山籁一百四首 其四十二","f":"五言律诗","c":["匡月入湖小，千波影共圆。","月光不到水，水月岂从天。","对镜看群岫，依林数过船。","个中谁是主，敛目独澄然。"]},{"t":"归宗山籁一百四首 其四十三","f":"五言律诗","c":["自笑生涯拙，犹能不怕穷。","就泉惟酌茗，移榻爱当风。","到老凭谁力，千峰一策通。","不知人事易，随意任西东。"]},{"t":"归宗山籁一百四首 其四十四","f":"五言律诗","c":["湖水连天白，登高见远帆。","肝肠付寥廓，形影托松杉。","心在何劳圣，情忘莫厌凡。","一般孤月迥，容易住层岩。"]},{"t":"归宗山籁一百四首 其四十五","f":"五言律诗","c":["山鸡半夜鸣，月落溪云生。","坐久悬灯暗，门开宿鸟惊。","何人于此得，独自绕檐行。","三十年前后，松涛一样声。"]},{"t":"归宗山籁一百四首 其四十六","f":"五言律诗","c":["祇园临大路，独立数晨宵。","官树贫人斫，春田野火烧。","云封当涧屋，月暗近山桥。","夕鸟催归客，松林断续招。"]},{"t":"归宗山籁一百四首 其四十七","f":"五言律诗","c":["祖意在山边，水牛眠野田。","深知黄叶趣，不坐白云禅。","鸠唤栽秧雨，风牵上水船。","此中无限意，肯向外人传。"]},{"t":"归宗山籁一百四首 其四十八","f":"五言律诗","c":["山食只粗粝，怜予谢少年。","岂当为苦节，贫贱得安禅。","多病偏宜澹，无缘但听天。","相从忘岁月，始觉及门贤。"]},{"t":"归宗山籁一百四首 其四十九","f":"五言律诗","c":["兴来谭往事，相逐过西溪。","解意忘前后，因人有笑啼。","语諠山岳静，树远夕阳低。","微月挂檐隙，回途尚不迷。"]},{"t":"归宗山籁一百四首 其五十","f":"五言律诗","c":["故山几日别，临崖一指间。","依然丹岫月，只度大庾关。","饮水知源远，耕田傍寺閒。","老年筋力少，不敢畏痴顽。"]},{"t":"归宗山籁一百四首 其五十一","f":"五言律诗","c":["院后遗残屋，吾师旧掩关。","湖光先日照，塔影驻云间。","对此无馀说，秖应时往还。","且教■子住，予欲老投閒。"]},{"t":"归宗山籁一百四首 其五十二","f":"五言律诗","c":["理策随身去，行行过石桥。","夕阳悬树杪，山犬吠藤条。","认得灵溪路，曾无道士招。","玄关予亦透，但不上青霄。"]},{"t":"归宗山籁一百四首 其五十三","f":"五言律诗","c":["独唳不堪闻，孤松影到曛。","落虹摇浅濑，归犊出深云。","顾我当奚似，于人何可云。","古来多显达，垒垒见高坟。"]},{"t":"归宗山籁一百四首 其五十四","f":"五言律诗","c":["身在难忘世，机停始见山。","龟蛇知雨至，鸿雁及春还。","月出胸怀爽，霜飞道路艰。","层峦与孤屿，能得几人閒。"]},{"t":"归宗山籁一百四首 其五十五","f":"五言律诗","c":["目前谁是客，梦里悟多身。","莫辨客中主，宁知身外人。","西风飘一叶，万木敛三春。","启我惟秋色，优游林下真。"]},{"t":"归宗山籁一百四首 其五十六","f":"五言律诗","c":["尽言黄独美，难得白云横。","岂是一生事，都酬旷劫情。","钟敲霜叶落，雁叫碧潭惊。","不了目前意，空怜道者名。"]},{"t":"归宗山籁一百四首 其五十七","f":"五言律诗","c":["密树连云暗，残荷杂草香。","心孤寄水月，年迈历秋霜。","世有高僧传，人无辟谷方。","方知林下士，多半为閒忙。"]},{"t":"归宗山籁一百四首 其五十八","f":"五言律诗","c":["群岫当轩入，寒泉到枕边。","何须更举足，只在此中眠。","睹影日中鸟，闻声梦里蝉。","萧条自岑寂，莫与懒人传。"]},{"t":"归宗山籁一百四首 其五十九","f":"五言律诗","c":["黄叶纷纷坠，白云片片飞。","只闻辞社燕，不见捣寒衣。","世故山城远，清秋霜露微。","野人无感激，寂寞掩柴扉。"]},{"t":"归宗山籁一百四首 其六十","f":"五言律诗","c":["三日松风生，五天檐雨声。","此时大麦熟，秋谷仓箱盈。","荒后人心约，安贫势利轻。","世间与世外，何事不相成。"]},{"t":"归宗山籁一百四首 其六十一","f":"五言律诗","c":["秋原怀远踪，想像正无穷。","问路草初白，遥山叶欲红。","销磨云水里，俯仰客情中。","洒拂禅房静，还家听塞鸿。"]},{"t":"归宗山籁一百四首 其六十二","f":"五言律诗","c":["一觉开门出，月明才四更。","江流浮夜色，石濑引秋声。","敛听忽何有，冥心合太清。","谁当更复忆，不可号无名。"]},{"t":"归宗山籁一百四首 其六十三","f":"五言律诗","c":["五更山吐月，四望空无云。","树转西峰影，风斜北雁群。","上关仍就榻，稍坐见微昕。","世事惟高蹈，关河了不闻。"]},{"t":"归宗山籁一百四首 其六十四","f":"五言律诗","c":["柳叶夏已长，稻花秋更齐。","山门无一事，寻伴步西溪。","老鹳认人惯，田鸡过午啼。","村夫知雨至，指树觉天低。"]},{"t":"归宗山籁一百四首 其六十五","f":"五言律诗","c":["菊花开灿烂，溪水日潺湲。","不睹黄云暗，焉知白露繁。","稻粱迟社燕，茗盌对山村。","回首成衰迈，还应望石门。"]},{"t":"归宗山籁一百四首 其六十六","f":"五言律诗","c":["出栊金锁鸟，杀羽向山丘。","不啄黄金盌，空栖青树头。","往还愁俊鹘，居止学巢鸠。","长翮虚空阔，高低纵晚秋。"]},{"t":"归宗山籁一百四首 其六十七","f":"五言律诗","c":["何处堪栖息，烟霞隐梵宫。","鸟摇篱菊嫩，犬吠夕阳空。","问世无成策，安心只是穷。","老僧惟有退，含笑委长风。"]},{"t":"归宗山籁一百四首 其六十八","f":"五言律诗","c":["满目无山水，全身已在林。","不因人自昔，那得我从今。","香暖流云幕，钟寒怯曙襟。","当时谁坐断，塔影尚沉沉。"]},{"t":"归宗山籁一百四首 其六十九","f":"五言律诗","c":["斗大梧桐树，当檐引晚风。","半留山月到，更与野禽通。","子落知秋老，枝疏惜岁穷。","衰荣看欲尽，独立意谁同。"]},{"t":"归宗山籁一百四首 其七十","f":"五言律诗","c":["雁叫微霜后，林寒细雨初。","板桥先度客，野圃罢烧畲。","望寺僧归疾，投城马去疏。","前涂云树合，回步竟何如。"]},{"t":"归宗山籁一百四首 其七十一","f":"五言律诗","c":["閒情销隐几，独觉愧婆和。","秋水无心照，山禽有影过。","拂空翻鸟迹，把火沸冰河。","人道虚神用，吾师念积屙。"]},{"t":"归宗山籁一百四首 其七十二","f":"五言律诗","c":["流水去无返，年华暑复寒。","根尘如梦起，识浪几时乾。","白日忙閒过，青山岁月宽。","尝闻高隐客，还共夕阳残。"]},{"t":"归宗山籁一百四首 其七十三","f":"五言律诗","c":["五更开户望，孤月照禅真。","脚踏生台影，灯摇绕佛身。","风停花入定，雁过水无尘。","不到空潭曲，难论旷世因。"]},{"t":"归宗山籁一百四首 其七十四","f":"五言律诗","c":["不是远人迹，都缘避世誉。","经行苔径没，燕坐草堂虚。","生死当知处，浮沤岂易除。","年来消息断，惭愧客情疏。"]},{"t":"归宗山籁一百四首 其七十五","f":"五言律诗","c":["主院至垂老，因人敢爱閒。","幸然无俗客，乘暇且看山。","掩户推云出，开窗揖月还。","高松投鹤影，永夜不成关。"]},{"t":"归宗山籁一百四首 其七十六","f":"五言律诗","c":["人定钟初歇，灯明夜最真。","闻猿几丧我，观树亦犹人。","万籁归何处，群机得所因。","谁当更消息，孤负陌头春。"]},{"t":"归宗山籁一百四首 其七十七","f":"五言律诗","c":["赋性偏多癖，违时追昔贤。","疏才居事后，勇退在人前。","自合栖岩壑，难教入市廛。","爱人殊未已，有约白云边。"]},{"t":"归宗山籁一百四首 其七十八","f":"五言律诗","c":["午睡鸟呼觉，交交声未休。","不知吾觉后，鸟意复何酬。","濯濯风前柳，洋洋石上流。","山中长似此，卒岁乐优游。"]},{"t":"归宗山籁一百四首 其七十九","f":"五言律诗","c":["发白垂将遍，眸青尚可观。","往年筋力异，来日杖头宽。","禅寂终宵尽，房栊薄暑寒。","岂堪贪茗盌，更使夕阳残。"]},{"t":"归宗山籁一百四首 其八十","f":"五言律诗","c":["空谷归人少，高峰落日寒。","望云惭老大，深夜绕栏杆。","万事省心力，六时惟内观。","浮生岂容易，休作少年看。"]},{"t":"归宗山籁一百四首 其八十一","f":"五言律诗","c":["歘然一自返，头白老青山。","俯鉴游鱼戏，仰看飞鸟还。","身随松鹤瘦，心逐野鸥閒。","旦晚清阴下，安知世路艰。"]},{"t":"归宗山籁一百四首 其八十二","f":"五言律诗","c":["不择名山老，江流尽有源。","金轮承雨露，华首接云根。","一榻长霄迥，千峰古木繁。","终焉复何憾，相视欲无言。"]},{"t":"归宗山籁一百四首 其八十三","f":"五言律诗","c":["含晖欣晚景，立雪忆当时。","我亦承人后，谁无一日知。","江流深不测，云影变多奇。","峰顶孤松色，岁寒然后知。"]},{"t":"归宗山籁一百四首 其八十四","f":"五言律诗","c":["百岁过驹隙，憧憧何所成。","机深天性薄，欲寡道心生。","世故岂难见，林泉空有名。","吾生少营虑，于此独能明。"]},{"t":"归宗山籁一百四首 其八十五","f":"五言律诗","c":["不识幽栖趣，徒劳招隐心。","长空无雁影，流水误琴音。","虎豹畏山浅，鱼龙忘海深。","高林多绮角，莫向洞庭寻。"]},{"t":"归宗山籁一百四首 其八十六","f":"五言律诗","c":["谁信子期死，伯牙仍鼓琴。","从来无覆处，岂敢贵希音。","住久识山性，听多知水心。","晨宵欣独往，林下莫沉吟。"]},{"t":"归宗山籁一百四首 其八十七","f":"五言律诗","c":["往复长松下，相逢岂异人。","暗投愁按剑，什袭愧非珍。","过涧须眉在，啼林鸟雀亲。","生平吾不昧，以此得安贫。"]},{"t":"归宗山籁一百四首 其八十八","f":"五言律诗","c":["背山朝隐雾，傍殿夜闻钟。","忽忆此生事，都忘何处从。","百骸成聚散，一觉有春冬。","饮啄同山鸟，登临信竹筇。"]},{"t":"归宗山籁一百四首 其八十九","f":"五言律诗","c":["望夕光沉魄，晴林影尚微。","为云曾不是，即月岂全非。","过眼山容隐，含情夜色晖。","若教迟皓洁，已丧目前机。"]},{"t":"归宗山籁一百四首 其九十","f":"五言律诗","c":["坐落西轩月，行看东岭松。","易教云作水，难信石成钟。","物理自衰变，人情时夏冬。","是谁能免此，同上最高峰。"]},{"t":"归宗山籁一百四首 其九十一","f":"五言律诗","c":["对人时累足，闭目不观空。","偶起探晴岳，携筇过寺东。","古松摇涧底，怪石出云中。","多少住山事，茫茫逐异同。"]},{"t":"归宗山籁一百四首 其九十二","f":"五言律诗","c":["寒月窥帘悄，晴云覆岫阴。","一般閒景趣，识得道人心。","视听当犹昔，溪山岂自今。","愿同泉石老，猿鹤许相寻。"]},{"t":"归宗山籁一百四首 其九十三","f":"五言律诗","c":["一榻蒙头坐，千峰夕照移。","重云低匝地，微月上高枝。","气暖龙蛇蛰，山寒鸟雀饥。","不知春信至，即在夜长时。"]},{"t":"归宗山籁一百四首 其九十四","f":"五言律诗","c":["积雪通昏昼，丛光掩岳川。","闭门寒色敛，拥褐夜灯然。","三事白头衲，一床黄独烟。","青山非世僻，容得懒成颠。"]},{"t":"归宗山籁一百四首 其九十五","f":"五言律诗","c":["万古一弹指，云山梦里看。","目前销不易，荣落始知难。","大雪危峰出，残冰饥鸟欢。","拥垆对良夜，独自耐深寒。"]},{"t":"归宗山籁一百四首 其九十六","f":"五言律诗","c":["百情安一遇，得解不成文。","雪满云山合，澌流河汉分。","掩窗寒隔纸，煮茗叶烧云。","俯仰观尘劫，冥心知所云。"]},{"t":"归宗山籁一百四首 其九十七","f":"五言律诗","c":["人羡庞公好，全家隐鹿门。","但知山泽美，宁畏虎狼喧。","独树难藏影，旋岚不著痕。","此心无去住，何事更招魂。"]},{"t":"归宗山籁一百四首 其九十八","f":"五言律诗","c":["春草露先白，霜根雪后青。","拥垆当秉烛，饵药失颓龄。","引兴寻梅澹，凭高共鹤泠。","不辞摇落尽，寥寂自寒庭。"]},{"t":"归宗山籁一百四首 其九十九","f":"五言律诗","c":["閒中数往事，往往叹前因。","不信先贤语，几成衰世人。","身名存石室，岩壑老风尘。","借问鸾溪水，能回白草春。"]},{"t":"归宗山籁一百四首 其一○○","f":"五言律诗","c":["叹惜今时事，难追往哲风。","道随炎冷异，心与利名同。","拙朴甘吾塞，文章让世通。","陆沉终不易，何苦问污隆。"]},{"t":"归宗山籁一百四首 其一○一","f":"五言律诗","c":["何人能独立，云静与山深。","万木无行径，千峰稳住心。","拚教风逐虎，输去月同琴。","想望人天际，迢迢流水音。"]},{"t":"归宗山籁一百四首 其一○二","f":"五言律诗","c":["山泽匪耽寂，云林自作师。","好随明月去，休被晚风吹。","乱石填阶砌，长松荫后篱。","一从深入后，垆火不曾离。"]},{"t":"归宗山籁一百四首 其一○三","f":"五言律诗","c":["绳床方敛足，不觉到馀曛。","碧涧沉清影，青霄无片云。","夜猿愁月照，山鬼畏僧闻。","自笑为人浅，都惭与物分。"]},{"t":"归宗山籁一百四首 其一○四","f":"五言律诗","c":["晚年宜好静，日日数生涯。","候种畏寒早，为园及暖乖。","临风多远思，明月易生怀。","不作馀龄计，忙来亦自佳。"]},{"t":"归隐罗浮诗报老父","f":"七言律诗","c":["潦倒云岩日惘然，听泉时枕石头眠。","且非有意逃人世，那得閒情结俗缘。","盖代勋名都是梦，大家生死倩谁肩。","年来老大心须歇，百劫光辉在目前。"]},{"t":"还小持船示诸子","f":"七言律诗","c":["眼前一望黍离离，燕子忘机归亦迟。","当忆百年缘散处，莫随顷刻念生时。","黄粱未熟谁先觉，荷叶初开我已悲。","幸自临池多暇日，无生有诀慎相期。"]},{"t":"次韵答吉州周天木","f":"七言律诗","c":["今人行业古人心，落落孤标物外寻。","白鹭洲前春有脚，五羊城外海无音。","雄才未遂甘丘壑，清梦犹能到石林。","世运兴衰看不尽，赤松桥北未沉沉。"]},{"t":"送梁弼臣北上","f":"七言律诗","c":["天上只今已如此，丈夫出处倍相关。","时危不可徒干禄，亲老何妨暂住山。","绿树清泉身足隐，眠云坐石道能閒。","秘书未必赤松意，笑杀留侯空自还。"]},{"t":"郭无伤邝无畏见过","f":"七言律诗","c":["金粟如来是后身，澄潭孤月净无尘。","看同镜里人何似，话到声销道易亲。","铁树开残寒腊燄，雪花藏得旧年春。","水云上下深深意，鹤影松虬好结邻。"]},{"t":"西樵写怀十首 其一","f":"七言律诗","c":["乾坤内外绝为邻，梦里何劳问主宾。","治乱兴亡千古事，死生老病百年身。","白云欲锁寒山色，梅萼谁怜冻腊春。","石上因缘知几几，莫教浮世笑閒人。"]},{"t":"西樵写怀十首 其二","f":"七言律诗","c":["破衲蒙头一味真，随时粥饭莫嫌贫。","伊耆阪涿今何在，沧海桑田岂有垠。","已过身名他日泪，未来事业旧时人。","凭谁深信三生论，共坐樵峰话往因。"]},{"t":"西樵写怀十首 其三","f":"七言律诗","c":["一日閒来一日足，百年愁去百年忙。","须将后事翻前事，莫误今狂学古狂。","松覆石床人外寂，门开竹径意中凉。","诸缘易尽心难尽，好悟无生万法忘。"]},{"t":"西樵写怀十首 其四","f":"七言律诗","c":["溪声山色净无尘，独坐云峰意自新。","无智无能空笑我，多才多艺总输人。","百年生计须臾弃，历劫操存旦夕因。","一领衲衣閒不彻，箪瓢陋巷几曾贫。"]},{"t":"西樵写怀十首 其五","f":"七言律诗","c":["世外难忘物我情，败非成是不须争。","时来用尽生前福，事去徒矜死后名。","一念乍兴旷劫累，万缘休歇此身轻。","林泉大有甘心处，寒夜孤筇傍月行。"]},{"t":"西樵写怀十首 其六","f":"七言律诗","c":["身前身后事谁明，才忆因缘暗里惊。","猛士难催金锁骨，精兵不破涅槃城。","平原兔尽归将晚，黄石松疏荫未成。","一自世途机滚滚，青山历乱少人行。"]},{"t":"西樵写怀十首 其七","f":"七言律诗","c":["十年丘壑梦魂轻，渐喜人忘旧姓名。","影现情缘迷处尽，融通起灭静中明。","鸟啼花落空岩意，月淡云寒流水声。","老我儒冠劳半世，柴门犹得寄馀生。"]},{"t":"西樵写怀十首 其八","f":"七言律诗","c":["觅得茅庵奉老亲，玉泉清冽映松筠。","试茶暂过石桥北，步月遥看菊径新。","睦叟无鞋应愧母，隐峰有妹足閒身。","乱离法乐饶天乐，好共人间识旧因。"]},{"t":"西樵写怀十首 其九","f":"七言律诗","c":["身隐须教心共隐，遣情争似泯情佳。","桔槔转处聪明巧，机轴停来天地差。","逐浪随波人易偶，离非绝句道犹乖。","可怜林下逃名者，名重如山时未谐。"]},{"t":"西樵写怀十首 其十","f":"七言律诗","c":["青山满目匪人间，楖栗横挑自往还。","过客但闻时事慨，论心每觉道情悭。","目前活句堪谁举，天外摇头笑我顽。","近日有人知此意，明年三月掩柴关。"]},{"t":"戊子春掩关雷峰诸道俗见讯示此","f":"七言律诗","c":["四十年来弹指间，荷担大道不知顽。","无缘常恐法轮坠，多病偏怜梦幻悭。","业识未乾迷悟假，垢心忘尽圣凡閒。","于今剩有蒙头衲，敢效高僧闭死关。"]},{"t":"恭怀空老人","f":"七言律诗","c":["香花曾结胜缘欢，十载追随行路难。","忆别忽惊风俗异，感寒时念衲衣单。","月明千里心相照，云起双峰影独看。","已是道人情似水，一回潮满一回澜。"]},{"t":"梦馀轩","f":"七言律诗","c":["浪迹阎浮四十春，依稀重记劫前身。","白云万里空双眼，绿影横空足几人。","近竹淡烟他日梦，隔桥明月旧时津。","江山今古长如此，高卧峰头我欲贫。"]},{"t":"初秋","f":"七言律诗","c":["月落风高秋渐横，此时谁复论浮名。","巍巍独坐虚生白，寂寂幽林露有声。","久住深山无此意，偶观尘世乐閒情。","竹林薄梦先桐叶，不到寒更衣欲轻。"]},{"t":"怀祖心弟","f":"七言律诗","c":["故园泉石亦迟迟，万里云山此一时。","常对夕阳愁去雁，每因风雨梦连枝。","望空天地月能语，思共林梢花不知。","闻道江南多故老，笠瓢相访未应疑。"]},{"t":"怀湛六","f":"七言律诗","c":["四十扶筇筋力微，远檐平望独依违。","月明万里霜天直，云淡疏帘秋水肥。","远树苍茫辜客梦，乱流明灭有人归。","光辉已自成今古，赚我寒更露满衣。"]},{"t":"戊子九日","f":"七言律诗","c":["去年此日乱离中，霜叶寒花今又逢。","雁羽不堪穷漠北，戍歌犹是大江东。","烟销衰草横塘静，日照疏林秋浦红。","潦倒莫辞朝落帽，夜猿声急白蘋风。"]},{"t":"九日洪少宰西岩袁都宪特丘放生小持船赋此却寄","f":"七言律诗","c":["闻道重阳白社开，德云不在妙高台。","尽教鱼跃鸢飞去，识得长天秋水来。","贝叶肯和霜叶脱，昙花应傍菊花栽。","金钱不买陶潜醉，别有醍醐露一杯。"]},{"t":"九日忆梁未央用台设韵","f":"七言律诗","c":["百年踪迹客情悭，占得雷峰一日山。","篱菊饮残陶令酒，茱萸看尽杜卿颜。","死生多故闻秋雁，老大无心卧竹关。","为语登临但乘兴，长江滚滚几时还。"]},{"t":"复风幡堂旧趾","f":"七言律诗","c":["梦断风幡不可寻，虚堂犹见古人心。","一池春水临高阁，十亩荒烟想故林。","人事暗销芳草尽，道情偏共乱云深。","月明此地知何限，薄影横窗曾几吟。"]},{"t":"答商丘伯侯若孩","f":"七言律诗","c":["披衣夜夜睹明星，古寺寒塘户半扃。","笑我抛閒居市井，多君相见望州亭。","千家灯火销兵甲，万里烟波注海溟。","野老新承堂搆旧，好添封事进坛经。"]},{"t":"夏日书怀","f":"七言律诗","c":["云里无家何处归，平生踪迹尚依依。","休心阅世机常钝，拙算投林愿亦违。","入梦青山一榻稳，逢人丹荔半餐肥。","乱离不作终朝计，潦倒浓阴暂解衣。"]},{"t":"初秋郡守丞倅诸公过译经台","f":"七言律诗","c":["浩公载自鹿门至，谂老床头接赵王。","不是野人情简略，都缘护法意深长。","虎溪苔印秋容淡，玉带光流山色凉。","珍重诸贤然诺处，译经台畔木樨香。"]},{"t":"秋日喜袁特丘刘同庵过访","f":"七言律诗","c":["门无分水绕长松，亦枉高轩林下逢。","竹院风高先见雁，经台日午不闻钟。","无心于世秋偏冷，有意寻僧梦独浓。","相对秖应閒着眼，百年踪迹问云峰。"]},{"t":"与崔石师泛舟","f":"七言律诗","c":["深闭柴扉独种园，何人招我破云痕。","竹摇青影落河渚，日蘸寒光出海门。","秋水连天横小艇，晚烟笼树失孤村。","归来一路渔歌起，芦荻洲前月色温。"]},{"t":"忆老亲","f":"七言律诗","c":["寒涕垂垂一比丘，依林傍岸独誇犹。","甲兵老我半生事，饥渴消人百岁忧。","绿竹沿溪已无夏，青山入座望临秋。","海天浪拍门前月，远映高堂清欲浮。"]},{"t":"答刘客生中丞用来韵","f":"七言律诗","c":["海天秋色共茫茫，雁影长空入草堂。","有句不堪酬长老，无心曾否问空王。","裴公已结香花债，诸子谁教秘密藏。","选佛未应迟破衲，幞头先愿为人忙。"]},{"t":"葵扇二首 其一","f":"七言律诗","c":["谁将碧眼入芳丛，裁就云团欲荡空。","岂与世间忙腊月，且随云麓度秋风。","逍遥蓬户宜高士，摇落朱门傲贵公。","手里仙人君见否，不曾遮面透罗红。"]},{"t":"葵扇二首 其二","f":"七言律诗","c":["严寒始见世人容，寥落风尘独有侬。","逸士正宜青竹坞，老僧携上白云峰。","轻裾泛夜如飘素，薄暮投凉拟坐松。","似我何须畏炎热，和衣清昼梦魂浓。"]},{"t":"秋夜述怀","f":"七言律诗","c":["一龛灯火月微明，似听孤猿坐五更。","毳衲岂无芳草意，蒲团犹有倚寒情。","十年辜负西山梦，今日空惭渔父名。","假我百千疏散计，乱云叠嶂老馀生。"]},{"t":"寄庞若云用梁同庵韵","f":"七言律诗","c":["窗间犹见数峰青，已报秋归霜满庭。","添我道情空落落，赚谁人事独惺惺。","红炉点亦欺残腊，万派声须到巨溟。","倚石惯知寒瀑味，乘风无限意泠泠。"]},{"t":"答梁同庵叠前韵","f":"七言律诗","c":["挥空长剑倚天青，万里无云月在庭。","双眼阅穷终古意，百年聊复共人惺。","梦甜林麓空群岳，坐拥溪流失四溟。","谁道珠江江上水，亦随残腊冻泠泠。"]},{"t":"如是居忆椒园用憨山韵","f":"七言律诗","c":["川原历乱欲谁归，独有山人到竹扉。","恍忽旧时梅影冷，似曾寒坐月华微。","百年人事空潭影，一夕云林孤雁飞。","特地不堪重话处，倚栏顿尔发清机。"]},{"t":"吊王勃用达此韵","f":"七言律诗","c":["高阁凌霄尚壮哉，何人风雨渡江来。","影沈湖水秋烟冷，韵遏匡云碧嶂开。","多艺如君应薄命，閒情似我亦怜才。","遥知万古长天色，一度登临恨一回。"]},{"t":"酬汪明府用来韵","f":"七言律诗","c":["一从谷口白云横，世上谁当问隐名。","绿水绕门依古渡，青松夹岸喜秋声。","绳床久向空中坐，玉带难忘方外情。","此语莫教消息漏，溪桥深锁夜乌轻。"]},{"t":"岁晏和何朗水韵二首 其一","f":"七言律诗","c":["江门春色自何来，冷燄寒香暗里催。","物化共看谁着眼，旅怀独酌未成杯。","劳劳人外虎溪月，落落更残牛粪煤。","野衲不知时序易，数株松树一瓶梅。"]},{"t":"岁晏和何朗水韵二首 其二","f":"七言律诗","c":["扰扰劳生又到春，钟山投老倦蹄轮。","乾坤有恨销穷腊，江汉无情问隙尘。","黑白异同今日梦，枯荣宠辱百年身。","匡庐且纵陶潜酒，嬴得酡颜倚雪筠。"]},{"t":"西樵碧玉洞与诸子卜筑","f":"七言律诗","c":["谁信匡庐千尺练，曾移一半到西樵。","多年梦断黄岩路，此日寒生碧玉条。","远眺宝峰云影乱，近开灵鹫雨花飘。","可怜十八多佳士，筑得沿溪度石桥。"]},{"t":"庚寅二月雷峰即事","f":"七言律诗","c":["野寺疏钟接晚笳，蓟门残雪岭南花。","十年征战江云断，二月风烟山日斜。","古洞暮猿凄绝岸，荒原明月照谁家。","越王台上西风急，夜夜哀魂到海涯。"]},{"t":"次韵答侯若孩太傅二首 其一","f":"七言律诗","c":["海阔天空鸟不藏，孤城日暮怯微霜。","烽烟暗锁千门柳，羽檄分驰万里骧。","戎马十年肠亦冷，竹床二月梦先凉。","一般桃李春开尽，今古云山漫度量。"]},{"t":"次韵答侯若孩太傅二首 其二","f":"七言律诗","c":["野寺孤村泣断燐，半生魂梦若为真。","可怜按剑看投夜，始信寒岩独有春。","沐雨栉风多载恨，锄云耕月一身贫。","劳生扰扰同今昔，更莫长歌恸鬼神。"]},{"t":"怀王园长","f":"七言律诗","c":["四望重围鸟鹊愁，何人乘月独登楼。","海门一夜寒沙起，香水三春野服游。","古寺黄鹂啼欲暮，严城画角吹成秋。","河山万里应同恨，雪竹霜筠此日投。"]},{"t":"雷峰夜雨","f":"七言律诗","c":["细雨轻寒梦不成，萧然一榻自生平。","严城春夜近无梦，野寺云溪渐有声。","林外不妨花落尽，篱边犹爱笋初生。","江山此夕同何夕，惭愧幽人空复情。"]},{"t":"春晴望诃林诸衲","f":"七言律诗","c":["竹院春深亦乍晴，青山历历水盈盈。","白云草木连沙漠，玄菟旌旗拥穗城。","人在重围风雨暗，鸟啼高树雾烟轻。","从来识得荣枯理，不谓离群感独生。"]},{"t":"雷峰三月三首 其一","f":"七言律诗","c":["浩劫江山足战场，白云归处是家乡。","一帘夜雨浇残梦，百啭流莺过短墙。","春色到门山犬睡，淡烟遮岸海鸥忙。","乾坤有地藏痴拙，古木森森待日长。"]},{"t":"雷峰三月三首 其二","f":"七言律诗","c":["迟迟春日醉松门，生趣翻从世外存。","七十老翁初入寺，八年慈衲望孤村。","风低弱柳拖烟色，雨过新潮长石痕。","一上峰头占海气，越王台畔黑云屯。"]},{"t":"雷峰三月三首 其三","f":"七言律诗","c":["清簟疏帘镇日眠，百年多病且随缘。","雁翎去尽潭无影，燕子归来春可怜。","淡淡野烟孤屿暝，重重青霭远山连。","萧条人事逢寒食，犹听悲笳入暮天。"]},{"t":"秋日怀出山诸衲","f":"七言律诗","c":["疏林斜日照纷纷，断岸长亭入暮云。","野寺无人扫败叶，寒江有客阻妖氛。","月明桥北等闲过，雁叫霜天何处闻。","离乱不堪期别后，青山谁与问孤坟。"]},{"t":"秋月","f":"七言律诗","c":["光临江汉九垓宽，百尺峰头万木寒。","到底龙潭清碧碧，排空雁字白团团。","此心已许先秋素，睹影何劳后夜看。","独倚长松发深省，一声横笛五更残。"]},{"t":"喜光半入山","f":"七言律诗","c":["萧条瓢笠出严城，破寺相寻物外情。","笑我溪流黄叶乱，赚谁谷口白云轻。","十年有梦山何在，深树无人雁过声。","莫是秋原戎马急，却教白发闭门生。"]},{"t":"九日雷峰登高","f":"七言律诗","c":["万方多难此登台，今古兴亡尽客杯。","北郭白梨何地落，东篱黄菊满园开。","人归野渡秋原晚，日入长江霜气来。","一领衲衣寒不到，百年猿狖为谁哀。"]},{"t":"十日再登峰顶","f":"七言律诗","c":["珍重茱萸露一杯，与君今日更登台。","秋光未尽看如此，少长相携笑几回。","林木亦同人事改，江山不共雁声哀。","休心阅世还怜我，潦倒长松薄暮堆。"]},{"t":"十一日三登峰顶","f":"七言律诗","c":["何时何地独支藤，三上峰头尚有僧。","风起烟销江练碧，云寒霜重石床冰。","平原返犊笛声远，古木留人月色增。","万载清秋应共此，柴门深锁佛前灯。"]},{"t":"秋尽","f":"七言律诗","c":["海门风急浪千寻，万里山河老衲心。","流水过桥红日落，古榕低岸白云阴。","相看独我知秋尽，徙倚同谁到夜深。","搔首碧天无限意，石寒林静雁声沉。"]},{"t":"答李山农","f":"七言律诗","c":["寂寂云溪但有名，似应珍重过桥声。","谁怜雪竹题诗处，殊愧金山赠衲情。","远岳渐无青草色，近潮犹听白鸥鸣。","年来旦夕成今古，何日迟君石上盟。"]},{"t":"遣怀","f":"七言律诗","c":["身前身后路漫漫，满目云山梦里看。","零露不凋枫叶尽，哀鸿到处菊花残。","田横壮士何年泪，炀帝歌姬旧日欢。","惟有老僧与孤客，夜深常觉月明寒。"]},{"t":"忆匡山诸衲","f":"七言律诗","c":["自从瓢笠辞匡岳，不觉蹉跎又十年。","岭海云寒僧渐老，金轮雪重月频圆。","几人守猎猿啼处，十里还山花信前。","遥忆暵阳初解冻，同谁岩下试新泉。"]},{"t":"庚寅除夕","f":"七言律诗","c":["一帘灯火坐残更，百岁曾无此夕情。","忍见新燐流大漠，不闻归客向孤城。","痴心且逐今宵尽，活计从他后日生。","收拾瓮头黄叶乱，悔教身世赚浮名。"]},{"t":"雷峰春事用明教韵","f":"七言律诗","c":["世事浮沉孰可攀，随缘只合老青山。","吾宗后死有人在，懒病馀生假我閒。","独坐焚香孤野兴，推窗览镜笑颓颜。","听潮暂过溪桥晚，一望春深云树间。"]},{"t":"识尽震六自皈随予十年相次而殁抚今思昔情不能胜诗以写之","f":"七言律诗","c":["独坐峰头泪欲频，十年风雨梦中人。","迢迢云汉何堪问，滚滚江流岂复亲。","烟没台空成异代，鸟啼花落又深春。","一从俯仰知多少，我亦悠悠信此身。"]},{"t":"辛卯除夕","f":"七言律诗","c":["青山迢递海门东，目断长年一夜中。","人在水云閒岁月，梦随梅柳入春风。","半龛灯火光无际，万里关河望欲穷。","去住独怜寒雁影，此心不系与谁同。"]},{"t":"壬辰元旦","f":"七言律诗","c":["山门瑞气入初年，龙象齐瞻古殿前。","曙色渐回春树影，云衣常带篆炉烟。","依微村岸行人少，寂寞川原归雁连。","举额但祈戎马息，林泉无事日安禅。"]},{"t":"初春","f":"七言律诗","c":["东风初拂月初弦，寂寞柴门送雁天。","梦断梅花空见叶，望深杨柳未成烟。","一声画角山城远，万里行人春树边。","珍重白云啼鸟处，几回惆怅绿萝前。"]},{"t":"正月十七日","f":"七言律诗","c":["此日干戈传海岸，一年忧乐问田间。","园林雨过春犹浅，里社灯残人尚閒。","鸟语忽闻山客去，钟声初歇暮潮还。","江城远近胡笳起，嫩绿重云早闭关。"]},{"t":"得止言旧冬书","f":"七言律诗","c":["何事音书报早春，长征三月限通津。","连天衰草八行泪，动地悲笳万里人。","楚水雪消帆影乱，吴山日莫柳条新。","归鸿欲寄不知处，绿树平沙杜宇频。"]},{"t":"送离欲足两广慈乞食东江兼柬陈康叔王园长","f":"七言律诗","c":["花落纷纷春正深，萧条瓢笠下孤岑。","同人且暂虚磐石，到处何妨共竹林。","重云细草山中路，岸柳沙禽江上心。","甘贽定知贫衲意，相投门巷莫沉吟。"]},{"t":"清明","f":"七言律诗","c":["清明山郭黯朝晖，去国离家长翠微。","青草冢边一鸟下，白杨堆里几人归。","寒烟万里迷春树，细雨遥天溅客衣。","试向越王城外望，流花桥上落花稀。"]},{"t":"袁特丘送澹归入山","f":"七言律诗","c":["破寺寻僧又五年，香花重见昔人贤。","壁间高韵迟投老，槽厂行人欲解禅。","谷口白云何处入，溪流黄叶旧时缘。","通玄顶上应无憾，满目河山只偶然。"]},{"t":"怀剩人弟沈阳","f":"七言律诗","c":["天涯别绪古今同，又见归鸿入远空。","七载滴残寒夜雨，九旬欲冷杜鹃风。","沙场牧散钟声外，岭海人疑夕照中。","南北更怜杨柳处，黄云青霭一无穷。"]},{"t":"送商丘伯侯若孩二首 其一","f":"七言律诗","c":["旅榇相依向故岑，十年逋客几沾襟。","江山并作终天恨，禾黍徒萦异世心。","淇水疏钟随晓骑，桐门斜日待秋林。","云峰尚有安瓢处，不学田横入海深。"]},{"t":"送商丘伯侯若孩二首 其二","f":"七言律诗","c":["迢遥万里怆孤臣，转战频年归几人。","衰草断垣无白发，辞家去国有青春。","荆山西望三川尽，淮海南浮四塞均。","自古帝州看垒垒，月明深夜忆閒身。"]},{"t":"中秋同诸子坐月","f":"七言律诗","c":["古殿苍茫对月明，青山独有老僧清。","风吹不散长天色，虫响暗连落叶声。","万里山河双眼净，三秋林壑几人情。","须眉共照寒溪水，何事悲欢却并生。"]},{"t":"送止言澹归先入匡山","f":"七言律诗","c":["曾忆紫霄峰上话，十年留滞海门东。","空山背日寒犹在，春草无人绿未穷。","覆瓮悔教黄叶去，移茅定在白云中。","撑持赖尔难兄弟，相送河桥念朔风。"]},{"t":"壬辰除夕","f":"七言律诗","c":["万里津梁归此夕，几人心事付初年。","初年犹是近村寺，此夕竟同寒戍天。","梦里云山应不改，客中岁月已徒然。","何堪更忆匡庐旧，暮梵晨钟古木边。"]},{"t":"癸巳元旦","f":"七言律诗","c":["渐老应怜海外身，一年寒热又随人。","分明昨夜春光早，却讶今朝曙气新。","草木知时先坼甲，杯盘献岁久非辛。","东风便送归鸿去，云影潮声亦自真。"]},{"t":"过北寮看采石病","f":"七言律诗","c":["东风袅袅柳初低，野寺萧萧莺乱啼。","幸不客来虚隐几，却逢僧病强扶藜。","潮连海岸鱼梁没，雨过春园笋蕨齐。","百岁定知酬一死，茅堂山日莫相暌。"]},{"t":"夏日与刘见颙王入闻阿字无方白庵须识诸子小坐山亭","f":"七言律诗","c":["古木森森直似春，茅檐土屋自为亲。","从来隐几几忘我，今日空山喜见人。","顿入钟声一觉里，悟将云影百年身。","相期更有千峰在，莫雨朝晞应未贫。"]},{"t":"袁特丘刘见颙何一字见过","f":"七言律诗","c":["缓步寻幽过草庐，霜清啼鸟宦情疏。","竹林閒就峰烟里，山径寒生秋雨初。","万里归心钟磬失，百年羁旅梦魂纡。","飘蓬莫作乱离事，但信吾生只自如。"]},{"t":"喜谢伯子司农入山","f":"七言律诗","c":["历落交游三十年，秋风相见海潮边。","频经祸乱君能老，暂阅穷愁诗亦传。","黄土终归当世士，绿萝深绕几生缘。","萧萧古木寒山静，胜事空知晚更怜。"]},{"t":"旋庵四十又一","f":"七言律诗","c":["月流桐叶清辉悄，风掩蓬关薄曙寒。","一度逢生秋水怯，四旬如昨镜花看。","心存遗泽伤年迈，手自栽松及露漙。","辛勤立雪成何事，深草堂前语默宽。"]},{"t":"初秋怀出山诸衲","f":"七言律诗","c":["瑟瑟西风动竹扉，关心寒色转霏微。","三间旧拟云中去，一钵新期海上归。","有时桥岸逢人立，何处江山无雁飞。","白首更怜千里梦，寒花霜叶石门违。"]},{"t":"秋夜有怀","f":"七言律诗","c":["梧桐叶坠碧天开，落落閒情秋夜回。","风送泉声出谷去，月将寒色近帘来。","右军池上钟初歇，扬子江头雁已哀。","瘴海别峰霜冷处，一时回首妙高台。"]},{"t":"与袁特丘","f":"七言律诗","c":["梧桐叶坠噪栖鸦，楚客逢僧话转赊。","云外峡桥犹有路，烟中霜树已无家。","远公林下风初动，王粲楼头日未斜。","信我定宽陶令酒，何年丹壑醉流霞。"]},{"t":"瓶花","f":"七言律诗","c":["寒花难得是深红，时见晴开霜叶中。","不与上林春斗艳，欲教篱落色知空。","西风似有微音入，秋雨谁将衰草同。","且向飘零频著眼，一瓶清冷自无穷。"]},{"t":"癸巳秋将之匡山寄别广州诸子","f":"七言律诗","c":["临岐不作别离情，望里烟霞足此生。","闻鹤已伤行路意，畏人犹讳买山名。","十年瘴海馀秋色，千里云帆入雁声。","寒夜紫霄深雪处，论交先寄石羊城。"]},{"t":"匡山怀剩人弟","f":"七言律诗","c":["归卧庐峰忆旧因，夜深谁共侍瓶巾。","千株松柏前朝树，万里关河羁旅人。","明月未残竹影寺，黄云长蔽雁门津。","艰难阅尽头先白，兄弟遥看泪欲频。"]},{"t":"礼金轮峰舍利塔","f":"七言律诗","c":["层崖叠嶂拥金轮，辛苦谁怜负铁人。","寺是右军开晋室，塔传竺土肇西秦。","云霞缥缈诸天俨，日月升沉百代新。","稽首长空馀涕泪，感恩徒有刹尘身。"]},{"t":"秋夕奉怀长庆老人","f":"七言律诗","c":["一别云山岁月虚，问安犹记朔风初。","曾为弟子恩非薄，仰事吾师愧有馀。","月上禅西幢影乱，灯明方丈履声徐。","金轮捧足何年事，泥首长空掩敝庐。"]},{"t":"九日悼梁同庵","f":"七言律诗","c":["吴山越水共茫茫，会尽因缘亦自伤。","半榻寒灯风雨旧，一帘秋色梦魂长。","故乡望断空千里，折柬开残但八行。","旷劫不忘师弟子，只今无奈菊花香。"]},{"t":"甲午四月八日再礼金轮峰舍利塔","f":"七言律诗","c":["二十年来话未圆，今朝重礼窣波前。","心悬海外烟霞幻，足履云中色相捐。","遍界不曾藏面目，一峰何处论中边。","此生定遂终焉愿，坐断群峦独晏然。"]},{"t":"送顿修真佛行乞兼怀岭南九江诸子","f":"七言律诗","c":["金井桥边风习习，玉渊潭上月娟娟。","十年残梦无寻处，一夕离歌尽惘然。","已许白云成我友，又随流水作人缘。","因君忽动无穷思，岭海豫江霜叶前。"]},{"t":"与即觉顿修话旧","f":"七言律诗","c":["二十年前古道存，瞿塘无路觅精魂。","此心欲向青山付，佳话空传流水喧。","众病渐侵何可久，情缘疏淡不堪论。","焚书直入乱云去，忍听人间说感恩。"]},{"t":"用韵酬阿字时阿字以结茅留江州","f":"七言律诗","c":["寂寞云中又一秋，忽惊柿叶满峰头。","九江澄汉堪闻雁，五老斜阳独上楼。","入郭应知泉石稳，投林殊叹道名浮。","买山谁作住山计，辛苦都忘在沃州。"]},{"t":"须识以端阳入岭订予九月还山霜露已降消息渺然病中多感纪之以诗","f":"七言律诗","c":["到海定知三夏尽，归山曾约北风初。","夜寒病骨应愁汝，秋杪长途每系予。","解语好教窗外鸟，忘怀只有案头书。","一杯芦菔何人进，坐候晨钟霜月馀。"]},{"t":"十月九日病起","f":"七言律诗","c":["白草纷披孤磴出，青乌啐啄败垣寒。","野人病起若初到，旧处经行作梦看。","乱叶拚将流水去，千峰忍见夕阳残。","庞眉石上知谁世，细雨斜风秖自叹。"]},{"t":"山中病起人境初涉而茅屋待结远人未归怅然兴怀书寄阿字","f":"七言律诗","c":["一生多病为人忙，百事违心徒自伤。","世乱有山容易住，道衰无侣不成藏。","白门僧去溪云断，雁翅书来海日长。","为报江州莫久滞，北风吹雪入茅堂。"]},{"t":"冬夜怀足两","f":"七言律诗","c":["萧条寒色掩山斋，夜静钟残影自埋。","念尔情穷尚孤寄，因人肠冷一兴怀。","狂吟海岸应无伴，共棹江云那有涯。","古道只今寥寂甚，不胜惆怅步庭阶。"]},{"t":"入博山舟次石港","f":"七言律诗","c":["舟行八百半长途，石港临村客况孤。","水落沙寒深夜火，天空雪白满江芦。","深山纡曲奔师命，杖履疏违愧我愚。","明日香台重泥首，慈云千匝护双趺。"]},{"t":"湓石滩夜泊与阿字顿修书怀","f":"七言律诗","c":["古木森森山鸟鸣，孤舟日暮不胜情。","多时沙际三人影，到处滩头一水声。","胸次欲横星汉外，须眉犹照晚霜清。","风尘赖有敝袍在，地角天涯莫寄名。"]},{"t":"奉侍长庆老人高泉晚步诗示随行诸衲","f":"七言律诗","c":["早春乘兴午风温，树里行人望远村。","回首忽惊新客邸，乱坡如出旧郊原。","巍然硕果吾师在，蔚尔新枝若辈存。","溪鸟一鸣山尽绿，百年此日竟谁论。"]},{"t":"雪五首 其一","f":"七言律诗","c":["半落层崖断壑中，静依云树望成空。","月疑浅影若堪似，梅逐馀香未许同。","不信马蹄能久白，独怜榾柮傍深红。","何人高卧峨嵋顶，满目寒光路欲穷。"]},{"t":"雪五首 其二","f":"七言律诗","c":["洁白何曾上独峰，只教岩麓绝人踪。","压斜茅殿万山悄，欲启柴门深夜从。","幸托青松堪自见，却嫌红燄愧为容。","禁寒或亦饶孤赏，聊许高人一寄筇。"]},{"t":"雪五首 其三","f":"七言律诗","c":["濛濛万象独凭陵，何物光芒积素凝。","面目冷然遗草泽，肝肠如见托崚嶒。","若为热处偏成水，不耐寒多竟作冰。","惟有野人茅舍稳，断桥孤屿一枝藤。"]},{"t":"雪五首 其四","f":"七言律诗","c":["一夜严威生大漠，万山如醉俨成降。","尚堪为白先投岳，未肯成冰但入江。","素练条条千树一，青眸皎皎几人双。","凄清莫作穷冬事，破衲蒙头早闭窗。"]},{"t":"雪五首 其五","f":"七言律诗","c":["霏霏如絮到茅茨，想见烟深草没时。","零泪似伤寒日落，投空匪畏北风吹。","四山昏翳愁青黛，一室冰棱笑白眉。","只恐暂晴樵路稳，无人更起剡溪思。"]},{"t":"送渐侍者归省","f":"七言律诗","c":["怅望湖州未敢归，故园杨柳欲依依。","忍看国破先离俗，但道亲存便返扉。","万里飘蓬双布屦，十年回首一僧衣。","悲欢话尽寒山在，残雪孤峰望晚晖。"]},{"t":"万年山居","f":"七言律诗","c":["夏日生涯易到秋，阴森松竹倚山楼。","怀高霄汉从风雨，倦倚匡床听鹁鸠。","三藏岂须归白马，五千何用觅青牛。","柴门寂寞烽烟外，不信人间有许由。"]},{"t":"四月雨中即事","f":"七言律诗","c":["风雨飘摇茅舍欹，日长寒灶午炊移。","山中乞士方离院，江上归帆已过时。","播谷预占今岁早，种瓜须记去年迟。","商量浩浩成何语，羞听黄莺啼短篱。"]},{"t":"送阿字之沈阳讯剩人弟","f":"七言律诗","c":["罗浮匡岳十年外，吴水燕山万里馀。","鸿雁影分沙碛暮，鹡鸰声急朔风初。","牧羝地识苏卿雪，洗马池深刺史庐。","海外干戈烟塞远，关心云树正踌躇。"]},{"t":"阿字临行口占示之","f":"七言律诗","c":["万里传持白纸书，往来无伴莫踌躇。","父翁消息全凭汝，兄弟天涯欲慰予。","云水不教沾一滴，衲衣珍重更无馀。","仙歌日待辽阳鹤，早晚溪桥认旧庐。"]},{"t":"初秋书怀","f":"七言律诗","c":["兀兀山堂意渐降，飘飘秋叶送寒窗。","三年游子传临粤，万里征人已渡江。","入北定瞻新帝阙，回南犹是旧蛮邦。","关门自此无防闭，夜夜胡笳到石幢。"]},{"t":"栖贤怀古","f":"七言律诗","c":["谷口白云何处入，堂前深草易生悲。","读书高仰名公迹，拭泪徒销浊世疑。","烟雨屡更殊未定，溪山长峙不堪思。","相看更莫论千古，他日兴怀正此时。"]},{"t":"丙申生日","f":"七言律诗","c":["穷年兀兀似憨痴，鸟道虚空举向谁。","伯玉知非先一腊，香林走作未移时。","寒溪石上吟何已，空谷人来未可知。","白日降心唯此道，千松岩月意迟迟。"]},{"t":"送来机奉母还岭南兼寄社中诸子","f":"七言律诗","c":["青青竹笋春船远，白白山云谷日舒。","我母畏寒归岭海，而师好静滞匡庐。","四依清苦为徇道，三业精勤胜读书。","珍重故园摇落后，十年杨柳梦魂馀。"]},{"t":"怀阿字","f":"七言律诗","c":["慈乌哑哑盼危枝，况复投荒万里疑。","想去欲知经夏处，望归空记出门时。","匡云影覆千山衲，边月寒生五老帷。","关塞极天戎马日，却忧吾道苦相思。"]},{"t":"怀足两","f":"七言律诗","c":["结茅相傍石梁东，一腊云烟心事同。","乞食随人过贡水，还山有约忆西风。","千家曙色投朝市，六月寒林坐晚钟。","老去渐哀吾道丧，蹉跎岁月别离中。"]},{"t":"怀吼万须识","f":"七言律诗","c":["匡庐深谷驻寒烟，谁共开池种白莲。","借饭有人从楚泽，寄囊无路到秋天。","独行市井见新月，徙倚茅堂听夜泉。","所叹道孤年运迈，梦魂犹系穆陵边。"]},{"t":"滕王阁","f":"七言律诗","c":["拨云倚棹度江津，戴笠登楼景倍新。","雨过西山人望越，风回南浦雁归秦。","背城画角孤烟晚，近水芦花隔岸春。","俯仰一回思帝子，碧霄无际浪无尘。"]},{"t":"滕王阁五首和足两韵 其一","f":"七言律诗","c":["早年瓢笠及登临，乱后栖迟遂至今。","怀古况逢新画栋，凭高因见旧苍岑。","歌钟几向人间换，词赋犹怜世外寻。","我亦卧游舒远瞩，长江孤照白云心。"]},{"t":"滕王阁五首和足两韵 其二","f":"七言律诗","c":["高楼雄镇坐春风，胜国洪图今古同。","戎马喜随歌舞散，文章愁逐玉鸾空。","江鱼云雁浮沉外，南贡西山日夜中。","俯仰共知游览意，临秋应信蓼花红。"]},{"t":"滕王阁五首和足两韵 其三","f":"七言律诗","c":["东南平望控通津，豪贵才华异代人。","楼阁只今全盛气，江山终古有馀春。","閒云自是当虚槛，极浦何辞长白蘋。","莫向登临重怀抱，杖头无地觅风尘。"]},{"t":"滕王阁五首和足两韵 其四","f":"七言律诗","c":["夜涛千里锦帆轻，错落嘉宾足盛名。","倚醉清风同此日，是谁豁眼得生平。","牢骚作赋词人泪，慷慨当筵壮士鸣。","满目河山成旷代，平观空有老僧情。"]},{"t":"滕王阁五首和足两韵 其五","f":"七言律诗","c":["高怀年少独登楼，纵是无家亦乍愁。","四望云山忘作客，一闻鸿雁暗惊秋。","芦花宿月沉沙渚，羌笛因风满鹭洲。","天地自来虚橐籥，不堪人事日悠悠。"]},{"t":"还岭南道中得阿字长安书","f":"七言律诗","c":["多病已拚匡岳去，因人复向海门归。","聚船南贡江桥在，布谷春畴山日违。","万里音书添旅思，三旬风雨想征衣。","驰驰未可酬风穴，白日红尘泥帝畿。"]},{"t":"初还雷峰示诸子","f":"七言律诗","c":["七贤远别成何事，三老重来信有因。","若与交臂新交臂，吾犹昔人非昔人。","老榕垂荫酬初地，弱柳沿溪似旧津。","再礼慈云深自省，肯教狼藉故园春。"]},{"t":"忆即觉","f":"七言律诗","c":["虎门水殿春灯迥，狮子楼台霜月残。","千里江山一路直，百年梅柳几回看。","却因多病伤吾耄，每到良宵念汝单。","案上毗尼须尽读，法庭秋晚摄僧难。"]},{"t":"寄怀阿侍者","f":"七言律诗","c":["三年才得一封书，梦里还山信屡虚。","病去随人归瘴海，怀深无计问江鱼。","而翁忧道长思汝，尼母怜儿每向予。","何事五旬心气尽，秋风凝眼倚山庐。"]},{"t":"六月书怀","f":"七言律诗","c":["在道平观习渐轻，空怜形影笑馀生。","肝肠于我终无易，意气逢人暂一更。","暇日且教销贝叶，高谈聊亦寄閒情。","杜多未必无知己，净护须眉入太清。"]},{"t":"荔支","f":"七言律诗","c":["海外灵株自古今，江南江北绝相寻。","浓阴难覆胭脂色，锦质谁怜冰雪心。","近水似拚形影托，为园聊寄姓名深。","畏寒岂是安乡国，白草狼烟情不禁。"]},{"t":"喜阿字归自沈阳","f":"七言律诗","c":["去从湓水趋辽左，归背幽燕入岭东。","三年云月何曾别，万里溪山自昔同。","踏雪但知陵寝在，逢人休道子卿穷。","生还已是吾门幸，休向关门怨朔风。"]},{"t":"送雪草还归宗兼寄栖贤诸子","f":"七言律诗","c":["怅望湖山头渐白，送君临别益凄其。","金轮夜月虚残照，珠海西风怯早吹。","帆指庾关云暗处，人归晋寺雪深时。","玉渊再会终无负，一语先传猿鹤知。"]},{"t":"广州三首 其一","f":"七言律诗","c":["陆贾清谈收百粤，衣冠旷代见忠良。","秩宗首义车先裂，文苑连营阵亦亡。","万古江山皆易主，一朝簪绂自从王。","何人搆斗纡传檄，阖国身歼筑怨长。"]},{"t":"广州三首 其二","f":"七言律诗","c":["粤秀山前鼓角哀，越王台畔草堆堆。","飞龙白日旌旗闪，独骥黄尘斥堠来。","王谢入为麾下客，贾商推出济川才。","十年巨室诛求尽，闾巷萧条乔木灾。"]},{"t":"广州三首 其三","f":"七言律诗","c":["万里悲笳朔气深，故园摇落倍沾襟。","登楼漫拟刘琨啸，出郭谁为梁甫吟。","普天丘墓无新旧，近海云山有古今。","去国岂须怜郑谷，徘徊鸥鸟是知音。"]},{"t":"怀栖贤二首 其一","f":"七言律诗","c":["卜隐匡山曾六年，玉渊金井坐流泉。","出头已讶盘空势，拭眼谁怜避世禅。","生客久拚青草里，孤踪犹滞白云边。","存亡去住知何定，怪石长松亦有缘。"]},{"t":"怀栖贤二首 其二","f":"七言律诗","c":["石人岩下草萋萋，洗马池边日渐西。","故山猿鹤梦中觉，千里风烟望里迷。","便拟梅花同雪早，难将海色共潮齐。","时危两负青门客，招隐迟回黄叶溪。"]},{"t":"梦栖贤","f":"七言律诗","c":["昨夜梦到栖贤谷，泉声鸟声相间鸣。","高楼欹侧云僧少，狭径支离山犬惊。","牛屋紧围藏芋种，姜田翻转下蔓菁。","地炉叹息归何日，隐隐闻呼大小名。"]},{"t":"寄栖贤","f":"七言律诗","c":["早年卜隐盟丹壑，反望匡庐作故山。","留滞海门非我意，暂随鸿雁寄书还。","新松不厌百千树，旧屋从教三五间。","谨护柴扉容客到，但妨豺虎莫偷閒。"]},{"t":"冬泉","f":"七言律诗","c":["冬日水枯穿地骨，泠泠涌出映眉泓。","十年咸海空愁热，一掬香流但有名。","可汲岂须伤井渫，真源那复待河清。","莫劳橹断更招隐，到处佳泉惬老情。"]},{"t":"与诸子探早梅","f":"七言律诗","c":["濒海轻烟古寺东，一枝初放竹林中。","寒香漫道当春异，疏影偏怜今夕同。","落落路傍疑过客，垂垂人外泣孤鸿。","相寻未必终寥寂，对此幽姿妒晚风。"]},{"t":"己亥冬至","f":"七言律诗","c":["岭外再逢长至日，烟袅风轻散缕愁。","岂无海市堪舒眼，不是匡庐莫上楼。","戎马乡关今日泪，溪山松菊百年秋。","管灰纹线人间世，衰变从教雪满头。"]},{"t":"赴龙溪樊郝诸公探梅之约三首 其一","f":"七言律诗","c":["海阔风高起远思，扁舟乘兴恰同期。","杜陵看去愁偏乱，裴迪相逢春已迟。","笑我衣单宁畏此，催人头白欲怜谁。","一冬深雪香炉仄，肯似黄村薄暮时。"]},{"t":"赴龙溪樊郝诸公探梅之约三首 其二","f":"七言律诗","c":["昔岁匡梅愁独赏，今年风物好盘桓。","地僻更逢豺虎远，僧閒兼有谢陶欢。","香浮玉盌人烟暖，色罥冰壶日影寒。","回首顿忘天地外，石梁金井欲漫漫。"]},{"t":"赴龙溪樊郝诸公探梅之约三首 其三","f":"七言律诗","c":["万山积雪驻寒烟，残月疏钟欲曙天。","曾忆抱襟开户坐，却疑馀梦到林眠。","疏斜且出黄花后，攀折徒怜青草先。","相对尽期深谷里，莫教人羡上皇前。"]},{"t":"龙溪诸子再约黄村观梅阻雨不果是夕林将军招游波罗","f":"七言律诗","c":["濛濛细雨暗新潮，路湿春泥冷灞桥。","岂为滴残香蕊薄，都缘寒滑马蹄骄。","黄村风雪昨堪望，浴日烟波晚更招。","暂随海鸟迟花信，乘兴还来未寂寥。"]},{"t":"波罗舟中呈林将军并同游徐梁诸公","f":"七言律诗","c":["飞鹢定觇波浪稳，浮杯遂作海门游。","旌旗射日摇鲛室，鼓角喧风落雁洲。","将军礼数能宽客，山叟疏狂欲狎鸥。","莲社相期尽刘许，岂如张翰漫乘流。"]},{"t":"南海神祠","f":"七言律诗","c":["祝融神庙千秋祀，圣代封题百粤名。","乔木逾深沧海色，巨涛难荡古今情。","厓门日月沉珠浦，南越风云俨穗城。","几历兴亡香火在，年年铜鼓撼潮鸣。"]},{"t":"浴日亭","f":"七言律诗","c":["薄汉祥云开紫气，一轮寒日涌沧溟。","阴霾洗荡孤阳起，乾德清明万汇醒。","曙色已澄新宇宙，夕晖犹映旧辰星。","海天上下观垂象，百代兴怀在勒铭。"]},{"t":"登西台李木洲故址","f":"七言律诗","c":["黄湾东望独悠悠，雁过西台悲昔游。","花草已埋吴藻丽，衣冠想见晋风流。","平林风震星辰动，大海潮来天地浮。","九原只在河山里，泪洒新亭未易收。"]},{"t":"登海光寺楼","f":"七言律诗","c":["万里波涛惊绝汉，高楼回首几人悲。","休将作赋拟王粲，错比行吟哀楚词。","寒日独悬沧海外，浮云欲变古今时。","登临自笑同年少，尘幻无心鸿雁知。"]},{"t":"诃林菩提树","f":"七言律诗","c":["古殿巍峨接穹苍，庭蟠嘉树自梁唐。","朝钟暮鼓风鸣叶，翥凤飞龙月上廊。","铁干婆娑撑法苑，霜枝峭劲拄禅堂。","袈裟重覆思壬午，俯仰乾坤垂荫长。"]},{"t":"海珠寺二首 其一","f":"七言律诗","c":["涛心涌出梵王宫，蜃气溟溟露瑞容。","四面波澜摇画壁，一城笳鼓杂晨钟。","海上乾坤成殿阁，檐前风雨吼蛟龙。","自从宋代开忠简，回首厓门烟雾重。"]},{"t":"海珠寺二首 其二","f":"七言律诗","c":["荡漾青莲见佛尊，千年钟梵至今存。","飘飘帆影来天汉，浩浩潮声撼寺门。","云连雉堞旌旗暗，水落鱼梁市舶喧。","沧海共深香树迹，渚烟沙雁自黄昏。"]},{"t":"挽瞿庵","f":"七言律诗","c":["三十年来意气真，芒鞋踏惼可怜春。","清风明月留佳句，衰柳斜阳想幻身。","衣钵只教归故里，风流终不见情人。","岭南自此无寻处，越水吴山孰问津。"]},{"t":"忆匡山旧居五首 其一","f":"七言律诗","c":["一回瘴海心难歇，两住匡庐计未成。","守院数人常入岭，开春随雁几归程。","溶溶石上新潭水，寂寂松间旧磬声。","庭下梅花经雪瘦，不堪重忆倚寒情。"]},{"t":"忆匡山旧居五首 其二","f":"七言律诗","c":["泉冻无声钟漏稀，玉渊松影佛灯微。","白分槛外千峰雪，红上炉边百衲衣。","海腊不寒梅落尽，山春两负雁空归。","共谁曾住栖贤者，此夕风光能几违。"]},{"t":"忆匡山旧居五首 其三","f":"七言律诗","c":["峡桥茅屋堪谁托，珠海禅房且自安。","山水多因青鬓误，风烟空向白头叹。","旧移方丈从蛛蝄，新植松杉作虎栏。","几载经营岩壑在，潺潺一路石门寒。"]},{"t":"忆匡山旧居五首 其四","f":"七言律诗","c":["叠叠山河天地间，晴空望尽雁洲寒。","潮声惯作泉声觉，海色长当山色看。","郑谷莫轻今世易，沃洲真见古人难。","垂垂五十又过二，千里云烟梦未安。"]},{"t":"忆匡山旧居五首 其五","f":"七言律诗","c":["蜃海蛮风吹短景，严城哀角动寒林。","人情已觉苍茫晚，世路还同漭沆深。","梦里松花应十亩，望中湖水欲千寻。","南来岂为稻粱计，渚雁沙鸥见远心。"]},{"t":"送渐监院还栖贤","f":"七言律诗","c":["匡庐曾悔别离去，相送潮头归思同。","残月渐随孤棹远，青山只在白云中。","为留高树邀巢鹤，想到清秋听夜鸿。","赖有杨岐芳躅在，肯教寥寂旧家风。"]},{"t":"哭千山剩人法弟三首 其一","f":"七言律诗","c":["鸰原北望雾云重，白草堆中古寺松。","万里谁教还马革，千山今复号熊峰。","死当边野非吾意，终误才名惜此宗。","椎拂纵横知负汝，白头吟些欲何从。"]},{"t":"哭千山剩人法弟三首 其二","f":"七言律诗","c":["乌玄鹄白尽乾坤，侠骨平心欲并论。","至性自应投绝域，深悲何必恨中原。","十年膻雪酬先泽，七刹幢铃答后昆。","觉范子卿终一死，空馀骸骨吊关门。"]},{"t":"哭千山剩人法弟三首 其三","f":"七言律诗","c":["断舌何年悟世亲，虚庭六月忆天人。","徘徊行处蛮烟旧，想像空山塞雪新。","匣里恩书缄碧血，碛中遗履拜黄尘。","临风俯仰惭孤调，愁对秋高白雁翷。"]},{"t":"九日雨","f":"七言律诗","c":["近海高秋蜃气侵，更愁寒雨苦登临。","河山不到一翁眼，松菊相怜百岁心。","把茗欲当陶令酒，闭门聊效杜陵吟。","青溪何事断肠处，独对流泉霜露深。"]},{"t":"悼具三","f":"七言律诗","c":["早年避乱投泉石，因病辞家渡海云。","白社尚存居士笔，青山添作苾刍坟。","泪泠松埠新霜露，梦绕萝龛旧见闻。","借汝再来吾已老，不堪孤雁唳斜曛。"]},{"t":"渐监寺再还雷峰","f":"七言律诗","c":["荔枝初熟披星去，梅树花开带雪还。","我久冥心同水月，君于何处访云山。","孤舟腊月回初地，破寺寒天盼老颜。","添汝三峰数点泪，增余五老一回叹。"]},{"t":"辛丑初春出海幢适同学从长庆来谈及剩人殊增存殁之感","f":"七言律诗","c":["会日愈惊离日远，怡山转见白云边。","干戈不限三千里，须鬓徒嗟十六年。","雁影久虚寒碛外，棣华重绽煖春前。","鸾溪立雪几人在，相对珠江只惘然。"]},{"t":"怀阿字掌孟崖州","f":"七言律诗","c":["绝塞驱驰经两夏，珠崖跋涉又当春。","鹡原多难空劳汝，茅屋深移更累人。","荡荡薰风车辙远，条条细柳草堂新。","兴怀岂尽伤离别，白拂微言清昼贫。"]},{"t":"上华首台","f":"七言律诗","c":["不到罗浮已十年，登台松柏望苍然。","幢幡曾绕一人后，堂构空惭七众先。","旧植菩提堪荫月，新移石磴尚闻泉。","峰头老少疑残梦，泪逐西风落枕边。"]},{"t":"冬日即事","f":"七言律诗","c":["日日扶筇望海涯，目前生计秖些些。","一泓潦隔平田阔，千树松排东岭斜。","山外不知何处岸，云中依旧野人家。","閒过木桥询老叟，今年丰稔少嘘嗟。"]},{"t":"忆三峡涧","f":"七言律诗","c":["买得青山千里外，愁来空复向谁论。","溪中叠石疑岩窦，桥下重峦锁洞门。","高松仰看行人小，远水平邀绕座喧。","最是数年金井侧，一杯招隐易黄昏。"]},{"t":"诸子邀游厓门诗以谢之","f":"七言律诗","c":["孤情不欲向厓门，兴废谁将世外论。","郁勃定知埋古殿，苍茫何处吊忠魂。","露濡荒冢青山冷，风撼洪溟白昼昏。","祚移时去无今昔，千古难忘是感恩。"]},{"t":"暇园留题","f":"七言律诗","c":["冈城几岁歌钟地，此日香花胜事新。","曾识主人池上水，再逢公子竹林春。","干戈过后悲存殁，岩壑当前孰幻真。","野鹤何心细择木，为怜松柏长荆榛。"]},{"t":"初夏得石鉴凌江报","f":"七言律诗","c":["两旬风雨到庾关，一纸音书达故山。","闻道干戈前路远，定随鸿雁早秋还。","三吴烟水十年梦，五老云峰几日閒。","怀抱自深明月里，清光无计夜钟残。"]},{"t":"闻石鉴四月十九日度岭计此时应到栖贤","f":"七言律诗","c":["扁舟一叶向湓城，此日云峰眼底明。","高树鹤疑新箬笠，隔桥人唤旧时名。","茅房五月谷风冷，松径三更溪月生。","兴洽顿忘千里外，怀深并起故山情。"]},{"t":"中秋大日庵丧次","f":"七言律诗","c":["凄然今夕是何夕，依旧去秋茕独身。","仰看忉利空无际，回望双林泪转新。","愁极却怜知己在，夜深偏忆故山真。","谁携拄杖从金井，曾见宾鸿到海濒。"]},{"t":"重阳前二日陈小安入雷峰遂有丹霞之约","f":"七言律诗","c":["异代何人许共寻，秋风回首几沾襟。","维摩且喜不曾病，惠远终惭未入林。","黄花莫问当年酒，白发难为后日心。","更欲订君同长老，天然觌面海云深。"]},{"t":"八闽陈季长西蜀喻赓三入山","f":"七言律诗","c":["海岛茅庵门半开，何人一棹趁秋来。","黄花满地惭无酒，青涕垂膺懒拨灰。","云里有家非剑阁，山中无梦俨南台。","相期未尽千秋业，回首西风松柏哀。"]},{"t":"秋夜怀顿修","f":"七言律诗","c":["高秋静院寒先至，孤月长涂影倍怜。","生死顿疑千里外，悲欢徒忆十年前。","相看容易成岐路，共阅艰难更远天。","岁月岂堪离别过，残荷衰柳几潸然。"]},{"t":"水仙花二首 其一","f":"七言律诗","c":["姑射仙人下彩虹，绿裳霓袖隐芳丛。","性从水石馀香腻，质合冰霜解色空。","寒夜无人应入月，晓窗孤影易乘风。","相看只有閒云鹤，玄赏都疑在镜中。"]},{"t":"水仙花二首 其二","f":"七言律诗","c":["濯濯幽姿写不成，一溪风雪晚来清。","北山弱蔓难为影，南国繁香愧得名。","无力倚空春意倦，有怀乘月缟衣轻。","探奇总作凌霜韵，别岛深云惜此情。"]},{"t":"夏日李晓湘司寇尹恒复中翰见过和晓湘作","f":"七言律诗","c":["遗老相携访僻居，水清山浅混樵渔。","投閒赖有霜筠寺，祇对难酬竺尚书。","密树池边聆好语，孤烟墟上送回车。","临门再订重来往，三伏林间风有馀。"]},{"t":"得顿修返匡山信","f":"七言律诗","c":["忧极忽传匡岳信，平安不敢问归程。","一腔热血此生毕，两地关心到死轻。","闻道自通先世论，感时当忆住山情。","荷花残落西风起，淅沥长疑户外声。"]},{"t":"秋日寄何紫屏宪副","f":"七言律诗","c":["瑟瑟西风潮汐边，香花谁结未生缘。","灵光不隔三千里，魂梦徒迂十二年。","金井珠江瓢笠异，鸡鸣凤翥剑书悬。","多君学易几无过，笑我浮生雪鬓颠。"]},{"t":"喜陈法楫过山堂","f":"七言律诗","c":["寂寂山堂戎马外，何人负笈入云林。","尝因乱世得高士，岂为忧贫生道心。","秋雨窗虚寒色渐，晚钟人定野情深。","身前身后茫茫里，珍重垂杨倒夕阴。"]},{"t":"戏柬姚六康","f":"七言律诗","c":["五旬待刬阶前草，选佛还教先选官。","但识人间原是幻，岂嫌山上笑弹冠。","旧时文社曾称长，此日祇园赖悉檀。","题壁未应忘雪竹，何年重过玉渊寒。"]},{"t":"酬彭进士羡门二首 其一","f":"七言律诗","c":["世间安有閒云鹤，君独名成恣远游。","野寺似曾题雪竹，木犀犹故放山楼。","岂当再过辞生客，却讶前因拟狎鸥。","且勒高文留贝叶，他年应记碧峰头。"]},{"t":"酬彭进士羡门二首 其二","f":"七言律诗","c":["衰柳寒花岁岁同，光荣憔悴共秋风。","欲知物理腾腾外，只在尘缘滚滚中。","千里合违成雅遘，一宵言笑总无穷。","含情更有凝眸处，别指庭前百日红。"]},{"t":"秋日警众","f":"七言律诗","c":["梧桐叶坠去年秋，电火难追镜里头。","可是聪明成底事，枉随闻见重夷犹。","百年身世看朝露，一代才华逐水沤。","幸自心知同此日，猛然提取莫悠悠。"]},{"t":"送石鉴覞西堂领众栖贤","f":"七言律诗","c":["忆别匡庐又七年，湖光山月待人圆。","栽松未了何生愿，插草遥看后日缘。","拄杖已传庾岭信，深山知有石头禅。","烟霞到老真成僻，为寄遐心峡涧边。"]},{"t":"送记汝典客随石西堂之栖贤","f":"七言律诗","c":["借汝篁溪一日别，酬予金井十年情。","怀高深谷饶云水，谊重连床老弟兄。","霜叶满山人外色，雪花投涧枕边声。","箭锋试向针芒柱，千里幢铃梦里生。"]},{"t":"晓湘李大司寇八十一初度","f":"七言律诗","c":["今古齐观劫外春，朱帘高捲彩筵新。","霜威尚见前朝老，雪鬓长看后代人。","黑白且图良友对，敲推嬴得野僧邻。","桃花流水从通塞，稳卧钟山松柏身。"]},{"t":"春日李司寇惠诗及粟却酬","f":"七言律诗","c":["风雨潇潇春正深，落花流水共谁吟。","青山不到人间眼，白首偏怜世外心。","饱读新词能永日，饥餐脱粟卧长林。","懒残未必无知己，怪石苍松岂自今。"]},{"t":"乙巳冬闻沙汰之令","f":"七言律诗","c":["山犬不惊松户旧，寒花犹绕竹篱新。","袈裟有诏从初服，云水无私归道人。","牛火漫煨馀涕在，鹤形还对一经贫。","瓮头黄叶须收拾，莫滥恩光误早春。"]},{"t":"陆未庵六十初度","f":"七言律诗","c":["久慕雄州贤太守，高堂长侍白头人。","从来恺悌多仁寿，始信廉明有老亲。","五岭薰风披永日，一河慈润汇通津。","山中野叟遥多祝，愿忆生前最胜因。"]},{"t":"尹恒复中翰遣公郎兼中持书入山峕沙汰宽旨赋此酬之","f":"七言律诗","c":["野老归山去不辞，谁持折柬寄相思。","遣儿未肯同裴老，开社还应愧远师。","近日林梢仍向化，避人茅屋岂终移。","物情累卵同今昔，珍重篁溪石上时。"]},{"t":"再示兼中","f":"七言律诗","c":["天语新传法运回，寒梅依旧雪中开。","云閒僧卧青山稳，林外人寻白社来。","空寂欲同真梦泡，豪华休作幻楼台。","吾门大有酬恩句，举向高堂进一杯。"]},{"t":"得晓湘李司寇见怀诗用韵奉酬","f":"七言律诗","c":["绝岛寒林自掩关，深居从不为人閒。","千株松柏清阴外，万叠山河落照间。","云欲收时空不碍，鹤曾栖处法仍还。","书劳太傅思应剧，会借遐心到药栏。"]},{"t":"丙午元日","f":"七言律诗","c":["炎洲孤屿阿兰若，腊转霜残又到春。","梅柳喜迎初岁景，幢铃长绕去年人。","光天宝炬随潮远，匝地祥云捧日新。","百尺倚空烟水阔，洪崖何处石磷磷。"]},{"t":"示程周量舍人","f":"七言律诗","c":["大道幸然同内外，随缘且现宰官身。","王臣付嘱非无意，居士传灯岂异人。","十里香花今日胜，一围宝带旧时因。","主宾机感何年事，珍重钟山雪竹春。"]},{"t":"寄廖昆湖太守","f":"七言律诗","c":["匡月湖烟尚未收，几人此日忆同游。","河山剩有霜筠色，云水飘馀桐树秋。","五马重嘶金井畔，三车还拟墨池头。","拭眼因缘今古合，一书先报李江州。"]},{"t":"丹霞诗十二首 其一 初入丹霞","f":"七言律诗","c":["壁立崔嵬透一关，不携楖栗跨千山。","空中风起石梁隐，足下云生鸟道顽。","长老峰高终古在，天然岩待此时还。","群峦尽在霜烟里，夜月横江万木寒。"]},{"t":"丹霞诗十二首 其二 法堂","f":"七言律诗","c":["紫玉屏临翠石栏，万山林立一峰寒。","琼楼金殿空中幻，宝几华巾云外安。","穷子衣珠终自得，仙人罗扇不须看。","一铺直接庾关上，香水潺潺到此间。"]},{"t":"丹霞诗十二首 其四 紫玉台","f":"七言律诗","c":["左控重关拱上台，擎空仙掌向阳开。","影分白日临深壑，玉断丹丘作露台。","绝巘流云当北障，乱风吹雨度南来。","石籀古篆何年事，暮转寒飙枫叶哀。"]},{"t":"丹霞诗十二首 其五 篻竹坡","f":"七言律诗","c":["碧巘崎岖长绿条，野人凭望晚萧萧。","拂崖停日倍秋露，积石临江生洞箫。","凤翅影连青嶂色，龙鳞吟动紫林飙。","山南帝子今何在，砂起雾来寒欲摇。"]},{"t":"丹霞诗十二首 其六 芳泉","f":"七言律诗","c":["何人凿石及寒泉，桐叶潾潾玉槛前。","出浪定占清净应，负缶翻为桔槔怜。","曹源一滴澄今古，渤海千沤竞后先。","吸尽西江无著处，云深还待拥轮贤。"]},{"t":"丹霞诗十二首 其七 晚步松岭","f":"七言律诗","c":["岁寒犹见一丛青，高托层崖覆石屏。","夜月不侵无草地，晓风频护独椽亭。","荫垂千仞连云栈，响答长江入海溟。","倚杖闻猿却回首，下方谁梦到林坰。"]},{"t":"丹霞诗十二首 其八 登海螺岩","f":"七言律诗","c":["重岩飞阁近天门，俯瞰群峰势独尊。","晚秀倚空徒自鉴，草玄无上与谁论。","心同云汉形俱外，目对星辰意不繁。","踏遍且归山尽处，妙高终日到黄昏。"]},{"t":"丹霞诗十二首 其九 龙王阁","f":"七言律诗","c":["龙王阁下有龙池，池在山头龙不知。","布水为云封洞壑，顺风吹雨到江湄。","出头天外星辰绕，举足南陲草木披。","遍界不曾藏听睹，六窗长蔽昼暝时。"]},{"t":"丹霞诗十二首 与诸衲绕海螺山脚二首 其十","f":"七言律诗","c":["奇山怪岫赴螺城，欲注南湖浸未成。","突屼洪崖插汉立，森罗列嶂拥云横。","火龙暗度千寻壑，丹凤高昂万里程。","拟挈乱崚归上界，先教人向别峰行。"]},{"t":"丹霞诗十二首 其十一","f":"七言律诗","c":["身在此山山不见，潜移一步大家看。","慈威倒正无人处，蜒蜿裒斜入画难。","倚树仰空飞瀑细，搴萝就石宿云寒。","自惭垂老逢真境，更绕千回兴未阑。"]},{"t":"丹霞诗十二首 其十二 过锦岩","f":"七言律诗","c":["峭绝云屏松径欹，大岩疏阔石离奇。","傍无宿地僧归少，门对西江日到迟。","瞻仰金容疑近古，指麾灵鹫定何时。","杖头举处无多路，叹息人间钟梵稀。"]},{"t":"朝阳岩寻故址","f":"七言律诗","c":["朝阳岩下访遗宫，树锁寒烟万壑中。","金像瓦穿残日照，僧房门掩败垣通。","落泉流漫厨灰冷，坠叶纵横溪路穷。","试看石床苔没处，阴晴疑有虎狼踪。"]},{"t":"丙午除夕","f":"七言律诗","c":["朔风吹雁落人间，塞北江南梦欲残。","万里溪山看腊尽，数峰松竹到春寒。","佛灯自照夕阳外，僧笠谁从鸟道宽。","一夜石泉流不住，晓钟依旧出云端。"]},{"t":"丁未元日与诸衲泛舟江上","f":"七言律诗","c":["梵王宫在碧峰头，初日迎春瑞气浮。","香散紫霞归洞壑，钟摇松响出江流。","欲看金阙参差影，共泛晴川汗漫舟。","回首画图丹嶂外，何人乘兴晚悠悠。"]},{"t":"元夕","f":"七言律诗","c":["山中岁月无新旧，抚景随人乐事仍。","泉落石声调玉管，月移云影暗春灯。","早鸟唤林千嶂绿，夜猿啼雨一江澄。","人间物序忧迟暮，只有閒情属老僧。"]},{"t":"春日登山门石阁","f":"七言律诗","c":["懒步峰头曾几日，凭高又见草芊芊。","画中山鸟啼无数，梦里春花开正妍。","上界窗临江岸远，下方人望石楼前。","风烟满目谁为主，已觉身随云树边。"]},{"t":"送澹归行化五羊","f":"七言律诗","c":["五年辛苦走山城，搆得名蓝惬老情。","画壁楼台笔下起，莲花宫阙舌头生。","看云只有三冬日，冒雪还登二月程。","春草自青潮到处，江流偏作送人声。"]},{"t":"寄海幢首座","f":"七言律诗","c":["髼松雪鬓满头斑，垂老于今始入山。","上岭人扶登绝顶，下坡杖倚到前关。","晚秀茆房还我住，龙王书阁待僧閒。","封题却忆舟中语，写去新诗一破颜。"]},{"t":"寄雷峰诸衲","f":"七言律诗","c":["白头遥望万峰低，小隐何人守故溪。","去国塞鸿先我见，入门春燕傍谁栖。","河桥日落渔舟近，海树烟深村路迷。","生事百年消一病，青山依旧白云齐。"]},{"t":"春雨","f":"七言律诗","c":["春山将雨云先布，雨隐云中闻石泉。","闭户却疑空劫住，开窗如对上皇前。","香烟欲共衣衫湿，茶气能令几席鲜。","众籁顿归暝坐里，万峰谁记一千年。"]},{"t":"子规","f":"七言律诗","c":["已知宫阙生芳草，犹抱愁心泣夕阳。","无那东风增惆怅，有时寒雨助凄凉。","声随流水涓涓远，血染残红黯黯伤。","莫向山斋悲旧苑，晓钟微月梦初长。"]},{"t":"对花","f":"七言律诗","c":["年年二月放新枝，挹露含烟似有期。","笑我冷来和月老，怜人热去妒风吹。","墙头一朵春能艳，涧底千丛夜不知。","閒把胆瓶移近处，莫教香透捲帘时。"]},{"t":"种桐","f":"七言律诗","c":["山居生计唯耕植，共道栽桐胜种田。","无税不惊鸡犬叫，有锄休仰子孙贤。","偷禾鼠往邻村去，薙草人閒镇日眠。","三岁便教花作实，满篷风送卖油船。"]},{"t":"南雄陆太守孝山书至却寄","f":"七言律诗","c":["书至始知游兴阻，迢迢空谷想遐音。","多时茎草荣丹壑，此日清风隔碧岑。","自笑身形难似鹤，空教松树俨成林。","水云上下生涯旧，墨绶何时拂石阴。"]},{"t":"赠陆亦樵","f":"七言律诗","c":["当年丹荔频相对，此日青山又到来。","居士持斋忘岁月，比丘行脚遍岩隈。","开怀泉石供图画，入眼云烟绝坋埃。","闭户默然同静者，一番临别重徘徊。"]},{"t":"悼离言","f":"七言律诗","c":["梦里犹惊久病身，老榕窗北已无人。","难留去影思曾住，想见新苔长旧痕。","生死岂惟千里隔，合离深恨一冬频。","道情尽日伤流水，谁向长江问古津。"]},{"t":"中秋前五日与诸衲宿片鳞岩","f":"七言律诗","c":["偶共寻凉过露台，追欢更上片鳞隈。","依岩挂屋千峰顶，绕壁横空一径开。","夜静钟声从地起，月寒秋色自天来。","休将此夕疑他夕，几转幽怀到劫灰。"]},{"t":"九日","f":"七言律诗","c":["年年此日在高山，更不登临但倚栏。","百岁定知黄菊在，一瓢且对白云寒。","雁辞玉塞空秋草，犬吠霜钟起夜坛。","底事暂随吟望处，风流不与夕阳残。"]},{"t":"栖贤石长老生日","f":"七言律诗","c":["老僧旧住溪桥上，却忆当时亦五旬。","潭影杖摇山日落，纸窗灯暗夜猿频。","门庭枯澹思先辈，田舍荒芜赖后人。","莫倚年华少提挈，寿昌七十钁头春。"]},{"t":"秋日阅陈全人梁同庵英卓今遗稿感而赋诗并示诸子","f":"七言律诗","c":["瑟瑟西风薄暮生，百年衰柳几回荣。","镜花久逐东流去，水月犹怜独夜明。","断柬故人空有泪，当时孤韵已多情。","道心不向吾门冷，珍重云山好弟兄。"]},{"t":"金公绚生日","f":"七言律诗","c":["繁华阅尽老王庭，炯炯双眸意气横。","感恩岂必曾相识，慕义殊惭暂近名。","盈户总为朱履客，遥山犹系白云情。","因君益我林泉兴，幸托长庚耀此生。"]},{"t":"萧孟昉生日","f":"七言律诗","c":["曾闻负铁铸金轮，觉海隆因属后人。","意躁天中香已旧，阇耶手里麨重新。","清水欲收丹壑网，梵音先咒毒龙驯。","胜缘久植遐龄祉，相见还期大冶春。"]},{"t":"六十一诗十四首 其一","f":"七言律诗","c":["一周甲子又从头，生事如环谁去留。","白发不知人厌老，青林空见叶为秋。","朔风吹雁来衡岳，寒月迟猿下石楼。","多少陵阳馀岁月，世间犹此忆沧洲。"]},{"t":"六十一诗十四首 其二","f":"七言律诗","c":["阅尽兴亡隐逾深，匡庐彭泽共浮沉。","空教黄鸟啼来日，谁向青山问昔心。","一夕寒花犹是古，万年流水始如今。","长松几岁劳相伴，识得侬渠薄曙襟。"]},{"t":"六十一诗十四首 其三","f":"七言律诗","c":["青山垒垒忘归路，白露皑皑湿客冠。","三代废兴犹欲问，一身前后不知寒。","老来方悔少年拙，病去难寻向日欢。","谁解预为衰暮计，石门携手共盘桓。"]},{"t":"六十一诗十四首 其四","f":"七言律诗","c":["久滞尘寰想洞天，归山不觉已三年。","人过六十有何事，峰住千重只是禅。","下界残阳云影里，上方初夜月明前。","闻道近多乘兴者，隔江应见剡川船。"]},{"t":"六十一诗十四首 其五","f":"七言律诗","c":["紫霞深处曙钟寒，风转袈裟罥石栏。","心逐夜猿声里憩，身随云侣腊前观。","高幢月落乌初觉，叠砌枝横露未乾。","此意静中看已老，一林松菊绕香坛。"]},{"t":"六十一诗十四首 其六","f":"七言律诗","c":["微霞薄照影漫漫，世上愁从落日攒。","閒倚石楼思往事，忽惊阳雁报新寒。","头颅久豁重添雪，杖屦犹存数绕坛。","不用更寻华表鹤，六旬人物已凋残。"]},{"t":"六十一诗十四首 其七","f":"七言律诗","c":["衰病自知来日少，偷閒人去卧时多。","目前秪有无忧得，身老其如此道何。","啄木鸟悬枫树上，摘茶僧向石梁过。","山中底事逢时节，叹息人间咏伐柯。"]},{"t":"六十一诗十四首 其八","f":"七言律诗","c":["渐老渐知吾道稳，更无馀梦到羲皇。","伊耆龙马昔全盛，阪涿熊罴今淼茫。","江雨未收山日出，夜钟才憩晓鸡忙。","韶光冉冉同流水，谁信松门活计长。"]},{"t":"六十一诗十四首 其九","f":"七言律诗","c":["年年见说人多往，岂有昨宵今再来。","犹向石坪低处望，不妨篱菊暂时开。","峰高引水当阶溅，日逼移槐隔槛栽。","青山得住何嫌老，返景初残月上台。"]},{"t":"六十一诗十四首 其十","f":"七言律诗","c":["久住匡庐无雪诗，去年二月苦吟时。","青山依旧人添老，白发无私天亦垂。","万顷冰田春尚早，一庭玉树夜何其。","石梁回首寒犹在，独立松檐却问谁。"]},{"t":"六十一诗十四首 其十一","f":"七言律诗","c":["海螺绝巘覆洪濛，老眼临高豁大空。","越水东流流不住，楚云西望望无穷。","风吹落叶知何处，月到寒宵只此中。","欲倚长天青碧碧，一声鸿雁隔千重。"]},{"t":"六十一诗十四首 其十二","f":"七言律诗","c":["居山只合种山田，岂为无心作俗缘。","人事强如千日日，世情薄似一年年。","道贫不欠他生债，身病长赊买药钱。","便采菊花当服食，颓龄无酒亦陶然。"]},{"t":"六十一诗十四首 其十三","f":"七言律诗","c":["手扶人背上丹梯，只是临高眼莫低。","老去尚能誇足力，兴来差不厌人携。","猿贪果熟连枝坠，鸟识僧归隔树啼。","暗数登山今四度，明年还拟搆岩栖。"]},{"t":"六十一诗十四首 其十四","f":"七言律诗","c":["万仞峰高独坐时，纸窗虚映满头丝。","古今不到眼前尽，云月从教人外移。","僧繇岂有图空手，荣叟嬴将入老诗。","自此更生千岁日，石床题遍定无疑。"]},{"t":"己虚庵主出先华首座下住琼南二十馀年与余生同甲子适当揽揆分奉舍利以福遐龄","f":"七言律诗","c":["罗浮古木不知年，移向琼南作话传。","厚荫偏宜炎热地，新枝重发冱寒天。","一周甲子伊谁主，十万程途后日缘。","化度未终吾与汝，灵珠分曜海潮边。"]},{"t":"戊申冬日属西堂石鉴代主长庆临别示此","f":"七言律诗","c":["十年未弛吾师担，三请深惭居士心。","多尔逆撑曹洞水，为余雄据大沩岑。","先宗断续宁论后，古道凌夷直赖今。","千里临风无别语，瓮头黄叶慎知音。"]},{"t":"石长老入闽已有别句临行再书扇头二首 其一","f":"七言律诗","c":["老大翻惊岁月频，那堪更作别离人。","三年寒暖初停梦，一夕云峰又隔春。","有意菊花成聚首，无情梅萼送行津。","风烟转盼分闽粤，锦水华山却认真。"]},{"t":"石长老入闽已有别句临行再书扇头二首 其二","f":"七言律诗","c":["一瓢峡涧冰霜重，千里云幢身世轻。","话月总教随刹土，临门犹悔出山情。","庾关古已多行客，乌石今仍对会城。","拄杖到时春已半，堂前不信草频生。"]},{"t":"寄林孔石","f":"七言律诗","c":["折柬殷勤又七年，肝肠重布菊花前。","却惭堂构乘承后，转见王臣嘱累先。","白社遥知宗炳意，青山分去远公禅。","临风更有无言句，他日相催一默然。"]},{"t":"曾公实过访","f":"七言律诗","c":["看君几岁箨皮冠，试问从来为选官。","念我故山肠欲断，因人岐路泪偷弹。","已成白发南洲暮，却忆青袍北邸寒。","莫怪童龄多慷慨，低垂犹自倚阑干。"]},{"t":"作金携牡丹回","f":"七言律诗","c":["倾国名花好自持，岂因零落慎相期。","竹笼驰马惭当日，雪棹逢僧寄一枝。","无意桃葩开始盛，有情丹壑恨来迟。","回首沉香亭上事，空令人忆暮春时。"]},{"t":"南雄陆太守同阖郡诸宰官招入华林","f":"七言律诗","c":["宰官招我下重关，楖栗横肩自去还。","爱听三车迟近院，曾先五马入深山。","风流况有宗雷并，云外偏宜皎贯閒。","愿见久忘朱户贵，麻衣高座鬓毛斑。"]},{"t":"建封滩寻灵树禅师旧址","f":"七言律诗","c":["青松高出建封寺，信棹滩头问古津。","旧址久成豪族冢，原田半入俗居人。","坡斜漫灭无行径，竹出参差多著尘。","五百方袍何处去，清溪水涸石磷磷。"]},{"t":"晚泊有感","f":"七言律诗","c":["布帆忽忆十年前，独树临江晚泊船。","戍角凄凉林外垒，渔灯黯淡渡头烟。","行尘扰扰人非昔，流水涓涓夜稳眠。","世事总如寒浦雁，飞来飞去暮云天。"]},{"t":"初入华林","f":"七言律诗","c":["近郭名蓝半壑开，华簪方服对高台。","云生几席僧催至，香满山厨客带来。","万里风烟霜竹断，三生魂梦午钟催。","相看未易论畴昔，且共遐心倒茗杯。"]},{"t":"赠阮若生","f":"七言律诗","c":["阅遍兴亡一布袍，早传名字到蓬蒿。","心同野鹤青冥近，身傍云庵白社劳。","卖药韩康疑市隐，栽松道者爱年高。","投閒岂为田园乐，止酒寻僧不姓陶。"]},{"t":"华林送李别驾廷标入觐","f":"七言律诗","c":["折柬寻僧几日情，俄闻万里逼王程。","一官久系皇恩重，三径从抛乐事轻。","梅萼渐看帆影远，杏花回首马蹄横。","遥知丹石薰风下，野老欣传返旆声。"]},{"t":"龙护园","f":"七言律诗","c":["太守新修别院深，遥分祇树落城阴。","官閒喜傍烟霞迹，僧僻惭牵缨冕心。","定化弦歌成佛国，已将钟梵入名林。","溪坛曾见闻樨者，空谷宁愁金玉音。"]},{"t":"还山留别陆太守","f":"七言律诗","c":["真成一日堪千载，太守高怀岂偶然。","揆迹直深尘劫外，论心须忆古皇前。","香花已见当年事，云水还期后日禅。","归棹未应愁此别，石门遥望夕阳边。"]},{"t":"归舟晚望","f":"七言律诗","c":["久住青山性未驯，出山何似入山频。","猿声岂为催归客，江色长疑送去人。","沙上白鸥寒照水，祠前青竹静临津。","石门深处夕阳闭，昔指云间是隐沦。"]},{"t":"岁暮","f":"七言律诗","c":["就隐丹峰几腊残，昨随人去四旬还。","夕寒鹤自归松顶，月落云仍到竹关。","万里客乡知岁尽，一天风雨待春閒。","孤怀淼淼谁堪共，独拄桄榔吟上山。"]},{"t":"寄酬南康别驾沈赤岩","f":"七言律诗","c":["佐郡名豪隔蠡湖，官斋如水对青菰。","携觞自有陶彭泽，看竹应寻舜老夫。","深谢朔风驰雁翅，空惭明月寄香炉。","多才会见劳丹诏，还许山人怀刺无。"]},{"t":"程大匡仪部入山却赠","f":"七言律诗","c":["异代名贤去住间，偶携书笈扣柴关。","永和风味难为客，彭泽田园岂易閒。","息影且依春树暖，登高莫厌石头顽。","凭君举目看尘世，更有何缘好似山。"]},{"t":"春怀","f":"七言律诗","c":["坐对青山一望宽，山山如黛镜中看。","马嘶芳草青烟澹，燕绕空梁白昼寒。","微雨闭门春寂寂，落花沉水夜漫漫。","信知世虑由来薄，亦有幽情时倚栏。"]},{"t":"春日寄雷峰社中","f":"七言律诗","c":["庾关残腊惜归时，门掩春风日渐迟。","衰鬓自怜山兴洽，閒情惟有水边知。","浅深绿树藏茅屋，开落红花荫竹篱。","不分雨过云又起，望中难见向南枝。"]},{"t":"赵孝廉苏生归自江陵与同榜潘广文伊蔚过访","f":"七言律诗","c":["同年并辔访幽居，出处支离话有馀。","千里远归淮海梦，一官犹钓锦江鱼。","难将身世论今日，且向云山问草庐。","松下石床眠不尽，残冰衰柳燕来初。"]},{"t":"送沈融谷回浙秋试","f":"七言律诗","c":["青云直上乡关路，寄别题诗惜柳条。","郡幕已深庭树影，秋江还拟桂香飘。","三春去马迟征雁，九夏归人独听潮。","才子声名应此日，十年回首话非遥。"]},{"t":"春日即事","f":"七言律诗","c":["朦胧春色石楼前，落尽桃花听杜鹃。","水涨锦溪知夜雨，月沉丹嶂起朝烟。","山中各自成昏昼，世上曾无异食眠。","芳草王孙归未得，几人于此独潸然。"]},{"t":"芳草","f":"七言律诗","c":["何处东风送大堤，王孙去后独萋萋。","邮亭日暮烟方合，废苑花飞叶未齐。","乳鹿眠云春更暖，芳筵坐客晚多携。","无边胜事山川上，说向侯门醉似泥。"]},{"t":"忆崇祯丁丑寓鹫峰寺上元日早朝","f":"七言律诗","c":["梵王春殿曙钟催，却望金轮紫禁来。","万炬光中轩骑入，千官头上午门开。","遥瞻凤阙仙班后，始拜龙墀鹓从回。","白云残梦思周穆，纵有瑶池亦劫灰。"]},{"t":"忆与陈全人下第南归舟次金陵宿报恩塔院","f":"七言律诗","c":["六朝王气盛当时，水满秦淮绕帝畿。","帆落旧都江色暮，月摇金塔梵钟微。","壮心淡泊听莲漏，客路萧条恋禁围。","回首山阳成往事，不禁禾黍叹依依。"]},{"t":"忆过西湖与余中丞集生汎舟","f":"七言律诗","c":["苏堤衰柳雁初飞，短袖峨冠静对谁。","万古湖山犹此日，六桥风雨忆当时。","故人梦断西州渺，病鹤天遥松月移。","记得少年曾有约，一瓢长乞浙江湄。"]},{"t":"金陵怀古","f":"七言律诗","c":["建业楼台烟树微，苍茫天堑雁斜飞。","大江南北谁能限，西浦神仙愿已违。","昔日顾荣轻白羽，当时王道重乌衣。","方山日夜长如此，淮上千年古帝畿。"]},{"t":"寄姚石埭六康","f":"七言律诗","c":["北望金城思渺然，寒蒲新柳夕阳天。","遥山雁去三千里，独树莺啼四五年。","官阁联诗知政暇，宦情如水记生前。","故园更有樨香在，莫学渊明醉菊边。"]},{"t":"桐子山","f":"七言律诗","c":["桐山早岁已知名，今日亲从鸟道行。","一缕云根逾岭路，半空人语隔溪声。","新栽绿树埋烟重，旧引红泉落涧清。","此去数程江岸近，不教人作武陵行。"]},{"t":"春日再过泐山","f":"七言律诗","c":["西浦春畦生野烟，北山疏雨过游船。","一条旧路依层砌，无数新阴异去年。","近接紫霞回峻岭，远临芳树带长川。","高台日暮天风起，水逝云寒思渺然。"]},{"t":"黄徵君过访","f":"七言律诗","c":["江楚名儒不姓庞，云山次第到湘江。","石头路滑苍苔遍，螺髻春深烟树降。","看竹最宜风满座，闻花应爱鸟窥窗。","灰心更有诗囊在，荒院留题韵自将。"]},{"t":"上巳寄南康太守廖昆湖","f":"七言律诗","c":["泬寥春色近何如，花落寒梢影自疏。","藉草远过江浦岸，烧畬还课北山锄。","波光几岁摇高岭，云气从朝覆敝庐。","此日独怀彭蠡守，袖中存有故人书。"]},{"t":"春日凌世作陈无隐凌稚圭叶御题陪黄徵君入山","f":"七言律诗","c":["数数离家谒上方，此回陪客趁春光。","蹋穷芳径草新绿，啼遍杨枝莺旧黄。","出郭未除寒食火，入山偏近野棠香。","残红黯黯都教尽，世上浮生几著忙。"]},{"t":"寒食","f":"七言律诗","c":["年来底事觉荒唐，无数春怀掩上方。","万灶寒烟逢禁火，千条弱柳送残阳。","岸高临水苍波远，日永看云紫陌长。","处处古埏封白纸，阴森松柏去人忙。"]},{"t":"清明","f":"七言律诗","c":["近臣赐火何年事，浅绿深红过此生。","已看细雨连三月，却听啼鹃正五更。","侯门尽醉当花落，马背馀醒拂柳轻。","抚景不堪愁蝶梦，因人空切住山情。"]},{"t":"春望","f":"七言律诗","c":["多情每笑无酬处，独上高楼望远空。","细雨自零春岸迥，斜风偏送柳条东。","百年暗逐江篱暮，万事销归山槿红。","寥落莫愁头白尽，死生宁不与人同。"]},{"t":"悼言全监寺华首","f":"七言律诗","c":["离家已是五年馀，总向残山守旧庐。","离乱寺田空有税，往来羸稚不成锄。","出门自负干寒暑，掩室贫炊数麦蔬。","肺病两冬犹未释，伯仁由我痛何如。"]},{"t":"寿刘焕之副戎","f":"七言律诗","c":["真隐何殊水石间，王门深远意相关。","入世但尊程氏学，论心唯许远公閒。","常供军储先输国，时舍僧田为近山。","最喜年华才不惑，伫看儒术遍尘寰。"]},{"t":"楚黄赵处士入山见访","f":"七言律诗","c":["楚客春游望石门，一肩风雨冒寒原。","因寻茂宰知山近，却枉高轩到日昏。","野鸟避人过远树，潭龙喷沫见深源。","凭高莫指前溪路，苦竹林边有夜猿。"]},{"t":"寄足两侍者","f":"七言律诗","c":["旧院何人潮汐中，十年立雪恨西东。","频行方丈莓苔破，久病床头药罐空。","门对孤松分鹤影，窗临野竹恼春风。","老僧近亦多愁疾，独掩高峰闻夜钟。"]},{"t":"落叶","f":"七言律诗","c":["一叶辞枝影便单，烟深沙浅乱离难。","因风恨不寒烧尽，踏月空怜屐齿乾。","却忆题红疑有字，若逢为笠也须冠。","纷纷树上残阳里，正好和云作画看。"]},{"t":"落花","f":"七言律诗","c":["辞枝片片逐东风，不信繁华过眼空。","山月自寒今夜梦，碧云愁锁旧时丛。","遍寻踪迹徒劳蝶，狂逐馨香尚有蜂。","但识初终无二致，依然满树紫兼红。"]},{"t":"姚大参亦若儗僦居太平舟次相见率尔有赠","f":"七言律诗","c":["曾因避世入丹丘，北望衡阳几度秋。","乱后将家依幕府，归途访旧过汀洲。","谷口残莺啼柳暗，石门斜日映江流。","看云休逐三川远，却指乡关在豫州。"]},{"t":"送澹西堂之海幢兼寄阿首座二首 其一","f":"七言律诗","c":["薰风又送下江船，共许青山各一天。","柳色渐深人去后，莺声偏逐马行前。","半旬云寺倾长日，几夕灯花话隔年。","若问老僧春梦足，多时曾绕木兰边。"]},{"t":"送澹西堂之海幢兼寄阿首座二首 其二","f":"七言律诗","c":["不信遥山更有愁，苍茫烟树越王州。","见携孤策辞林鸟，知共何人上海楼。","潮带残阳归客艇，月随零露下蘋洲。","萧萧朝暮孤峰外，极目长天空白头。"]},{"t":"诏复滨海迁民故业三首 其一","f":"七言律诗","c":["市上惊传鬻海鱼，几年禁令忽闻疏。","流民多恐无归日，望里翻愁空故墟。","城犬随人寻旧路，野鸦迁树避新锄。","不堪悲处还成喜，童稚编篱且种蔬。"]},{"t":"诏复滨海迁民故业三首 其二","f":"七言律诗","c":["官府唯闻复故基，荒凉田舍欲何为。","馀生便是承恩日，后死弥深设虑时。","已分辞根同败叶，却因回律惜残枝。","夜塘寂寂春虫切，雨过疏篱带湿炊。"]},{"t":"诏复滨海迁民故业三首 其三","f":"七言律诗","c":["死生谁复问身名，尚在屏幪怆倍生。","妻子流离今已过，家园存没眼前成。","辞巢社燕先秋恨，泪血啼鹃薄暮情。","天道好还凭未得，人心将作感恩平。"]},{"t":"酬阿首座并寄澹西堂二首 其一","f":"七言律诗","c":["渡头长系过江船，树里寻源六月天。","海燕渐辞山槿后，塞鸿应见露槐前。","道情断续同流水，世事飘飖似去年。","自是吾门生计在，可堪惆怅白云边。"]},{"t":"酬阿首座并寄澹西堂二首 其二","f":"七言律诗","c":["抱璞生愁刖亦愁，脚跟无线系皇州。","若教此意如秋叶，不惹閒心上庾楼。","临水已沉潭底影，看云犹忆雁回洲。","苦吟岂为誇同调，一曲清歌笑白头。"]},{"t":"李别驾入觐回署适当诞日作诗寄之","f":"七言律诗","c":["万里朝天归早秋，西风昨夜报山楼。","去时忆别愁青黛，回日逢生尚黑头。","杨柳旧烟仍系马，梧桐新月照牵牛。","王程鞅掌年方壮，共喜恩荣发艳讴。"]},{"t":"七夕骤雨","f":"七言律诗","c":["西风初动暮山寒，万树浓阴绿未残。","星汉自高虚夜色，鹊桥无路暗云端。","人间骤雨应遗恨，天上新凉欲尽欢。","景候不殊人事别，新诗携向佛灯看。"]},{"t":"余生平摘过颇切辄有面从之感赋以自责","f":"七言律诗","c":["我亦年来厌此心，无人终日对高岑。","尽云有石能攻玉，谁信真鍮不博金。","晚倚西风寒似昔，晓临秋水淡如今。","一林霜气从空下，单复衣衫各自任。"]},{"t":"初秋","f":"七言律诗","c":["山院炎蒸苦莫何，西风忽向竹间过。","梧桐新月难成寐，杨柳残烟好放歌。","足疾偏怜凭药力，心閒每恐入诗魔。","寒蝉远树声逾切，始信深怀冷处多。"]},{"t":"唐朴非有北上便道入山之订久候不至","f":"七言律诗","c":["遥望锦帆过急湍，短章裁就寄长安。","已开山阁延朱履，却讶香尘隔玉鞍。","秋草定沾朝露湿，黄花空送夕阳残。","八方辐辏春风暖，谁信柴门雪夜寒。"]},{"t":"送唐朴非北上兼寄程民部周量二首 其一","f":"七言律诗","c":["长安有路路茫茫，目送征帆雁影长。","九万程途新羽翼，一朝邦计旧文章。","杏花首擢谁先达，金马联翩接后行。","应笑老翁头白尽，怀人犹自忆春芳。"]},{"t":"送唐朴非北上兼寄程民部周量二首 其二","f":"七言律诗","c":["凤池几岁丝纶贵，空谷频年金玉遥。","坐断寒云归紫壑，望穷明月上青霄。","公车过处猿偏切，庙算閒时雪未消。","欲寄宋曹逢解袂，离歌一曲起渔樵。"]},{"t":"送广慈侍者归隐庐山","f":"七言律诗","c":["一笠风烟望故山，石梁流水尚潺潺。","投林输尔鞭先著，待月愁予身未閒。","远接湖光高筑室，近穿松径自为关。","听猿更有幽怀在，分付溪云留半间。"]},{"t":"酬卢处士黼子","f":"七言律诗","c":["西樵居士在端州，远寄丹山最上头。","二十年虚宗炳社，一千里忆剡川舟。","云端话断星岩夜，锦水人归碧玉秋。","世故儒生谁独念，黄埃满市莫淹留。"]},{"t":"庚戌元旦书怀","f":"七言律诗","c":["出世已经三十年，红帔白发拜金仙。","身閒在世岂容易，梦觉随人只倒颠。","夜雪晓风思暖盌，松涛溪管羡高眠。","未来人事应难料，又报钟声上法筵。"]},{"t":"送姜山侍者行乞江南兼寄匡山诸衲","f":"七言律诗","c":["一钵江南万户春，入廛须是住山人。","朱门岂有嫌支遁，白社何妨狎许询。","易见乡关他日梦，难辞师友此时身。","秋风返棹经庐岳，为嘱同门且耐贫。"]},{"t":"寄姚六康","f":"七言律诗","c":["因僧乞食下彭湖，试问陶公忆我无。","去岁绿杨仍在目，今朝黄鸟已频呼。","晴烟客棹诗能苦，春雨官斋酒再沽。","独有白头人怅望，深山何处望双凫。"]},{"t":"寄黄师古","f":"七言律诗","c":["柳条初发送寒原，更有怀人欲并论。","千里布帆愁锦水，一池荷叶忆篁村。","马卿有意先为客，杯渡无心自到门。","珍重封题随雁去，无穷春色趁王孙。"]},{"t":"闻石长老归自闽中却寄此诗兼讯廖太守昆湖","f":"七言律诗","c":["别去闽城未一年，秋风忽报返湖船。","正疑人重烟霞僻，却似天留水石缘。","云里峡桥仍古路，雪中金井迸新泉。","坐逢谢守为予道，近欲移茆五老边。"]},{"t":"赠与安竟书记","f":"七言律诗","c":["脱却黄冠著锦斓，还丹误服得童颜。","真人未必居蓬岛，药草终须到雪山。","剩有君臣绍洞上，更无文字到人间。","才华洗尽看南斗，莫学黄龙在泐潭。"]},{"t":"送作金行乞虔州","f":"七言律诗","c":["生涯且向涂中去，寒铎还从山上来。","布袋展开惭白汗，芒鞋踏倒笑青苔。","冲将苦雾行荒草，又带斜阳归雾台。","无限风流犹未厌，满船珠玉待人回。"]},{"t":"初春与诸衲游黄沙坑","f":"七言律诗","c":["春游老觉步行难，弟子肩舆过远山。","石壁旧坡须数转，野田新屋只三间。","犊窥僧背常偷菜，犬逐人行先到关。","自是大家新岁聚，一年唯有此时閒。"]},{"t":"二书记种桃于法堂方丈之间新花烂熳余偶过玩竟书记索诗示以此作","f":"七言律诗","c":["移得桃花近竹扉，一般景物昔人非。","白猿夜夜千峰切，红雨年年二月飞。","金阁俨临西子面，玉容长映老僧衣。","千株何似此株好，不及灵云未见时。"]},{"t":"寒夜偶成","f":"七言律诗","c":["老病况兼春夜寒，山堂寂寂佛灯残。","非无厚絮嫌衣重，却有多人任意难。","心憩久安身世幻，愿深不作有无观。","摇摇壁上交珠网，法界原来在此间。"]},{"t":"送澹西堂下广州并示阿首座","f":"七言律诗","c":["剩水残山又到春，龙钟双袖不知贫。","久膺道法惭无状，岂外形骸欲认真。","杨柳含烟初送暖，山花照日见行尘。","相逢但道予犹健，潦倒林泉信此身。"]},{"t":"再送姜山行乞江南","f":"七言律诗","c":["骊歌唱罢不胜悲，春水梨花二月时。","细雨闭门寒坐怯，暖风吹袖独行迟。","长干日落逢归客，湓浦烟销见废祠。","极目川原千里外，关心唯有老人知。"]},{"t":"牡丹花开讶其憔悴戏示诸衲","f":"七言律诗","c":["鄂君何事减生平，岂到山中绣被轻。","国色但存兴庆白，天香犹见雒阳名。","不将富贵撩人意，故作清癯称道情。","直待懒残寒涕尽，明年应有露苞生。"]},{"t":"苦雨","f":"七言律诗","c":["父老传闻雷打雪，果然四十日春霖。","江连野岸鱼龙出，树锁寒烟虎豹深。","田圃预忧新夏旱，经橱先受绿莓侵。","人间欣厌应难免，未必皇天无此心。"]},{"t":"秋日送李廷标赴云南郡丞","f":"七言律诗","c":["秋草萋萋送别频，宾鸿应识宦游人。","一官到处青山在，万里回看白社贫。","筇竹高低逢玉案，滇人老幼候云津。","暂劳佐郡威蛮服，会见泥金凤诏新。"]},{"t":"秋日怀悟石陆太守","f":"七言律诗","c":["瑟瑟西风梧叶疏，讼庭鹤唳夜灯初。","一帘秋月还霄汉，十卷楞严对梵书。","敛目欲寻相见处，閒心几失朗吟馀。","年年此日霜天迥，雁影长空知有无。"]},{"t":"答绍元居士","f":"七言律诗","c":["千里香花今日事，一林松韵昔时人。","名题华藏还从本，石镌如来信有因。","月满峰头閒布衲，雪沉川上忆纶巾。","山钟夜夜寒风度，吹向星岩入梦真。"]},{"t":"送陈季长还闽并寄怡山社中诸子","f":"七言律诗","c":["归帆一过石门寒，空谷难留久客欢。","丹峤共怜孤雁影，金崎谁待夕阳残。","渊明自有田园乐，惠远焉知世界宽。","白社若询山衲信，为言牛火正盘桓。"]},{"t":"岁晏怀姜山","f":"七言律诗","c":["东风吹雨下长干，又见梅花带雪残。","夏杪一传庐岳信，秋来几听雁声寒。","艰难客路谁能久，冷煖人情我已安。","闻道开年定入越，轻舟应过子陵滩。"]},{"t":"孝山太守入丹霞阻雨建封滩","f":"七言律诗","c":["閒似青山忙似城，若为离合倍关情。","东风欲送石门影，椒雨仍留屐齿声。","云掩春灯山路寂，浪高官舫夜江明。","此心久已成相见，魂梦何劳两地生。"]},{"t":"并头兰寄和阿字澹归二首 其一","f":"七言律诗","c":["同心只许二人知，泄漏春光却怨谁。","千里远持华萼信，一峰斜掩日长时。","放先已笑青莲拙，裕后潜教嫩桂移。","林下独宜深对月，灵根翻茂莫相亏。"]},{"t":"并头兰寄和阿字澹归二首 其二","f":"七言律诗","c":["两朵幽香一蒂开，逢人休更说从来。","风前泣露楚人思，月下听猿王者猜。","独秀何妨同众草，争荣时亦破荒苔。","孤芳尽日寒林里，肯向瑶琴叹活埋。"]},{"t":"沈融谷将入都门过别","f":"七言律诗","c":["白社名流觐上台，暂辞山侣一徘徊。","文章有价龙门近，岩壑争先鸟道开。","掩映桃花承雨露，悠扬榆荚趁春雷。","迢迢帆影随归雁，记取明秋芳信来。"]},{"t":"酬木公尊宿","f":"七言律诗","c":["白云何处足安排，万里河山一草隈。","当念久知忘劫量，入林元为济川才。","共期砥柱伤同异，不取移茅绝去来。","底事只今谁举似，伫闻法鼓起春雷。"]},{"t":"寿尹中书恒复","f":"七言律诗","c":["禅者归山问昔游，知君七十去年秋。","世间岁月岂容易，山上云烟忘去留。","招隐久虚宗炳社，怀人频上仲宣楼。","高龄相见难期约，远泛沧江空白鸥。"]},{"t":"仲春得姜山报知以此时入越却寄","f":"七言律诗","c":["一年才得两封书，桃雨霏霏柳雨疏。","吴峤夕阳投寺晚，锦江归鸟啭檐初。","迢遥客路饶新语，寂寞家山掩敝庐。","收拾笠瓢还旧隐，春光容易待樵渔。"]},{"t":"悼仞千壁西堂","f":"七言律诗","c":["昔辞雷岫独踌躇，再别丹山意倍孤。","庆喜堂虚人去后，钵昙花落雁行殊。","七年行径空芳草，此日云山有鹧鸪。","老我鸾溪成底事，不堪吾道日芳芜。"]},{"t":"海幢阿首座生日","f":"七言律诗","c":["法源曾出古皇前，洞水汪流浃后先。","谂老尚纡行脚日，雪峰已是入闽年。","鱼龙寂寞珠江阔，虎豹纵横石镜悬。","贵胤久成谁灌顶，高楼极目鬓皤然。"]},{"t":"初春陪廖使君曾文学游玉帘泉","f":"七言律诗","c":["明珠十斛泻寒隈，幽谷凭谁眼豁开。","最喜使君能拨草，更逢名彦共登台。","风飘素练朝烟细，月浸冰帘夜色回。","终古不曾停此日，却因嘉会忆从来。"]},{"t":"过东古雪悟禅师却赠","f":"七言律诗","c":["一岫独当栏外稳，石门回首众峰移。","长年寤寐酬今日，奕世光仪荷此时。","返照欲浮湖底月，寒云犹护岭头枝。","名山老我应无憾，来往能辞倒接篱。"]},{"t":"春日倩闇道者入山二首 其一","f":"七言律诗","c":["万壑千峰共一林，桃花落尽又春深。","移茅岂作避人计，爨木偏多流水音。","解语应知黄鸟意，高怀忍听白头吟。","休将底事同时俗，杜宇寒枝未易禁。"]},{"t":"春日倩闇道者入山二首 其二","f":"七言律诗","c":["户外新篁已过墙，忽闻语燕复窥堂。","秋风似昔空留社，春月于今仍照床。","尘劫有身难问世，夕阳无脚向何方。","开山我亦成孤调，回首云烟只自将。"]},{"t":"病中寄阿首座","f":"七言律诗","c":["尘刹难将岁月论，每因疏越见寒暄。","一年一度深秋雁，何夕何时入塞垣。","种菊岂惟期晚节，搴萝谁不羡吾门。","月明俯仰犹今昔，亦有闻猿欲断魂。"]},{"t":"玉帘泉用刘德馨太史韵","f":"七言律诗","c":["飞空素练玉同瑩，万古长留花雨声。","曾借东坡深夜偈，更逢摩诘对山楹。","影摇皓月沉空谷，梦绕枯藤濯此生。","好景莫随黄鹤去，遐踪应共白云情。"]},{"t":"又用叶桐初大士韵","f":"七言律诗","c":["泠泠清影擘云开，谁傍珠帘石径回。","千里有帆应计日，三生无约亦登台。","遥天喷雪无留影，洒墨凌空自作堆。","寂照已饶张拙韵，攀藤重许到山隈。"]},{"t":"陆义山舍人入山","f":"七言律诗","c":["深山一自埋清影，谁向鸾溪寺里行。","无著岭头空有约，天亲湖上旧知名。","木樨可遂闻香意，莲社应无生客情。","且就松阴磅礴坐，他年须忆鹤归声。"]},{"t":"陈元水见访病中少阙展待以诗赠之","f":"七言律诗","c":["高掩柴关人影稀，一秋伏枕愿多违。","隔林传语芳名旧，倒屣留欢足力微。","相见定应期后至，入山何可但空归。","挥毫且作他年券，松鹤溪猿认客衣。"]},{"t":"容瞻公见访","f":"七言律诗","c":["忽传谷口贵公来，入座乡书次第开。","同籍故人从帝阙，及门官舫过湘台。","山深江阔何年极，雁去云飞此日催。","更嘱陶潜须纵酒，荒芜松菊易成哀。"]},{"t":"开先山鸣禅师六十初度","f":"七言律诗","c":["重兴祖刹逢狮吼，一代真风付后人。","身在此山惭昔日，道隆堂构荷芳晨。","无穷自可禳山鬼，常住偏能现病身。","千尺龙吟投耳顺，班荆容我话长春。"]},{"t":"丹霞澹长老六十初度","f":"七言律诗","c":["如来寿量付何人，涌出因缘劫外春。","只少六年称弟子，却于五位定君臣。","临机输汝棒能疾，得意惭予道未亲。","且喜分身还集处，端然宝塔露全身。"]},{"t":"新春偕澹长老游玉帘泉","f":"七言律诗","c":["门内风烟许共寻，病馀春色与年深。","云山有意难登陟，泉壑无心自昼阴。","半日楼台增胜槩，千秋人事只如今。","飞霞喷玉终何极，老大相将且放吟。"]},{"t":"程周量寄诗并茧紬赋此酬之","f":"七言律诗","c":["十年烟水思乡客，万里王程限远岑。","寒念云山添老衲，情纡尘刹见高吟。","牡丹已觉时人梦，霹雳全彰隐几心。","桂府一麾非久滞，庐峰还待拥牙寻。"]},{"t":"与方楼冈学士谈千山旧事","f":"七言律诗","c":["廿年人事不堪论，把臂犹怜意气存。","且尽金山深夜话，欲招宋玉一春魂。","河山万里谁同调，雨雪千峰自闭门。","身世悠悠成旷劫，每因芳草念王孙。"]},{"t":"哭开先山鸣禅师","f":"七言律诗","c":["双髻真风在及门，十年铃铎报师恩。","名山我遂失良友，先席谁堪托后昆。","林白鸟哀深院寂，香残云暗几僧存。","洪波自古撼冥壑，入水长人岂易论。"]},{"t":"甲寅春日廖昆湖太守解组归里适予有移茅之役不获出祖诗以送之","f":"七言律诗","c":["政成得请还乡去，正值桃源花发时。","五老清风吹满袖，三山迟日照庞眉。","金轮难买陶潜醉，珠海谁呈宗炳诗。","自笑水云情未瞥，一条楖栗送君迟。"]},{"t":"挽真佛","f":"七言律诗","c":["有子传灯心已安，莲华台上足盘桓。","玉渊步月溪声旧，锦石登山屐齿乾。","放老岂虞调众拙，避人宁计买山难。","讣音正值移茅日，忆昔嗟今眉欲攒。"]},{"t":"送即觉还海云并寄社中诸子","f":"七言律诗","c":["鸾溪一住已三年，衰病无心作俗缘。","见说乡关人尽望，其如云水意犹牵。","白头生计应无别，青鬓仪型莫放颠。","若问老僧高卧处，紫霄峰下绿畴边。"]},{"t":"柬伦宣明使君","f":"七言律诗","c":["老病辄闻衰世事，无缘空抱古人心。","闭门风静看花影，倚树日迟听鸟音。","三径久荒迟贵客，五陵夐绝托瑶琴。","溪山莫笑无陶酿，也有清谈到夕阴。"]},{"t":"退院诗十四首 其一","f":"七言律诗","c":["生来业运满应除，幸托龙天得退居。","庐岳故丘曾有约，金轮祖席且从虚。","黄花晚节凌霜早，白竹新锄数亩馀。","自此幽栖少邻并，清谈无客或观书。"]},{"t":"退院诗十四首 其二","f":"七言律诗","c":["曾向清溪读梵书，老来还傍草堂虚。","窗前绿竹已成荫，屋后青山又举锄。","爱树不妨啼鸟换，避喧宁畏远人居。","往还自此无拘束，仄径随身月上初。"]},{"t":"退院诗十四首 其三","f":"七言律诗","c":["厌事久思云外室，爱身仍托寺边身。","鼓钟梦里惊如昨，眠食时来得任真。","闻道郡城多斥堠，焉知溪上有閒人。","投閒若更受閒累，到老何年是了因。"]},{"t":"退院诗十四首 其四","f":"七言律诗","c":["堪嗟吾道失真传，名实相亏愧昔贤。","光大祖宗凭法鼓，虚沾信施费官钱。","算来底事何人少，空把光阴暗里迁。","损己为人真个话，蹉跎三十又三年。"]},{"t":"退院诗十四首 其五","f":"七言律诗","c":["终年寒涕只垂垂，已分违时老更痴。","茅屋近溪云占尽，山堂依树月来迟。","高峰不入澄湖影，病鹤长栖绝壑枝。","寄语世人休笑杀，春花秋叶两相期。"]},{"t":"退院诗十四首 其六","f":"七言律诗","c":["古今浩浩足商量，谁转西飙山叶黄。","万里干戈江色动，一林松竹鸟声凉。","山头野鹿如无事，树里人家似著忙。","探幽戴日忘劳捍，浃汗如珠归路长。"]},{"t":"退院诗十四首 其七","f":"七言律诗","c":["阅世几埋孤鹤影，含情时复向人前。","钟期既死琴何用，黄石难留书已传。","云隐一峰星汉外，天摇双镜夕阳边。","水声深处多岐路，莫逐樵夫入远烟。"]},{"t":"退院诗十四首 其八","f":"七言律诗","c":["到处相逢说入廛，不因多病不知年。","门庭施设儿孙事，老大生涯水石边。","天下何人能稳坐，山中无事但高眠。","无穷岁月从今日，修短安危总听天。"]},{"t":"退院诗十四首 其九","f":"七言律诗","c":["寂寞湖山秋气清，欃枪日夜少人行。","野僧不识川原事，父老新传郡县名。","丹岫人归无信息，白门书去稍关情。","閒心亦有閒今古，历数兴衰感慨生。"]},{"t":"退院诗十四首 其十","f":"七言律诗","c":["秋深落叶埋芳径，避乱人多向远山。","送客未尝过谷口，蹇驴时见到云间。","户外西风欺病骨，篱边新月照颓颜。","一辞院事閒如许，又听鼙声早闭关。"]},{"t":"退院诗十四首 其十一","f":"七言律诗","c":["一山深又一山深，郢客无端未许寻。","尝因衰世近名事，益见前贤远害心。","俯仰白云空万里，周遭黄叶自长林。","日来渐得眠中趣，不信灵山直到今。"]},{"t":"退院诗十四首 其十二","f":"七言律诗","c":["相寻寂寞古人高，取次多年误汝曹。","大刹尽为豺窟穴，一丘犹是我蓬蒿。","柳溪地阔宜桃李，鹤岭山深足羽毛。","万顷湖光閒自得，笑看人世日劳劳。"]},{"t":"退院诗十四首 其十三","f":"七言律诗","c":["谩说林泉寄一枝，无心犹恐懒成痴。","初终后夜绕栏处，春夏秋山坐石时。","溪鹤伺鱼人不觉，山云到树鸟先知。","记得往年争洞济，涅槃城里竖旌旗。"]},{"t":"退院诗十四首 其十四","f":"七言律诗","c":["休随流俗负初心，生死何曾两不侵。","未举青莲应解语，空教黄叶误知音。","龙蛇易辨当机眼，水乳难忘薄曙襟。","今日始知前日过，庐山秖有此山深。"]},{"t":"寄旋庵解虎并社中诸子","f":"七言律诗","c":["退身卜得紫霄宽，准待诛茅度岁残。","老景秖知黄独美，少年休讶白云寒。","非关苦节成孤往，每念酬恩亦大难。","且学懒瓒聊自慰，还乡又在数年间。"]},{"t":"经开先上山鸣和尚塔","f":"七言律诗","c":["几日相过笑语欢，西风转盼陇楸寒。","溪桥一别人千古，山寺重来竹数竿。","夜月已添新塔影，寝堂犹挂旧蒲团。","扣门不作西州恸，直向深云定里看。"]},{"t":"过栖贤忆即觉","f":"七言律诗","c":["重踏溪桥万虑轻，今人丘壑昔人情。","青山不改寒松色，白水犹留峡涧声。","种竹庄前看已老，携瓶石上忆随行。","黄家兄弟皆沦落，叹息吾门百感生。"]},{"t":"上巢云二首 其一","f":"七言律诗","c":["曾托溪云留半间，十年椎拂未尝閒。","已随梁燕辞秋社，又逐霜鸿入楚山。","浅草尚多戎马迹，高原休笑鹿麋顽。","朝看湖水连天白，拟傍西峰共设关。"]},{"t":"上巢云二首 其二","f":"七言律诗","c":["揽尽湖光释素襟，俯临群岫倚高岑。","蹲云遂有牛头石，观水还堪雁影吟。","檐际星河连绝巘，下方灯火点疏林。","解空住处看弹指，莫负当年游历心。"]},{"t":"生日前一日闻南康戒严","f":"七言律诗","c":["生日今年异去年，连宵风雨忽晴天。","山中岁月无新故，世上兴亡迭后先。","万古云霄高著眼，千峰林木独成眠。","平观总是刹尘事，回忆当时已惘然。"]},{"t":"入岭道中寄诃衍角子泽萌广慈作金圆湛","f":"七言律诗","c":["庐岳于今已劫灰，白云流水尽生埃。","荒榛待辟谁堪守，新竹成阴我再来。","绝食自甘同大众，避人何惮走千回。","一生一死寻常事，珍重寒溪雪夜杯。"]},{"t":"乙卯人日酬樊月藏孝廉并寄大愿文学","f":"七言律诗","c":["匡庐归棹逢人日，是处宗雷在眼中。","莲漏久虚潮上月，蓬门重启雁回风。","四方戎马留村寺，十载家山倚竹筇。","存没未应停笑语，喜君兄弟信能通。"]},{"t":"酬谢邺门许二荄二文学","f":"七言律诗","c":["已分匡庐埋老骨，干戈万里促行尘。","谢家兄弟风流旧，玄度襟情笑话新。","近海烟深含岳色，远山云薄想晴春。","十方多难饶相过，韵事何妨到水濒。"]},{"t":"偶成","f":"七言律诗","c":["乱后无炊强下山，难忘熟处向庾关。","海云旧院曾相约，庐岳新锄且放閒。","战伐不争穷发地，行吟偏有荔枝湾。","日长睡足观潮上，大树交风到石栏。"]},{"t":"话月堂纪梦","f":"七言律诗","c":["梦里还山亦当归，紫霄深处稻花肥。","三间茅屋仍依树，一径松风尚掩扉。","蝴蝶岂知身是幻，庄周应笑我犹非。","鸡声枕畔蘧蘧觉，话月堂前灯影微。"]},{"t":"勉乐说还丹霞","f":"七言律诗","c":["咫尺丹山不肯归，已看红脱荔枝矶。","谁言锦石非深隐，谩说香炉待息机。","阅遍人情还老大，许同宗党莫依违。","灰心赖有吾门在，古道于今岂尽非。"]},{"t":"与诸衲赴大石李村荔枝之约","f":"七言律诗","c":["老人不是贪乡果，为就云峰过远村。","只个荔枝休道著，欲同冰雪倩谁吞。","小舠荡桨重阴淼，二力肩舆骤雨翻。","自是閒中忙不彻，好将风味寄高原。"]},{"t":"喜泽萌来自开先并示尘异时尘异偶患哑","f":"七言律诗","c":["万机休罢付雷同，买得青山湖水东。","乞食暂迂戎马外，耕田先指霭云中。","千两黄金难买哑，一生白眼拚教聋。","渐看人事多疑信，却有吾侪自远从。"]},{"t":"寄南康伦宣明太守","f":"七言律诗","c":["津梁远托济时艰，屡辱荣施动老颜。","世乱一丘难稳住，情高千里欲将还。","真僧只合依深壑，谋食惟应自种山。","更乞大贤终盼睐，紫霄容我永投閒。"]},{"t":"彭飞云刺史入海云偶谈往事感而成诗即以为赠","f":"七言律诗","c":["尽是湖山去住人，闻名何似乍相亲。","论心输我栖云老，问世还他居士身。","万古兴衰花上露，两朝形迹镜中春。","酸辛话到沅湘事，四十年来梦转新。"]},{"t":"方楼冈入海云","f":"七言律诗","c":["金轮惜别谁当后，珠浦重来我独先。","相见不须教瞬目，投机只个得从缘。","西风鼓棹江流疾，山月窥人霜叶穿。","海岛何如匡埠夜，万峰沉雪一灯悬。"]},{"t":"迟紫霄人不至","f":"七言律诗","c":["入关忽忽重逢腊，数折梅花当雪看。","多病每思庐岳切，避人犹觉故乡难。","平临海日行无地，独坐虚堂夜不寒。","意内久悬山信渺，峰头黄叶梦中乾。"]},{"t":"雪木归自博山见予海云闻其母谢世辞还省墓因示以诗","f":"七言律诗","c":["一肩风雪乱中来，祖席欣闻未劫灰。","旧院随行黄叶在，北堂遗爱白杨哀。","百年去住人何限，万里云峰梦欲回。","悲喜且从今日尽，相催还有妙高台。"]},{"t":"海云岁暮","f":"七言律诗","c":["老病空惊岁月深，白云终古恋高岑。","近人渐失溪山意，薄海犹存贫贱心。","戎马百年成往事，川原此夕惜寒襟。","香炉猿鹤劳相待，空谷谁怜隔岁音。"]},{"t":"马铁印严鼎臣二参戎入山","f":"七言律诗","c":["爱我西江意蔼然，高怀重过海云边。","故山千里干戈日，荒院残年梅柳天。","返旆定知壁垒静，到门应觉鸟声偏。","官艘自系榕桥下，话落寒潮只悄然。"]},{"t":"方楼冈自五羊之楚","f":"七言律诗","c":["干戈满地竟南询，烟水迢遥隔岸尘。","难向三生求父母，谁从五位定君臣。","因风荡桨楚云淼，借径还乡江月频。","我亦永怀庐岳顶，何年同泛蠡湖春。"]},{"t":"吴观察采臣入海云","f":"七言律诗","c":["乱后军储未易供，百蛮生事欲从容。","羽书缓急空筹饷，闾井蠲输赖劝农。","赋役尚宽僧户税，寻盟深愧虎溪踪。","麻衣身在陪轩冕，秋叶萧萧落远峰。"]},{"t":"秋兴八首 其一","f":"七言律诗","c":["三老高空入五天，南星一夜隔烽烟。","塞鸿不度庾公岭，江店难逢海客船。","万里秋风悲此日，千峰寒月忆前年。","蕉黄橘绿真堪慰，却引愁人到海边。"]},{"t":"秋兴八首 其二","f":"七言律诗","c":["皇图北极彩云边，旧事伤心在目前。","万里公车催朔雪，午门紫气望尧天。","孤城群盗方三日，许国元勋限五年。","金盌玉鱼千古恨，何堪鼙鼓入林泉。"]},{"t":"秋兴八首 其三","f":"七言律诗","c":["三十三秋污祖席，前年七夕始移茅。","干戈匝地惊林木，居食从天笑斗筲。","入海已深龙鳖蛰，望山犹隔虎狼咆。","高峰雪月何生事，泣向西飙作解嘲。"]},{"t":"秋兴八首 其四","f":"七言律诗","c":["绣户珠帘闭网尘，笙歌不似旧时春。","黄金勒马侯门贵，白璧镂刀壮士殉。","陆贾千金归汉德，钜桥万斛识周仁。","王师到处空秋草，何用衣冠系一身。"]},{"t":"秋兴八首 其五","f":"七言律诗","c":["海月湖风自一秋，南征北伐两悠悠。","富强岂是帝王事，成败那深将相忧。","万古乾坤开碣石，满天星宿照寒洲。","艰难世故空双眼，错认扬州是冀州。"]},{"t":"秋兴八首 其六","f":"七言律诗","c":["龙虎风云出大荒，蛟腾鱼跃满河梁。","楚鹰自猎身能白，篱菊迎人色欲黄。","灵武何年成往事，神仙无地问汾阳。","滔滔江汉连天碧，遮莫瑶池在上方。"]},{"t":"秋兴八首 其七","f":"七言律诗","c":["百二秦关定帝州，祖龙何处觅浮丘。","不信鲁连能蹈海，却疑李广未封侯。","云山一自归黄鹤，沙渚于今泛白鸥。","观水再逢梧叶冷，乘槎应溯蠡湖秋。"]},{"t":"秋兴八首 其八","f":"七言律诗","c":["闻道荆门未解兵，九嶷秋色对湓城。","僧归湖上无消息，客到虔州有战争。","三载孤踪怜踯躅，一楼明月带欃枪。","逢人但问西江水，日下黄尘蔽乱营。"]},{"t":"寄王廉宪仲锡","f":"七言律诗","c":["峄阳孤树逼青霄，流水高山向泬寥。","擿发久推今广汉，持平还拟古皋陶。","千寻渤海群龙战，万里秋风一鹗骄。","闻道遐心垂顾问，东篱花待晚萧萧。"]},{"t":"梅影诗示愿海","f":"七言律诗","c":["山斋不作师雄梦，那得佳人入户来。","四壁疏斜疑带月，一帘浮动已成埃。","未堪折赠谁当幻，更欲移踪独上台。","恐伤洁白聊同夜，自有寒香透劫灰。"]},{"t":"磊园舍作禅林招予主社感而留题","f":"七言律诗","c":["四十年来事转新，此时泉石昔时人。","右军第宅今犹在，晋室山河久已湮。","拄杖尚能观布地，栽松真欲论前因。","深堂雁影何由度，莫话寒山春信频。"]},{"t":"庞若云招游亦庵有怀梁同庵","f":"七言律诗","c":["兰若重游兴未衰，到门一望却犹夷。","当欢亦自知今日，后会难忘是往时。","篱落暂增新结构，山前尚有旧交知。","夜堂细语人何在，满目河山涕欲垂。"]},{"t":"除夕瞎堂梅花再放","f":"七言律诗","c":["岭表梅花不见腊，今年寒尽数枝开。","谁怜海国僧归后，故遣庐山春信来。","就下似临三峡水，因高疑傍七贤台。","暗香处处应无别，欲剥黄柑拟雪杯。"]},{"t":"中秋后三夕与诸子玩月感赋","f":"七言律诗","c":["连宵忍见天河净，风散重霾缺亦明。","落落河山人北望，悠悠关塞雁南征。","伤今聊作昔年兴，感往偏怜此夕情。","珍重庭前寒魄影，兰亭乐事惝然生。"]},{"t":"丁巳九日海云书怀","f":"七言律诗","c":["近海寒花亦未开，故山佳节几登台。","最怜千里同秋色，不共高林倒茗杯。","落日亭亭江路邈，长天迥迥雁声哀。","淹留每恨无成计，胜事空嗟岁月来。"]},{"t":"悼旋庵湛都寺","f":"七言律诗","c":["颓龄叹逝苦低垂，至性从今更有谁。","伏腊定先同列觉，艰难犹畏老僧知。","尝因高谊添身累，秖恐劳人却病迟。","回首西风成隔世，不堪挥涕忆当时。"]},{"t":"寄尹恒复中书","f":"七言律诗","c":["踪迹浮沉忆鬓华，当时文社几周遮。","辞山客久依残寺，有子年高只住家。","斜阳转景扶危柳，旅雁回风落浅沙。","白首相思何以赠，一杯清茗寄流霞。"]},{"t":"生日酬王廉宪仲锡吴观察采臣","f":"七言律诗","c":["草白花黄霜已深，调孤弦缓负知音。","全生岂尽庖丁技，三乐终非荣叟心。","遂枉文章归白社，尚纡瓢笠寄东林。","难忘高谊惟今日，指顾湖山起越吟。"]},{"t":"又酬南康太守伦宣明郡丞李子文","f":"七言律诗","c":["入岭时维六十七，当当七十尚盘桓。","广南望雪头先白，湖上瞻风叶正丹。","云间招手劳宗炳，火里煨牛愧懒残。","千里珠光摇海岳，益增归思倚栏干。"]},{"t":"又酬社中诸子","f":"七言律诗","c":["因乱离山托海濒，朔风初动水粼粼。","三千路阻干戈日，七十年催老病身。","慧远几时归净社，宗雷随地识前因。","莫辞秉烛烧残夜，鹤唳猿啼梦里频。"]},{"t":"又示各山","f":"七言律诗","c":["损己何曾遂利人，蹉跎七十可怜春。","足知尘世无成事，应惜云林暂住身。","万古江河犹往复，当时观听自疏亲。","迢迢空劫谁为主，莫逐生缘滥夙因。"]},{"t":"将还庐山留别社中诸子二首 其一","f":"七言律诗","c":["孤屿寒暄不记年，蜃楼海市几推迁。","片帆且趁东风便，老眼回看穗石偏。","春燕任教巢旧屋，山池重见长新莲。","人间聚散何曾定，雪夜还应待剡川。"]},{"t":"将还庐山留别社中诸子二首 其二","f":"七言律诗","c":["垂老生涯在石门，万峰积雪暗寒原。","今心未易酬先德，古貌终难媚后昆。","海客已随春雁去，溪声应共陇花繁。","流光冉冉干戈里，影息深云起自存。"]},{"t":"佛山遇严玉寰提督奉召入京却赠","f":"七言律诗","c":["百粤如今海不扬，相江一战敌宵亡。","始知事久论终定，足见功成迹逾光。","石勒岂能窥晋室，张巡全未失睢阳。","臣心如水天心鉴，万里星驰入帝乡。"]},{"t":"泊弹子矶","f":"七言律诗","c":["得附官艘称野情，碧天岩壑望中生。","重围初解韶阳堞，插羽仍驰西粤兵。","几岁干戈销客梦，一江风雨滞王程。","莫嫌老大归山暮，松菊荒芜赖晚成。"]},{"t":"舟次别严公","f":"七言律诗","c":["君趋凤阙我还山，共载江流两月閒。","戎马未酬臣子志，风烟已换道人颜。","拍天湖水春乘涨，鼓角官艘夜入湾。","计日虎符重出镇，双旌遥指白云关。"]},{"t":"奉柬制府董公","f":"七言律诗","c":["忆昔鸾溪绍祖山，时荒分卫荷隆颁。","出门倚杖惭僧服，避地移茅入庾关。","洪府远闻江路静，孤峰仍逐使臣还。","寅缘一望孙弘阁，七载衔恩想像间。"]},{"t":"哭石鉴覞子","f":"七言律诗","c":["八旬万里望寒原，倚杖山堂笑语温。","欲启蒋生当日径，俄招宋玉百年魂。","孤松日暮怜归鹤，断壑春深泣夜猿。","从此掩关忘岁月，不知谁是我儿孙。"]},{"t":"五月一日申刻睡起有感","f":"七言律诗","c":["闭门睡足申初起，峰转斜阳到竹扉。","万里干戈馀此日，五年江海待忘机。","黄叶不教流水去，白云终向故山归。","独怜跋涉同行者，失我三人泪满衣。"]},{"t":"戊午归自岭外以中夏上巢云","f":"七言律诗","c":["山堂九夏无人到，策杖寻僧问石源。","田尽树连迷虎径，云深溪断见松门。","当窗湖水浮衾枕，隔岫禅声入梦魂。","徙倚忽思珠海日，不知身已在高原。"]},{"t":"读石鉴遗诗","f":"七言律诗","c":["读罢遗诗意惘然，中间离合总堪怜。","沥乾热血难寻梦，欲趁馀生直上天。","几回后事悲前事，安得今年是去年。","顾我掩关惭已晚，閒情休更落中边。"]},{"t":"秋蝉四首 其一","f":"七言律诗","c":["轻身高木可悠悠，断续酸伤独不休。","观世已甘朝露薄，因风犹作岁华忧。","响彻千峰人在梦，生从一壑影临秋。","若教似汝肠应断，白首难为玄鬓愁。"]},{"t":"秋蝉四首 其二","f":"七言律诗","c":["历尽孤危动蔡琴，华冠几岁遂投林。","悲鸣竟日终何语，静抱长松只此心。","万里秋声风切切，一枝寒色月森森。","最怜客泪伤南北，都在离怀湿曙襟。"]},{"t":"秋蝉四首 其三","f":"七言律诗","c":["无求不敢向人清，繁响徒萦十里行。","曾学金人长杜口，忽逢玉露自成声。","高栖未必全关节，弃秽难辞是近名。","翘首长空如独诉，岂堪了了托閒情。"]},{"t":"秋蝉四首 其四","f":"七言律诗","c":["衰柳疏槐影自单，微吟真欲寄琅玕。","端绥有意陪高士，华首何心入侍冠。","飞映晚霞还就荫，饱餐朝露不知寒。","绿阴深处情犹热，莫讶噭噭到日残。"]},{"t":"与尘异论及姜山慨然有作","f":"七言律诗","c":["生别何云遂死离，百年人事不堪思。","从今晤对知多日，忆昔绸缪已后时。","泪尽江河空滚滚，看穷日月自迟迟。","寒山赖有安心处，收拾残编欲付谁。"]},{"t":"秋日游白鹿洞时督学邵公太守伦公重修书院赋呈伦公二首 其一","f":"七言律诗","c":["鹿迹难寻木叶乾，紫泥何事到云端。","一人显晦千秋系，百代楼台几日欢。","青松自荫讲堂静，画栋高临流水漫。","不堪回忆读书处，鹤唳猿啼白昼寒。"]},{"t":"秋日游白鹿洞时督学邵公太守伦公重修书院赋呈伦公二首 其二","f":"七言律诗","c":["代出真儒起陆沉，丁丁伐木振云林。","乾坤重换新堂构，山水还能增道心。","晓月欲分香岫色，西飙谁辨峄阳音。","曾从五百占名世，一睹遗风景仰深。"]},{"t":"游凌云留赠主人","f":"七言律诗","c":["沿溪万竹深深处，壁削凌云自一峰。","贪月少栽当砌树，爱人常策北山筇。","长年一衲寒暄换，小榭临窗苔藓重。","交臂忘怀成好友，更期借榻得从容。"]},{"t":"游玉川门留赠主人","f":"七言律诗","c":["何人筑室邻三叠，千尺飞泉冷布袍。","径凿巉岩依石壁，门开空阔俯林皋。","月来自照一龛静，云散长看五老高。","最爱秋山留晚景，行人寒夜秖成劳。"]},{"t":"题三叠泉二首 其一","f":"七言律诗","c":["千丈寒泉天上来，巨灵三劈起风雷。","冷冷玉屑镂青黛，洸洸珠帘罥紫苔。","叹逝冥心归有道，临流染翰待洪才。","吾门目击知何说，万古龟龙剖不开。"]},{"t":"题三叠泉二首 其二","f":"七言律诗","c":["高山流水何年事，俯仰登临今古情。","群岳欲干霄汉直，长川不共圣人清。","一条拖练探龙窟，千片摧冰护蜃城。","顿入光中忘岁月，琉璃国里许谁行。"]},{"t":"还庐山与尘异第一次对雪二首 其一","f":"七言律诗","c":["五年相失忽如昨，黯淡千峰暝色移。","严冷投人偏欲近，洁清于世肯相期。","翠竹且教凌后夜，青松不敢傲当时。","毋忘白首轻寒意，拥被为君赋雪诗。"]},{"t":"还庐山与尘异第一次对雪二首 其二","f":"七言律诗","c":["君看五老与天齐，错落群峦影渐低。","地轴压沉茅屋在，星辰无恙野云迷。","青青草树难为色，白白津梁易上泥。","一夜红炉销不尽，晓疑明月满峰西。"]},{"t":"净成阅工口占","f":"七言律诗","c":["当初结宇看容易，累石千层费巨财。","宝殿未成迟佛住，山楼粗就即僧来。","欲移杨柳沿堤入，拟凿莲池对户开。","双手如锥聊话会，一床锦绣待人裁。"]},{"t":"许明府逸林见过夜话次早陪上净成有诗见投率笔奉答","f":"七言律诗","c":["未竟夜堂无义句，明朝且逊杖头论。","崇山仄径回风细，浅水微烟过雨痕。","望望岂知春已入，行行空觉鸟初喧。","一铺功德聊回互，又待花繁到石门。"]},{"t":"春日口占呈郡中诸公","f":"七言律诗","c":["红桃碧柳到窗前，倦倚绳床听杜鹃。","曾历兴衰如昨梦，渐忘名字自今年。","少延生客调山惰，故纵高谈放老颠。","被物修名官占尽，独留一壑恣吾眠。"]},{"t":"咏木兰花","f":"七言律诗","c":["翛然高倚松杉上，白比梅花广大身。","赤体凌霜寒彻骨，多情含睇暗怜春。","似嫌弱质惭倾国，独许微香稍近人。","莫以繁枝掩冰雪，藐姑丛里绝芳尘。"]},{"t":"二月初九日山楼竖栋示诸子","f":"七言律诗","c":["东风吹雨过南皋，一片晴云捧日高。","撑栋架楼人力健，敲金持梵谷声豪。","巨灵护我终成住，乘愿同人岂见劳。","不爱繁华爱岑寂，夜寒谁解听松涛。"]},{"t":"寄澹归二首 其一","f":"七言律诗","c":["年年樗散愧相师，览镜遥怜鬓似丝。","此道几人同踼倒，登山饶我独扶持。","湖中春水堪乘兴，月下晴云好共披。","荒院木兰花盛发，折来清供欲贻谁。"]},{"t":"寄澹归二首 其二","f":"七言律诗","c":["下江路断偏为寄，入岭人频懒作书。","不能仰面成疏放，强欲诛茅似有馀。","峰抱石坪宜架阁，屋连荒垄且开畬。","前途未必无知己，却较还山得自如。"]},{"t":"伦太守宣明许明府逸林祀匡庐便道见过","f":"七言律诗","c":["雨暗郊原春尚寒，一行车马驻云间。","山祠酌酒千杯剧，野寺寻僧半日閒。","欲问沧洲终觉远，回看紫岫若为攀。","溪声竹影娟娟媚，不信峰头老更顽。"]},{"t":"李郡丞子文同伦太守许明府祀匡庐伦许二公入寺李公独上白崖诗以寄之","f":"七言律诗","c":["江州司马慕高踪，贪引山楼听夜钟。","冒雨几人过僧舍，搴萝独自上云峰。","何妨不见戴安道，有兴还寻南院颙。","莫厌东林不设酒，署斋长掩一重重。"]},{"t":"与诸子赏牡丹用尘异韵","f":"七言律诗","c":["山寺何来富贵花，汝曹应是厌繁华。","无端乘驿从京邸，误杀含香醉晚霞。","天外落红春日早，人间绣被夕阳斜。","上方更有琉璃国，试数峰头第几家。"]},{"t":"净成邀看牡丹是晓风折一枝行僧送来口号一律示之","f":"七言律诗","c":["东风不是妒花开，一枝先折过溪来。","檀心已入青宵梦，叶底难藏锦绣堆。","似厌芳尘轻绝袂，敢辞青目重登台。","从来仙种皆忘物，自有怜香护宝胎。"]},{"t":"净成看牡丹","f":"七言律诗","c":["寻花又向石溪东，岂逐君王笑脸中。","一朵微醺仍浅碧，数株轻紫倚深红。","影摇茗盌沉春绮，香结云岚递晚风。","怪底琵琶遮不住，笙歌缭绕万山重。"]},{"t":"巢云看牡丹酬广慈静主","f":"七言律诗","c":["看花再上一层峰，明岁新知即旧逢。","春露已承当日渥，御袍先赐隔年封。","娟娟国色含风净，郁郁天香裛雨浓。","金带莫愁迟莫意，魏公门外许从容。"]},{"t":"净成石泉","f":"七言律诗","c":["曾闻陆羽题招隐，天下标名第六泉。","紫岫更饶甘露味，洪源高出石流鲜。","子瞻到处西湖在，宏觉他生铁镇传。","笑我住山多苦涩，一杯常得试云边。"]},{"t":"曩在海云偶得一天风雨沉山阁之句时尘异诸子侍坐命作对语尘异以万古云烟锁石门应予心异之己未八月初七入双镜楼忽忆前事正当斯时因用旧句足成一律以识梦中之境始信人之心愿原非虚设也","f":"七言律诗","c":["淹留江海惜精魂，且喜今朝获旦昏。","岚影鹤声新耳目，竹林牛火旧寒暄。","一天风雨沉山阁，万古云烟锁石门。","起视不知成浩劫，六朝人物想应存。"]},{"t":"送刘莘叟别驾督漕北行","f":"七言律诗","c":["山中送别限溪桥，万里王程向日遥。","记得去秋松峤月，望穷长夏灞陵潮。","军输几岁功曹贵，戎马今年相国骄。","回首征帆随雁影，北风吹雪下云霄。"]},{"t":"中秋双镜楼与诸子玩月","f":"七言律诗","c":["云里高楼结构成，凭栏一望万峰晴。","移床且待黄花盛，玩月先当白露清。","阶下牡丹新影瘦，檐前湖水叠波泓。","颓龄赖有良宵乐，数尽长空过雁声。"]},{"t":"哭法纬济同学","f":"七言律诗","c":["同出师门愧弟兄，烽烟几岁梦魂惊。","悲离已作他生事，悼往终伤此日情。","白鹤何年归华表，黄岩依旧在湓城。","一杯清茗将双泪，千里遥称妙喜名。"]},{"t":"足疾","f":"七言律诗","c":["寸步难行人事非，六时高卧壮心违。","黄花自向篱边绽，白雁谁看天际飞。","有约不辞摩竭室，无言长掩懒残扉。","缅惟旷劫匪容易，莫负锦斓当日衣。"]},{"t":"九日病起登双镜楼二首 其一","f":"七言律诗","c":["重阳再见此登临，久病翻怜少壮心。","黄叶已寻幽涧落，白云犹闭独峰深。","多餐篱菊宁辞老，细看茱萸又到今。","寂寞湖山窗里尽，秋风高顶几成吟。"]},{"t":"九日病起登双镜楼二首 其二","f":"七言律诗","c":["万里秋深松柏哀，几人于此重徘徊。","入帘西日四山暮，极目长天独雁来。","宿草曾经春露早，寒林已见朔风催。","川原一往成今昔，谁向峰头数劫灰。"]},{"t":"独鹤","f":"七言律诗","c":["抟云万里竟徒劳，沙水无鱼入九皋。","不鸣莫论谁堪和，在荫何妨影自高。","体皓不贪松月照，息深无虑北风号。","鹳雏鴳稚休轩举，若向人前惜羽毛。"]},{"t":"孤雁","f":"七言律诗","c":["北风吹雪白纷纷，孤雁南飞紫塞分。","顾影每怜江上水，贪程不见岭头云。","稻粱汝亦甘为客，寒暑谁当念失群。","春到自知沙漠阔，远天嘹喨独峰闻。"]},{"t":"答刘别驾","f":"七言律诗","c":["万里王程往返忙，贤劳独我为才长。","漕臣转运供军国，诏使联翩出帝乡。","发赈可能周率土，其亡真信系苞桑。","蒙头有衲喜何级，和韵成诗兴更狂。"]},{"t":"己未仲冬十一日计尘异当以此时度岭率题长句一章","f":"七言律诗","c":["常思吾老及人老，归省情知许出山。","去日自辞星子石，计程应到庾公关。","法门有子皆他子，膝下承颜忆别颜。","相见定难期久暂，海濒江岸水潺潺。"]},{"t":"梦轩书怀","f":"七言律诗","c":["入山早计今生事，三十蹉跎到此时。","鞭马已无千里疾，解牛徒善一刀迟。","曾为弟子知恩重，谬作人师叹道衰。","息六愈深鹏起处，便乘云翮出天池。"]},{"t":"大雪开帘看牡丹台","f":"七言律诗","c":["无赖病夫朝尚眠，不知风雪霁长天。","千重珠网开丹壑，几树珊瑚种玉田。","看去已忘今日后，坐来殊笑数年前。","孤怀却喜无人对，静抱寒襟花叶边。"]},{"t":"己未岁晏","f":"七言律诗","c":["山中今又度残年，七十加三贫病连。","同学已归黄土尽，及门多在白云边。","客来到处攒斋料，工去逢人借赏钱。","旧事不堪更提起，生涯只有日高眠。"]},{"t":"南康太守伦宣明见过","f":"七言律诗","c":["山中交臂非今昔，白首谁论世上情。","曾到帝乡知士贱，却从林麓觉身轻。","寒梅罥雪香弥远，霜竹乘风影倍横。","百岁升沉一弹指，看君嬴得学无生。"]},{"t":"伦宪明文学入山赋赠","f":"七言律诗","c":["几载音书意渺茫，翩翩今喜到山房。","相看水乳多生旧，若问因缘后话长。","万里江山非远近，一灵明昧岂荒唐。","君家兄弟多高谊，三径随时到不妨。"]},{"t":"放言六首 其一","f":"七言律诗","c":["从来住处难如意，四十年居大众中。","今日退閒犹我造，小楼高出与山同。","窗间湖水寒光淼，屋外蔬畦霁色葱。","只有一般堪笑煞，或时富贵或时穷。"]},{"t":"放言六首 其二","f":"七言律诗","c":["富来架屋连云栈，转眼春粮不夏谋。","佛殿勉装过岁易，工钱赊落待谁酬。","竹鏖鹤岭知难贩，木取花园劝助修。","活计随时穷则变，人生何用苦营求。"]},{"t":"放言六首 其三","f":"七言律诗","c":["入山五日辞归省，尘异人疑岂有他。","炮药莫贪银罐好，典衣休惜子钱多。","移将野果当窗种，灌取秋葵待客过。","百事到来终做去，住山须是老头陀。"]},{"t":"放言六首 其四","f":"七言律诗","c":["提瓶挈水非容易，久住都来信宿因。","近学维摩空一室，还同鲁祖坐三春。","亲承尽是门庭事，道谊难为溪壑人。","岂到白头方觑破，生涯谁道有天真。"]},{"t":"放言六首 其五","f":"七言律诗","c":["广海闽山岂不安，几生梦绕紫霄寒。","一枝已遂巢居乐，满腹宁忧河水乾。","未曾九十骄荣叟，坐断千峰笑懒残。","宠去辱来看欲尽，刹尘何似太虚宽。"]},{"t":"放言六首 其六","f":"七言律诗","c":["饥饱寒温总听天，生来不乞半文钱。","非关性僻偏甘淡，只是人前耻受怜。","心里无求堪作佛，世间有欲岂能仙。","从他瞋怪从他爱，我自堆堆白昼眠。"]},{"t":"庚申初春得尘异去冬书","f":"七言律诗","c":["一程书信隔年还，细读犹能慰老颜。","宝镜自传寒月夜，寂光常照老梅关。","重经古道疑来日，乍听新潮别故山。","想到板桥回望处，几多人倚石阑干。"]},{"t":"正月二十一日","f":"七言律诗","c":["心閒性僻多幽趣，几许天真总著忙。","退院七年成后座，归人三月滞南方。","更买邻山樵径断，多培修竹引泉长。","若无愁病虚廊下，古木森森春草芳。"]},{"t":"偶得辛丑八月上华首台作不觉潸然复用原韵成诗聊写怀抱时庚申七月晦日也","f":"七言律诗","c":["旧事荒凉不记年，残篇收拾倍悽然。","西风叶堕梧桐后，山月寒生霜露先。","数历艰危馀老病，不堪绍续托林泉。","难忘涓滴成孤负，虚愿何曾到眼边。"]},{"t":"中秋伦太守见过","f":"七言律诗","c":["宦海波涛觉后惊，人间如梦信空名。","东林不满陶公意，逵路殊深扬子情。","万里秋风催锦瑟，千门寒月驻霓旌。","豪华易尽心难尽，谁向钟山悟此生。"]},{"t":"伦太守昆仲杨文学以贞过访","f":"七言律诗","c":["何人并辔访山隈，道是寻僧乘兴来。","入座翩翩今贾董，谈心落落旧宗雷。","云横谷口樵歌出，风过溪头牧笛哀。","错比龙钟双舞袖，德云不在妙高台。"]},{"t":"秋兴八首 其一","f":"七言律诗","c":["谁向峰头数劫灰，河清海竭两徘徊。","新亭泪尽江山在，故国歌残禾黍哀。","落落燕泥秋社没，亭亭雁字西风催。","渊明不解长林意，烂醉东篱任菊开。"]},{"t":"秋兴八首 其二","f":"七言律诗","c":["羽檄星驰万里津，清秋白昼蔽行尘。","五都无市三川旧，七萃何人六郡新。","衰柳不知承白露，寒花恰似倚青春。","世间岂有西王母，周穆当年认未真。"]},{"t":"秋兴八首 其三","f":"七言律诗","c":["国运谁当论短长，唐虞终古仰明皇。","田横不死客仍散，诸葛虽生汉亦亡。","秋老渐闻蝉响促，日西惟见鹤归忙。","尼山叹逝川犹在，试与当年圣者商。"]},{"t":"秋兴八首 其四","f":"七言律诗","c":["三十春光一布衣，太平时节下重帏。","金门待漏心偏壮，铁锁沉江愿始违。","悟物几年成远托，阅人今日已知非。","川原垒垒还今古，叶尽秋林早闭扉。"]},{"t":"秋兴八首 其五","f":"七言律诗","c":["一天星宿话应难，露滴秋原泪未乾。","七轴莲花毫素尽，十重帝网寂光寒。","生前有梦随蝴蝶，死后无人托臂肝。","月落澄潭看不彻，夜深携策绕阑干。"]},{"t":"秋兴八首 其六","f":"七言律诗","c":["达天委命是吾师，万古人心未易知。","秋尽故怜篱菊早，春先犹恨柳条迟。","张良岂果为韩出，徐庶何妨与汉辞。","谪宦吊湘哀贾谊，因人聊写在廷时。"]},{"t":"秋兴八首 其七","f":"七言律诗","c":["天网恢恢不可逃，兴亡千载恨王曹。","一生未易偿忠逆，当世谁知慎节操。","报楚伍员终过甚，酬知聂政亦云劳。","满山霜气澄秋汉，纵步青云岂是高。"]},{"t":"秋兴八首 其八","f":"七言律诗","c":["长源何事乞归山，功大难为骨肉间。","富贵每多孙子累，崇高偏觉孝慈艰。","秋风万里投林疾，寒月千峰入座閒。","莫道深云高卧足，近名干誉亦须删。"]},{"t":"闻雁","f":"七言律诗","c":["北雁南飞朔气侵，悲鸣未必为知音。","飘飖万里凭风力，断续千行到岳阴。","细认江芦归路远，难携海燕入云深。","旷观物理皆如此，老我桄榔信宿心。"]},{"t":"尘异广慈呈对雪诗用韵和之","f":"七言律诗","c":["白昼亭亭日渐沦，川原如醉净行尘。","旧时草树全无色，一夕江山尽变银。","流水不知溪远近，随风先见石嶙峋。","几翻緌繣长空在，耐得深寒景倍真。"]},{"t":"牙痛诸子入候时正大雪命西轩围炉分赋","f":"七言律诗","c":["世逢多难厌馀生，买断青山尚畏名。","老病日思先佛训，寒温时感后昆情。","新归共说关梁涩，旧住惟言菽水清。","炉火初红风味别，现前佳句雪中成。"]},{"t":"夭凤","f":"七言律诗","c":["鷟鸑初生未解飞，双眸炯炯羽毛稀。","发声震岳惊群鸟，昂首淩空撼落晖。","尤物自来人欲杀，灵姿巧遇命偏违。","梧桐世上多疑误，九万云霄好息机。"]},{"t":"冬杪示诸子","f":"七言律诗","c":["历尽秋冬又逼春，回风舞雪万峰新。","自从多病方知老，久谢閒名懒见人。","厌乱忍闻当世务，早眠犹得住山身。","去留但听诸来者，第一同居莫厌贫。"]},{"t":"哭澹归释子二首 其一","f":"七言律诗","c":["忆别山堂意黯然，相期隔岁返林泉。","木兰花发诗频寄，山菊霜零梦已先。","僧史未酬当世业，道风空付后人传。","普贤行愿谁如汝，长子于今永绝弦。"]},{"t":"哭澹归释子二首 其二","f":"七言律诗","c":["爱物情深转似瞋，随缘衣钵散僧贫。","生营狮座酬初志，死塔他山见夙因。","每念孤怀真类我，尝于岐路愧求人。","师资相搆何期合，百劫千生两认真。"]},{"t":"送尘异但子掩关","f":"七言律诗","c":["扶摇万里岂徒劳，鲲化还教惜羽毛。","海运莫随风力转，龙门休畏浪头高。","为资世论饶宗说，欲起寒泉拟桔槔。","好把青铜照两鬓，谁当牢落老蓬蒿。"]},{"t":"柬伦太守","f":"七言律诗","c":["保障江城艰钜身，十年风雨见孤臣。","从来世乱思廉颇，谁复功成忆寇恂。","苫块贤劳扶社稷，潢池安戢答君亲。","独怜狡兔川原尽，翘首九重泪点巾。"]},{"t":"澹归灵骨入塔","f":"七言律诗","c":["投江料非诸子事，归岭宁违汝夙心。","既订生还三峡寺，何妨死塔五溪岑。","孤衷岂植燃灯后，大愿还同楼至深。","老眼泪涔挥不断，千生魂魄许相寻。"]},{"t":"谢邺门贻梅影诗用韵和答以酬其意","f":"七言律诗","c":["月下开门送一枝，满林珠玉不胜思。","休伤岁暮难为折，恼乱春愁是此时。","只有孤踪投客意，何曾香气惹人知。","疏斜自向山溪早，银烛珠帘影每迟。"]},{"t":"寄酬闽中诸护法","f":"七言律诗","c":["笠瓢几度戒前程，老病人扶畏远征。","尚冀裴休宽后命，弥惭慧远滥虚名。","花香已见多生愿，尘刹难忘此日情。","沟壑未填终不负，山头猿鹤听分明。"]},{"t":"慰长庆诸衲","f":"七言律诗","c":["尽道归山山日长，半销衰病半心伤。","老成凋谢吾宗丧，少壮参商门户荒。","沉雪振衣临海众，深溪涉水出山堂。","僧归闽寺休惆怅，须念而翁满鬓霜。"]},{"t":"送李藿思刺史开化","f":"七言律诗","c":["将军急为收滇郡，刺史新除出紫薇。","百姓已遭荼毒久，深慈应念胁从非。","大君有命威先夺，廉吏持平乱后归。","万里单骑臣力竭，清忠知与世相违。"]},{"t":"简残帙得悼旋庵作","f":"七言律诗","c":["谊重难为继后尘，道衰聊与数前因。","非关今日方知汝，却忆当时尚有人。","海寺再来曾四夏，湖山归去又三春。","凄凉偶捡残章句，旧恨随声双泪频。"]},{"t":"牡丹发蕾","f":"七言律诗","c":["年年三月牡丹开，未及花开春渐回。","欲挽春光谁著力，望穷花信独徘徊。","移根尚忆中秋早，沃土曾经两夏培。","叶底秾苞应计日，等閒容易到重台。"]},{"t":"眼昏","f":"七言律诗","c":["去年齿痛疑生尽，今日偷生眼又昏。","牡丹蕾小花同叶，山径云摇石作豚。","世故无闻真法界，目前不见别乾坤。","解嘲未必全因老，亦有微言过漆园。"]},{"t":"诸衲呈望牡丹花不开诗","f":"七言律诗","c":["迟迟花信费疑猜，蜂蝶空劳去复回。","杨柳低垂枝欲坠，芰荷初莳叶频开。","似嫌富贵先承座，却爱慈恩后举杯。","白首自知山日永，洛阳笙管为人催。"]},{"t":"隐几","f":"七言律诗","c":["休将心事自罗笼，法界谁当较异同。","情为烟霞成绝世，道因衰病到无功。","山堂隐几纡尘刹，石磴凌风跨海东。","笑煞神通移听睹，人间天上一何穷。"]},{"t":"百合花用足两韵二首 其一","f":"七言律诗","c":["花以无名胜有名，野林僻径称山情。","微风度水香宜远，高日眠云梦不成。","遁世岂矜尘外见，近人最是热中清。","折来未必供幽赏，独忆当年溪上行。"]},{"t":"百合花用足两韵二首 其二","f":"七言律诗","c":["影落荒林静者知，微香不与众芳期。","云深绝壑水流处，月静高空雨过时。","邂逅芝兰随臭味，穷通山日自葳蕤。","从来物理多同异，指点川原付画师。"]},{"t":"辛酉中秋","f":"七言律诗","c":["秋空云散碧霄澄，万里江山倚太清。","此夜月高人尽赏，谁家香冷梦初成。","光辉不作悲欢色，今昔偏从寒照生。","惟有雁翎斜度急，一行倒影入河明。"]},{"t":"高方伯钦如入山","f":"七言律诗","c":["远客登山谈往事，无端并起刹尘心。","水中有树还荣落，镜里无人非古今。","万里长空过雁影，千年画壁卧龙吟。","凭君高著云霄眼，莫向浮生枉尺寻。"]},{"t":"许太守浣月入山","f":"七言律诗","c":["使君为政讼应稀，乱后民生贵息机。","饲鹤衙斋秋日永，寻僧山院晚风微。","意消坐对忘宾主，论发由中绝是非。","我亦无心方外侣，閒云流水共依依。"]},{"t":"秋思二首 其一","f":"七言律诗","c":["高松白鹤辞巢去，腐草青萤入梦来。","秋色不曾为客改，寒砧一自向谁哀。","东山月出临无地，南越猿啼旧有台。","回首石楼残茗在，岂须沉醉菊花杯。"]},{"t":"秋思二首 其二","f":"七言律诗","c":["山临海岸烟波近，不到霜深寒已知。","燕畏高秋辞社早，雁疑残渚向南迟。","风吹白草终何处，日丽黄花曾几时。","岂爱披云作长啸，石门风树正相思。"]},{"t":"山居十首 其一","f":"七言律诗","c":["百岁光阴大半过，西山消息近如何。","石门有路知通塞，空谷无人但啸歌。","三峡小桥黄叶少，五溪流水白云多。","尝因世上疑天上，纵得长生事转讹。"]},{"t":"山居十首 其二","f":"七言律诗","c":["已办深山老此身，到来山事又从新。","拟安水碓寻溪路，取转租田替佃人。","秋月满天云影碎，西风匝地雁声频。","目前景物随时得，收拾僧房且过春。"]},{"t":"山居十首 其三","f":"七言律诗","c":["坐石何年到夜深，临溪松竹已成林。","一时人事将非昔，万叠峰峦又是今。","月影入潭无透路，雪花投树有微音。","每当寒到知身老，灯暗香残怯曙襟。"]},{"t":"山居十首 其四","f":"七言律诗","c":["虎迹纵横万壑阴，难辞生客远相寻。","传来世故疑前代，看去人心岂但今。","风细稻香过浅草，日西檐影上高岑。","已知寒暑迁流尽，更说颓龄雪鬓侵。"]},{"t":"山居十首 其五","f":"七言律诗","c":["一般雪色白如绵，随意风吹堕野田。","万里飞花谁不爱，千林掩室独颓然。","极深断壑堆难化，绝顶孤峰出最先。","久住山中冬景好，地炉宿火到新年。"]},{"t":"山居十首 其六","f":"七言律诗","c":["青帝乘权辟大荒，雪消冰泮石泉长。","山花远近春光遍，岸柳高低风力狂。","野鸟不知声巧拙，晓烟无计色苍茫。","试从檐际偷舒眼，大块何曾有主张。"]},{"t":"山居十首 其七","f":"七言律诗","c":["有客篮舆破早霜，寻僧访道意偏长。","逢人但问葛洪子，觌面难酬粉署郎。","衰柳几时曾浅碧，寒花今日且深黄。","青山白水看容易，猿叫阴风送夕阳。"]},{"t":"山居十首 其八","f":"七言律诗","c":["万顷湖光入镜楼，四窗虚豁水天秋。","短墙砌绕围黄独，长径松高映绿畴。","山雨欲来封蚁穴，溪风骤至起龙湫。","夜长一觉鸡初报，再理重衾倚白头。"]},{"t":"山居十首 其九","f":"七言律诗","c":["山居遮莫厌长贫，尽日逢人但任真。","云散密林关不住，泉分远涧漏还频。","芰荷花发犹当曙，梅蕊香舒未是春。","谁道塞鸿南度远，澌流已到玉门津。"]},{"t":"山居十首 其十","f":"七言律诗","c":["历尽风烟好住山，满林丛棘不须关。","白开高顶松花瘦，红脱孤崖枫叶閒。","倚树微吟寒始觉，绕空长啸老成顽。","万峰重叠知深浅，莫守层阴误鹤还。"]},{"t":"送伦太守归里","f":"七言律诗","c":["一帆寒色动边霜，万里归人向夕阳。","无意马嘶芳草白，有情雁叫菊花黄。","渊明岂为思田里，疏广何曾薄帝乡。","自是此身将隐矣，聊倾沧海濯行藏。"]},{"t":"伦公备述去志未免有怀再赋二章 其一","f":"七言律诗","c":["百年前后事荒唐，业运常迁智者伤。","客散且嬴身易退，位高犹觉世难忘。","是非何定三人易，宠辱同归一梦长。","他时闻道堪朝夕，灵鹫尼山两不妨。"]},{"t":"伦公备述去志未免有怀再赋二章 其二","f":"七言律诗","c":["黄金难赎东隅失，白发徒增逝水悲。","学道不辞违世早，成名应畏去官迟。","浔江沽酒移舟处，峡涧探泉坐石时。","话尽今宵君且去，春花秋叶一相思。"]},{"t":"送杨以贞文学","f":"七言律诗","c":["乱馀江海一儒生，如雪肝肠不世情。","贫贱只今无鲍叔，死生终古有程婴。","一身为友唯徇谊，万里离家岂近名。","月夕风晨知己在，升沉谁复问前程。"]},{"t":"重阳先一日文日送白菊命行者和茗稍觉后时戏作","f":"七言律诗","c":["明朝九日应无事，抚景书怀定有诗。","且趁此时风日丽，不妨先赴菊花期。","堂僧喜供霜英早，行者慵烹玉液迟。","更待登高人兴发，茗杯山果共追随。"]},{"t":"辛酉九日","f":"七言律诗","c":["萧条人事逢佳节，云净天高景倍生。","落帽几人羞短发，繁霜空自对寒英。","愁飘红叶减山色，爱耸青松听鹤声。","岁岁茱萸看不尽，江帆溪月此时情。"]},{"t":"秋杪偶成","f":"七言律诗","c":["老去临秋叹往年，罗浮丹岫草芊芊。","餐英自惜篱花晚，落叶空怜梅蕊先。","指点风光还景物，悠扬空阔对山川。","遐心一往成宵旦，半掩柴关万壑前。"]},{"t":"秋杪夜坐","f":"七言律诗","c":["滚滚江流无尽期，关关林鸟欲何为。","馀生总是艰难日，胜事难追少壮时。","赖有黄花留岁月，无劳萱草解忧疑。","遐心一往凭谁问，坐落寒更山月移。"]},{"t":"初冬示玉泉侍者","f":"七言律诗","c":["不信吾宗竟陆沉，梅花初绽雪霜侵。","庚辰已办终焉计，甲午还寻夙昔心。","双树尚零金椁泪，孤桐难续峄阳音。","乘桴浮海谁从我，俯仰云霄可自任。"]},{"t":"净成上老父供阻雪十日二首 其一","f":"七言律诗","c":["隔溪有路通幽处，望见松门别一天。","因展先容归故隐，独登煖榻恋深禅。","寒林扫叶煨牛火，乱砌寻源引竹泉。","雪久地炉生事拙，焚香重理杂华篇。"]},{"t":"净成上老父供阻雪十日二首 其二","f":"七言律诗","c":["雨雪濛濛天地昏，指中马外眼前存。","远思几处未归客，近对何人可共论。","浩浩风传新水碓，皑皑砌绕旧蔬园。","此时此际成孤赏，独拥寒襟深闭门。"]},{"t":"送刘别驾莘叟赍捧入京兼寄少司农刘默庵","f":"七言律诗","c":["功曹转运忽三年，话别秋阴山月圆。","圣母更劳上寿表，故人重写赠行篇。","一官尽瘁忘霜鬓，万里关心共雪天。","为问侍郎相忆否，乱离去住两茫然。"]},{"t":"思过示诸衲","f":"七言律诗","c":["尼山有过幸人知，我又何人敢自欺。","功罪已明应共见，是非终定不须疑。","莲花出水非今日，柳叶随风惜往时。","一回提起惭何极，愿汝诸贤自得师。"]},{"t":"自慰","f":"七言律诗","c":["道衰无侣莫徘徊，生死如环任去来。","两袖龙钟人共弃，一双黑白眼常开。","先贤鼻孔还华藏，后学乖离付劫灰。","俯仰只今吾老矣，兴酣长啸上高台。"]},{"t":"岁晏","f":"七言律诗","c":["岁晏今年似去年，朔风吹断雁行偏。","关心岐路知多日，斫额长空叹暮天。","白首岂堪同壮志，青春终欲逊时贤。","檐前积雪千峰晓，一盏寒灯夜不眠。"]},{"t":"早春周赞皇郡丞携二子并吕胡两文学见访","f":"七言律诗","c":["因缘今现宰官身，须忆然灯共记人。","不信三生逢石上，何期千里到溪滨。","陪欢嘉客丰年玉，接武贤郎圣世珍。","情洽岂辞归马晚，云山从此往来频。"]},{"t":"寄雪悟禅师","f":"七言律诗","c":["忻逢空谷竟忘年，回首鸾溪在目前。","阅世暂浮沧海远，避人终逐草堂偏。","凋伤骨肉难为老，俯仰云山只是禅。","千里肯同牛粪火，数行应为巨灵先。"]},{"t":"春日送许逸林明府行取入京","f":"七言律诗","c":["几年民瘼赖谁求，邑有神君四境休。","百里津梁无斥堠，三春风雨足田畴。","升闻自是铨衡事，子惠殊为闾井忧。","入对更祈陈利病，野人斫额祝安流。"]},{"t":"二月醉梅","f":"七言律诗","c":["二月寻梅树树空，一株台畔最玲珑。","开经雨雪香犹在，看到晴明色较浓。","向人不欲全舒白，止酒何妨稍著红。","花信过时难入俗，疑醒疑醉付东风。"]},{"t":"哭阿字无子二首 其一","f":"七言律诗","c":["珠江绝袂几伤神，千里归山尚早春。","离合分明今日事，行藏谁定刹尘身。","失群鸿雁高飞急，背水将军转战频。","力尽势穷还法运，一条直路出风尘。"]},{"t":"哭阿字无子二首 其二","f":"七言律诗","c":["法界何曾有短长，长生路上见参商。","馀年频送春花落，掩室都忘秋叶黄。","万里寒空人寂寂，千峰残月晓苍苍。","箜篌妙指无宵昼，却教门庭事更忙。"]},{"t":"掩关净成玉泉入候未见而返次日呈诗即用其韵答之","f":"七言律诗","c":["几岁纡回峡涧东，相随杖屦日从容。","山莺一任啼朝树，岸柳何因掩暮峰。","春露已沾新绿湿，夏云偏指旧溪封。","无门有路通霄汉，倚立堂阶隔万重。"]},{"t":"虔州郡丞董昭时南康郡丞周赞皇都阃徐质美见访因病掩关不得出迓走笔以谢","f":"七言律诗","c":["并辔寻源访隐沦，千峰依旧可怜春。","曾陪石上惭知我，未识荆州愧病身。","暂借溪山为举似，尚留面目忆前因。","解空已到休弹指，何待他年再问津。"]},{"t":"偶作","f":"七言律诗","c":["取信于心何所事，穿牛落马总徒然。","千波竞发随高下，一亘晴空绝后先。","看去牡丹春已老，移将莲萼夏初妍。","目前生计些些子，留与云山作话传。"]},{"t":"刘别驾莘叟入山","f":"七言律诗","c":["万里王程归永日，纷纷竹马迓湖东。","城头峰出鸟飞外，谷口云封僧病中。","深棘旧寻三径在，断金难隔二人同。","尚期把臂秋山早，覆我寒襟共朔风。"]},{"t":"秋夕关中","f":"七言律诗","c":["万里河山夜不收，西风初报井梧秋。","江豚吹浪云归岳，社燕辞巢月满楼。","光景不殊今昔异，道心如醉水天浮。","关中消息堪长啸，啸指浔阳沙际鸥。"]},{"t":"纪梦","f":"七言律诗","c":["无端身在碧巃穹，俗气惭登法座隆。","绿鸭江升三十万，慈云阁上最高空。","梵音直透青霄外，衣袖逍遥白日中。","龙象几人还有约，他年无负与心同。"]},{"t":"纪梦诗成后再赋一章","f":"七言律诗","c":["寄迹尘寰岂异尘，因随流布幻中真。","痴心尚有无穷愿，业运徒迁有限身。","梦去总皆天上事，病来难恋眼前人。","但知法界无由入，尽此馀生且莫陈。"]},{"t":"彭少参眉白同檗庵道者入山","f":"七言律诗","c":["万里王程暂驻鞍，峡峤深处足盘桓。","题名华藏非容易，解组黄虞却较难。","自是鹅王能择乳，还他雁塔且弹冠。","同行况有无为子，塞雪燕云莫畏寒。"]},{"t":"关中七月念九日早起","f":"七言律诗","c":["蟪蛄切切动秋声，积雨今朝喜暂晴。","宿雾顿捐初日净，晓烟如洗万峰明。","鹤离松顶惊巢鸟，僧踏溪头向郡城。","閒倚南楼一长啸，不知身世欲何成。"]},{"t":"中秋病起与诸子玩月二首 其一","f":"七言律诗","c":["万里湖光夜气清，病馀秋色倍分明。","青山皓洁看同世，碧汉孤悬最有情。","掩映云中纡短景，悠扬空外霁长更。","今宵且喜群英共，不信萝庵梦几生。"]},{"t":"中秋病起与诸子玩月二首 其二","f":"七言律诗","c":["百年几度共中秋，回首悲欢付海鸥。","蟾桂不停乌鹊影，川原高举白云头。","寒空远鉴千峰衲，暖席横吹万户侯。","莫倚清贫傲当世，一般晴霁入双眸。"]},{"t":"王昌侯观察过访","f":"七言律诗","c":["有客寻僧过峡桥，西风微雨马蹄骄。","一丘已谢閒名久，三径忽传佳气飘。","青草何嫌临玉节，绿杨偏欲系金镳。","病馀还有清谈兴，不觉龙钟白发饶。"]},{"t":"九日同尘异登双镜楼","f":"七言律诗","c":["瑟瑟西风万窍号，危楼盼望意如何。","百年担荷归吾党，一日承欢喜尔曹。","发白不妨人共弃，眼青未许岳争高。","萧条草木秋将晚，珍重鸣阴出九皋。"]},{"t":"闻非影病馀干","f":"七言律诗","c":["频年添钵病人间，耐尽长途秋未还。","无限关心劳梦寐，那堪传语越江山。","药炉宿火同人少，旅舍新寒独夜閒。","最是迢迢烟路远，相思不觉惨颓颜。"]},{"t":"秋杪病起得岭南耗","f":"七言律诗","c":["山斋深掩避新寒，炉火初红夕照残。","坐听天风知雁急，病馀鹤骨见衣宽。","五岭招魂无宋玉，千峰卧雪有袁安。","百情未尽悲何极，自觉年来梦已删。"]},{"t":"玉泉呈雁字诗","f":"七言律诗","c":["不分气序却知寒，但到西风便入关。","长幼后先谙物性，纵横点画落人间。","观穷玄象踪应没，影印空潭榻亦难。","斜抹太虚惊绝笔，如虫偶尔莫成顽。"]},{"t":"尘异献菊","f":"七言律诗","c":["寂寞秋山百卉残，谁将霜质傍阑干。","元亮东篱徒酩酊，侏儒玉笥费盘桓。","把茗共餐知味苦，移床独对爱香寒。","自惭傲骨同幽逸，聊作吾门晚节看。"]},{"t":"答张文学二首 其一","f":"七言律诗","c":["閒名久谢掩青山，独足峰头指顾间。","正讶马蹄喧石磴，忽闻鸟语响柴关。","故人茂叔能重到，生客敬夫也共攀。","流水白云陪色笑，将知尘世有时閒。"]},{"t":"答张文学二首 其二","f":"七言律诗","c":["何劳车马到深山，久绝虚名落世间。","文章岂贵洛阳纸，道德空传函谷关。","入手明珠争照耀，插天岱岳绝跻攀。","从来国士酬知己，不信林泉尽日閒。"]},{"t":"雪中上净成","f":"七言律诗","c":["一病沉沉夏复秋，已将身世等蜉蝣。","盘空未尽千峰势，坐石重看三峡流。","恩大难酬尘刹愿，道衰徒负几人忧。","波波揭揭成何事，冒雪还应到上头。"]},{"t":"寿伦太守","f":"七言律诗","c":["罢官江海得优游，更欲翱翔上国游。","林麓尽多閒岁月，身心无限可绸缪。","豪华易尽谁堪托，甲子难教再一周。","酒醒试思寒夜后，光阴如箭雪盈头。"]},{"t":"谢君章郡丞入山","f":"七言律诗","c":["洪都司马署黄堂，地控湖山过石梁。","松下襜帷纡仄径，云中飞盖掩斜阳。","白莲有社惭非主，黄独煨寒笑大方。","不弃龙钟垂顾盼，长林丰草尽生光。"]},{"t":"长至书怀","f":"七言律诗","c":["短景才添一缕长，北风吹雪限津梁。","寒江想见归帆影，落日徒嗟去雁行。","虑重自知成老态，道孤谁信为人忙。","朝烟夕雾终何极，举目云山谩度量。"]},{"t":"壬戌除夕","f":"七言律诗","c":["雪月霜风岁岁同，溪南山北有无中。","目前秖是劳生事，梦后谁论造化功。","送腊梅花寒已彻，迎春椒叶气初融。","人间此夕忙如市，依旧明朝日出东。"]},{"t":"送许太守浣月归养","f":"七言律诗","c":["郡斋如水一閒身，拜表辞官为老亲。","家有田园堪仰事，船兼琴鹤莫忧贫。","山楼看月思玄度，道路攀车借寇恂。","归去庭帏多乐事，板舆佳话又重新。"]},{"t":"柬南雄太守李廷标","f":"七言律诗","c":["回思十载雄州事，轩冕麻衣去住心。","寒暑不侵松鹤羽，溪山长隔岭云音。","一枝深树翔初集，满腹洪流饮已深。","两地月明知共照，乘风聊寄白头吟。"]},{"t":"癸亥除夕","f":"七言律诗","c":["一岁光阴馀此夕，千门梅柳接新年。","人心寂寞同山水，世故推迁有后先。","知见欲留徒叹逝，身名如幻惜生前。","纵观衰变谁堪觉，独抱寒襟问古仙。"]},{"t":"春日送周赞皇郡丞","f":"七言律诗","c":["万里驰驱上表章，春风摇曳趁长杨。","去时望阙从江右，来日携家出建康。","京邸凤雏初比翼，湖中雁字欲成行。","黄花满径频相待，再见千峰话夕阳。"]}]};